/* =====================================================================
   Подкидной дурак — правила партии и отрисовка стола.

   Файл намеренно разделён на две части:
     ЧАСТЬ 1 «Правила» — работают только с объектом состояния «партия»,
             про экран и про кнопки ничего не знают. Их можно прогнать
             без браузера (автотест «бот против бота»);
     ЧАСТЬ 2 «Экран»  — по состоянию партии рисует картинку целиком,
             своих правил не придумывает.

   Разделение нужно, чтобы ошибку было видно сразу: если карта ушла
   не туда — это часть 1, если карта не там нарисовалась — часть 2.
   ===================================================================== */

'use strict';

/* =====================================================================
   ЧАСТЬ 1. ПРАВИЛА ПАРТИИ
   ===================================================================== */

const МАСТИ = ['♠', '♥', '♦', '♣']; // пики, черви, бубны, трефы
const КРАСНЫЕ_МАСТИ = ['♥', '♦'];

/* Колод у игры две. На двоих-четверых играют привычной колодой в 36 карт
   (от шестёрки до туза). На пятерых-шестерых её не хватает: шестеро по шесть
   карт — это ровно 36, вся колода уходит в раздачу, козырной карте взяться
   неоткуда и добирать нечем. Поэтому с пяти игроков берём колоду в 52 карты —
   те же масти, только младших карт больше (двойки, тройки, четвёрки, пятёрки).

   Достоинства перечислены по возрастанию, а вес карты — её место в списке
   плюс два. Так шестёрка весит 6 в любой колоде, и старшинство карт
   от размера колоды не зависит вовсе. */
const ВСЕ_ДОСТОИНСТВА = ['2', '3', '4', '5', '6', '7', '8', '9', '10', 'В', 'Д', 'К', 'Т'];
const КОЛОДА_36 = 36;
const КОЛОДА_52 = 52;
const МЛАДШЕЕ_В_КОЛОДЕ_36 = '6';

/** Достоинства выбранной колоды: у большой — все, у обычной — от шестёрки. */
function достоинстваКолоды(размерКолоды) {
  if (размерКолоды === КОЛОДА_52) return ВСЕ_ДОСТОИНСТВА.slice();
  return ВСЕ_ДОСТОИНСТВА.slice(ВСЕ_ДОСТОИНСТВА.indexOf(МЛАДШЕЕ_В_КОЛОДЕ_36));
}

// Достоинства обычной колоды. Отдаются наружу ради проверок и старого кода,
// который про большую колоду ещё не знает.
const ДОСТОИНСТВА = достоинстваКолоды(КОЛОДА_36);

const КАРТ_В_РУКЕ = 6;          // до скольки карт добирают из колоды
const МАКС_КАРТ_В_ПОДХОДЕ = 6;  // больше шести карт за один подход не кладут

/* Сколько человек может сесть за стол. Двое — это не отдельная игра,
   а самый маленький круг: правила ниже написаны для круга любого размера,
   и на двоих они сами собой сворачиваются в привычную игру «один ходит,
   второй отбивается». */
const МИН_ИГРОКОВ = 2;
const МАКС_ИГРОКОВ = 6;
const ПОРОГ_БОЛЬШОЙ_КОЛОДЫ = 5;   // с пяти игроков играем колодой в 52 карты

/* Две необязательные разновидности игры. Обе по умолчанию выключены: без них
   партия идёт ровно так же, как шла всегда, — это нарочно, чтобы привычная
   игра с ботом и по сети не изменилась ни на йоту.

   «Переводной» ({ переводной: true }) — отбивающийся вместо того, чтобы крыть,
   кладёт карту того же достоинства, что уже лежит на столе, и отбиваться
   приходится следующему по кругу. Подробности — у функции «можноПеревести».

   «Парами» ({ парами: true }) — игра двое на двоих, партнёры сидят через
   одного. Подробности — у функции «партнёр». */
const ИГРОКОВ_В_ПАРАХ = 4;        // игра парами бывает только вчетвером

/* Имена мест за столом. Первые два нарочно оставлены прежними: на слова
   «человек» и «бот» завязаны игра с ботом, сервер игры вдвоём и все
   накопленные проверки. Кто садится на место — живой человек или робот —
   правилам всё равно, это решает тот, кто создаёт партию. */
const ИМЕНА_МЕСТ = ['человек', 'бот', 'бот-3', 'бот-4', 'бот-5', 'бот-6'];

// Уровни соперника. Эти же слова показываются в меню и попадают в таблицу рекордов.
const СЛОЖНОСТИ = ['лёгкий', 'обычный', 'сложный'];
const СЛОЖНОСТЬ_ПО_УМОЛЧАНИЮ = 'обычный';

/** Незнакомое слово превращаем в «обычный», чтобы игра не зависела от опечатки. */
function проверитьСложность(значение) {
  return СЛОЖНОСТИ.indexOf(значение) !== -1 ? значение : СЛОЖНОСТЬ_ПО_УМОЛЧАНИЮ;
}

/**
 * Собрать полную колоду нужного размера (36 или 52 карты; без указания — 36).
 * Вес — число от 2 до 14, по нему сравниваем карты: так не нужно каждый раз
 * искать достоинство в списке.
 */
function собратьКолоду(размерКолоды) {
  const достоинства = достоинстваКолоды(размерКолоды || КОЛОДА_36);
  const колода = [];
  for (const масть of МАСТИ) {
    for (const имя of достоинства) {
      колода.push({ масть: масть, имя: имя, вес: ВСЕ_ДОСТОИНСТВА.indexOf(имя) + 2 });
    }
  }
  return колода;
}

/** Перетасовать колоду (алгоритм Фишера — Йетса, честное перемешивание). */
function перемешать(колода) {
  for (let i = колода.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const временно = колода[i];
    колода[i] = колода[j];
    колода[j] = временно;
  }
  return колода;
}

/**
 * Карты в руке держим по порядку: сначала некозырные по мастям,
 * козыри — в конце. Нужно только для удобства человека, на правила не влияет.
 */
function упорядочитьРуку(партия, игрок) {
  if (!партия.руки[игрок]) return;   // за таким именем никто не сидит — раскладывать нечего
  партия.руки[игрок].sort(function (а, б) {
    const аКозырь = а.масть === партия.козырь;
    const бКозырь = б.масть === партия.козырь;
    if (аКозырь !== бКозырь) return аКозырь ? 1 : -1;
    if (а.масть !== б.масть) return МАСТИ.indexOf(а.масть) - МАСТИ.indexOf(б.масть);
    return а.вес - б.вес;
  });
}

/** Целое число из настроек; мусор превращается в null, а не в ноль. */
function целоеИлиНичего(значение) {
  const число = Number(значение);
  return Number.isFinite(число) ? Math.floor(число) : null;
}

/**
 * Имена мест за столом. Можно задать числом («посади четверых») или списком
 * своих имён — второе понадобится игре по сети, где места зовут по игрокам.
 *
 * Второй довод — «просят играть парами». Тогда стол по умолчанию на четверых
 * и длиннее четырёх не бывает: игра парами других размеров не знает.
 */
function местаЗаСтолом(настройки, просятПарами) {
  const потолок = просятПарами ? ИГРОКОВ_В_ПАРАХ : МАКС_ИГРОКОВ;
  if (Array.isArray(настройки.игроки)) {
    const свои = настройки.игроки
      .filter(function (имя) { return typeof имя === 'string' && имя.trim() !== ''; })
      .map(function (имя) { return имя.trim(); })
      .filter(function (имя, i, все) { return все.indexOf(имя) === i; });  // повторов быть не должно
    if (свои.length >= МИН_ИГРОКОВ) return свои.slice(0, потолок);
  }
  const сколько = целоеИлиНичего(настройки.игроков) || (просятПарами ? ИГРОКОВ_В_ПАРАХ : МИН_ИГРОКОВ);
  const сколькоВПределах = Math.min(потолок, Math.max(МИН_ИГРОКОВ, сколько));
  return ИМЕНА_МЕСТ.slice(0, сколькоВПределах);
}

/**
 * Какой колодой играем. По умолчанию решает число игроков: до четверых —
 * привычные 36 карт, с пяти — 52. Просьбу взять другую колоду выполняем,
 * только если карт хватит на раздачу и ещё останется козырная под колодой.
 */
function выбратьРазмерКолоды(сколькоИгроков, желаемый) {
  const поЧислуИгроков = сколькоИгроков >= ПОРОГ_БОЛЬШОЙ_КОЛОДЫ ? КОЛОДА_52 : КОЛОДА_36;
  if (желаемый !== КОЛОДА_36 && желаемый !== КОЛОДА_52) return поЧислуИгроков;
  return желаемый > сколькоИгроков * КАРТ_В_РУКЕ ? желаемый : поЧислуИгроков;
}

/**
 * Разобрать настройки партии. Раньше сюда передавали одну строку — уровень
 * соперника, и так до сих пор делают игра с ботом, сервер и все проверки.
 * Поэтому строка (и вообще что угодно, кроме объекта) означает ровно то же,
 * что и раньше: двое игроков, колода 36, названный уровень.
 */
function разобратьНастройки(настройки) {
  const этоНабор = Boolean(настройки) && typeof настройки === 'object' && !Array.isArray(настройки);
  const набор = этоНабор ? настройки : {};
  const просятПарами = набор.парами === true;
  const игроки = местаЗаСтолом(набор, просятПарами);
  return {
    сложность: проверитьСложность(этоНабор ? набор.сложность : настройки),
    игроки: игроки,
    размерКолоды: выбратьРазмерКолоды(игроки.length, целоеИлиНичего(набор.колода)),
    // Разновидности включаются только словом «да» и только из набора настроек:
    // строка-уровень («сложный») никогда не должна случайно включить режим.
    переводной: набор.переводной === true,
    // Парами играют строго вчетвером. Если за столом собралось другое число
    // игроков, просьбу выполнить нечем — играем обычную партию, а не наполовину
    // парную: половинчатые правила хуже, чем понятные привычные.
    парами: просятПарами && игроки.length === ИГРОКОВ_В_ПАРАХ
  };
}

/**
 * Новая партия: тасуем колоду, раздаём по 6 карт, козырь — последняя карта
 * колоды (она лежит под колодой и достаётся последней).
 *
 * Довод — либо уровень соперника строкой (как было всегда), либо набор
 * настроек: { сложность, игроков: 2…6, игроки: [имена], колода: 36 или 52,
 * переводной: true, парами: true }. Обе разновидности по умолчанию выключены.
 */
function создатьПартию(настройки) {
  const выбор = разобратьНастройки(настройки);
  const колода = перемешать(собратьКолоду(выбор.размерКолоды));
  const козырнаяКарта = колода[колода.length - 1];

  const партия = {
    сложность: выбор.сложность,     // каким соперником играет бот
    игроки: выбор.игроки,           // места за столом по кругу, по часовой стрелке
    переводной: выбор.переводной,   // разрешено ли переводить ход картой того же достоинства
    парами: выбор.парами,           // играем ли двое на двоих
    проигравшие: [],                // кто остался дураком: один игрок, а в игре парами — оба из пары
    выбывшие: [],                   // кто остался без карт при пустой колоде и вышел из партии
    размерКолоды: выбор.размерКолоды,
    колода: колода,                 // колода[0] — верхняя карта, последняя — козырная
    козырь: козырнаяКарта.масть,
    козырнаяКарта: козырнаяКарта,
    руки: {},                       // на каждое место — свой список карт
    стол: [],                       // список пар { атака: карта, защита: карта или null }
    отбой: [],                      // сюда уходят отбитые карты
    атакует: выбор.игроки[0],
    /* Кто в этом подходе уже сказал «больше не подкидываю». Отказ держится
       до конца подхода, и забываем его ровно в одном месте — когда подход
       закончился и стол убрали (см. «завершитьПодход»). Ни новая карта
       на столе, ни новое достоинство, ни «Беру» отказ не отменяют: так
       ответил владелец игры, и так же играют за столом — сказал «пас»,
       значит молчишь до конца подхода. */
    пасы: [],
    берёт: false,                   // защищающийся сказал «Беру»
    завершена: false,
    // Имя дурака, либо 'ничья'. В игре парами — оба имени через « и »:
    // читать итог по одному имени там нечего, дурак не человек, а пара.
    результат: null
  };

  // Раздаём по одной карте по кругу, как в жизни.
  for (const имя of партия.игроки) партия.руки[имя] = [];
  for (let i = 0; i < КАРТ_В_РУКЕ; i++) {
    for (const имя of партия.игроки) партия.руки[имя].push(партия.колода.shift());
  }
  партия.атакует = ктоХодитПервым(партия);
  упорядочитьРуку(партия, партия.игроки[0]);
  return партия;
}

/** Самый младший козырь в руке (или null, если козырей нет). */
function младшийКозырь(партия, игрок) {
  let младший = null;
  for (const карта of партия.руки[игрок]) {
    if (карта.масть !== партия.козырь) continue;
    if (младший === null || карта.вес < младший.вес) младший = карта;
  }
  return младший;
}

/**
 * Первым ходит тот, у кого младший козырь за всем столом.
 * Козырей нет ни у кого — ходит тот, кто сидит первым.
 */
function ктоХодитПервым(партия) {
  let первый = партия.игроки[0];
  let младший = null;
  for (const имя of партия.игроки) {
    const козырь = младшийКозырь(партия, имя);
    if (!козырь) continue;
    if (младший === null || козырь.вес < младший.вес) {
      младший = козырь;
      первый = имя;
    }
  }
  return первый;
}

/* ---------------------------------------------------------------------
   Круг игроков. Здесь собрано всё, что отвечает на два вопроса:
   «кто отбивается» и «кому переходит ход». Ради этого они и живут
   в одном месте: в переводном дураке и в игре парами меняются
   именно эти два ответа, а остальные правила остаются прежними.
   --------------------------------------------------------------------- */

/** Играет ли этот игрок ещё — или уже вышел, оставшись без карт. */
function вИгре(партия, игрок) {
  return !партия.выбывшие || партия.выбывшие.indexOf(игрок) === -1;
}

/** Все, кто ещё в партии, в порядке мест за столом. */
function оставшиеся(партия) {
  return партия.игроки.filter(function (имя) { return вИгре(партия, имя); });
}

/** Обойти круг начиная с этого места; выбывших пропускаем — их за столом уже нет. */
function поКругуОт(партия, откого) {
  const места = партия.игроки;
  const начало = места.indexOf(откого);
  const круг = [];
  for (let шаг = 0; шаг < места.length; шаг++) {
    const имя = места[((начало === -1 ? 0 : начало) + шаг) % места.length];
    if (вИгре(партия, имя)) круг.push(имя);
  }
  return круг;
}

/** Следующий по кругу за этим местом. Вдвоём это просто второй игрок. */
function следующийВКруге(партия, откого) {
  const круг = поКругуОт(партия, откого);
  if (круг.length === 0) return откого;          // все вышли, партия и так окончена
  return круг[0] === откого ? (круг[1] || откого) : круг[0];
}

/**
 * Партнёр этого игрока в игре парами — тот, кто сидит через одного, напротив:
 * первый с третьим, второй с четвёртым. Вне игры парами партнёров нет
 * ни у кого, поэтому ответ — null.
 *
 * Партнёрство считается по местам за столом, а не по остатку игроков:
 * даже если напарник уже вышел без карт, он остаётся напарником, и подкидывать
 * ему по-прежнему нельзя — просто подкидывать уже нечего.
 */
function партнёр(партия, игрок) {
  if (!партия.парами) return null;
  const место = партия.игроки.indexOf(игрок);
  if (место === -1) return null;
  return партия.игроки[(место + 2) % партия.игроки.length];
}

/**
 * Это он сам или его напарник? Короткий вопрос, который правила ниже задают
 * трижды: кому не ходят, кому не подкидывают и кто с кем проигрывает.
 * Вне игры парами напарников нет, поэтому ответ «да» — только про самого себя,
 * и все правила сворачиваются в прежние.
 */
function самИлиНапарник(партия, кто, другой) {
  return кто === другой || партнёр(партия, кто) === другой;
}

/**
 * Кто отбивался бы, если бы ходил названный игрок. Вопрос вынесен отдельно,
 * потому что его задают дважды: про нынешнего атакующего — постоянно,
 * а перевод спрашивает заранее: «кому достанется защита, если я переведу?».
 *
 * В игре парами ответ отличается одним: своему партнёру не ходят. Если сосед
 * по кругу — напарник (такое бывает, когда соперник между ними уже вышел
 * без карт), его пропускаем и отбиваться зовём следующего соперника.
 */
function ктоОтбиваетсяЗа(партия, атакующий) {
  if (!партия.парами) return следующийВКруге(партия, атакующий);
  for (const имя of поКругуОт(партия, атакующий)) {
    if (!самИлиНапарник(партия, атакующий, имя)) return имя;
  }
  return атакующий;   // за столом остались одни напарники — партия уже кончена
}

/** Кто сейчас отбивается — следующий по кругу за тем, кто ходит. */
function защищается(партия) {
  return ктоОтбиваетсяЗа(партия, партия.атакует);
}

/**
 * Кому разрешено подкидывать и в каком порядке: сначала тот, кто ходил,
 * дальше по кругу. Отбивающийся себе не подкидывает, поэтому его в списке нет.
 * Вдвоём в списке остаётся один игрок — тот, кто ходит.
 *
 * В игре парами из списка выпадает ещё и напарник отбивающегося: подкидывают
 * только соперники. Иначе пара топила бы сама себя — карты партнёра для неё
 * такие же свои, как собственные.
 */
function подкидывающие(партия) {
  const защитник = защищается(партия);
  return поКругуОт(партия, партия.атакует).filter(function (имя) {
    return !самИлиНапарник(партия, защитник, имя);
  });
}

/**
 * Может ли этот игрок положить карту в атаку прямо сейчас.
 *
 * Главное здесь — очередь. Подкидывают по одному и строго по кругу: первым
 * говорит тот, кто ходил, и пока он не сказал «больше не подкидываю», никто
 * другой карту положить не может. Сказал — слово переходит следующему
 * по кругу, и уже он один вправе подкинуть.
 *
 * Раньше очередь считалась (см. «ктоХодит»), но право класть карту её
 * не спрашивало: подкинуть мог любой и в любой миг. Живой игрок это заметил
 * первым — он заходил шестёрками, а соседи наваливали карты через его голову.
 *
 * Вдвоём подкидывающий один, слово всегда его — там ничего не меняется.
 */
function можетПодкидывать(партия, игрок) {
  // Вышедшему из игры и после конца партии класть карты нельзя никому.
  if (партия.завершена || !вИгре(партия, игрок)) return false;
  // Первую карту подхода кладёт только тот, чей ход: подкидывать ещё не к чему.
  if (партия.стол.length === 0) return игрок === партия.атакует;
  // Нельзя класть карту ни отбивающемуся, ни (в игре парами) его напарнику.
  if (самИлиНапарник(партия, защищается(партия), игрок)) return false;
  /* Очередь есть только там, где подкидывают: пока на столе лежит неотбитая
     карта, ждут отбивающегося, и очередь подкидывания ещё не началась —
     класть карту в это время всё равно не даст «можноПоложить».

     ВАЖНО ДЛЯ ТЕХ, КТО ЧИТАЕТ ОТВЕТ СНАРУЖИ. В фазе защиты ответ «да» значит
     только «этому игроку подкидывать не запрещено вообще», а не «он может
     положить карту прямо сейчас»: сейчас не может никто, идёт защита.
     Ответ верен как разрешение ровно в двух фазах — «подкидывание»
     и «докидывание». Поле «могуПодкинуть», которое сервер отдаёт игроку,
     берётся отсюда, и опираться на него можно только в этих двух фазах.
     Отвечать «нет» в защите нарочно не стали: сервер по этому же ответу
     выбирает слова отказа и сказал бы не отбивающемуся «вы сейчас
     отбиваетесь» — то есть заменил бы неточное поле неверными словами. */
  const текущая = фаза(партия);
  if (текущая !== 'подкидывание' && текущая !== 'докидывание') return true;
  return ктоХодит(партия) === игрок;
}

/**
 * Что сейчас происходит за столом. Фазу не храним, а вычисляем по столу —
 * тогда её невозможно «забыть переключить» и получить зависание.
 *   'атака'       — стол пуст, атакующий должен положить карту;
 *   'защита'      — на столе есть неотбитая карта, ход защищающегося;
 *   'подкидывание'— всё отбито, атакующий может подкинуть или сказать «Бито»;
 *   'докидывание' — защищающийся берёт, атакующий может докинуть карты;
 *   'конец'       — партия окончена.
 */
function фаза(партия) {
  if (партия.завершена) return 'конец';
  if (партия.стол.length === 0) return 'атака';
  if (партия.берёт) return 'докидывание';
  for (const пара of партия.стол) {
    if (!пара.защита) return 'защита';
  }
  return 'подкидывание';
}

/**
 * Найдётся ли у игрока карта, которую прямо сейчас разрешено подкинуть.
 * Считаем честно, по столу: подкидывают только тем достоинством, которое
 * на столе уже лежит, и только пока стол не упёрся в потолок.
 */
function найдётсяЧемПодкинуть(партия, игрок) {
  const рука = партия.руки[игрок] || [];
  for (const карта of рука) {
    if (можноПоложить(партия, карта)) return true;
  }
  return false;
}

/**
 * Ждём ли мы слова от этого игрока. Не ждём двоих: того, кто уже сказал
 * «больше не подкидываю», и того, кому подкинуть просто нечем — его ответ
 * известен заранее по картам, и спрашивать его значит зря дёргать человека
 * кнопкой, которую можно нажать только одним способом.
 *
 * Этой же меркой пользуется «пас», и это важно: разойдись они хоть на шаг —
 * один ждал бы слова от того, кого другой уже пропустил, и подход завис бы.
 */
function ждётСлова(партия, игрок) {
  if (ужеСпасовал(партия, игрок)) return false;
  return найдётсяЧемПодкинуть(партия, игрок);
}

/**
 * Сказал ли игрок «больше не подкидываю» в этом подходе.
 *
 * Отдельная мерка нужна, чтобы отказ значил одно и то же везде: слово такого
 * игрока пропускают целиком — и когда спрашивают, кто подкинет, и когда ищут,
 * кому закрывать подход (см. «ктоХодит»). Сказал «пас» — до конца подхода
 * тебя не спрашивают больше ни о чём.
 *
 * Стол пуст — значит подхода ещё нет и отказы прошлого подхода не в счёт.
 */
function ужеСпасовал(партия, игрок) {
  const пасы = партия.пасы || [];
  return партия.стол.length > 0 && пасы.indexOf(игрок) !== -1;
}

/**
 * Чьё сейчас слово: имя игрока или null, если партия окончена.
 * В подкидывании и докидывании право высказаться обходит по кругу всех,
 * кому разрешено подкинуть: сказавших «больше не подкидываю» и тех, кому
 * подкинуть нечем, пропускаем.
 * Вдвоём подкидывающий один, поэтому очередь всегда возвращается к нему —
 * ровно как было до появления круга.
 *
 * КТО ЗАКРЫВАЕТ ПОДХОД, когда подкинуть больше некому. Кто-то один должен
 * сказать «Бито», иначе стол так и будет лежать. Раньше это слово всегда
 * возвращалось к тому, кто ходил, — и на этом партия у живых игроков встала
 * намертво. Случай был такой: ходивший сказал «Пас» ещё в подкидывании,
 * дальше подкидывал сосед, защитник сказал «Беру», подкинуть стало нечем
 * никому — и слово вернулось к тому, кто уже спасовал. Карту он класть
 * не вправе (отказ держится до конца подхода), и всё, что ему остаётся, —
 * формально нажать «Пас» второй раз. Пока он этого не сделал, за столом
 * не может сходить никто; а у него на телефоне была старая страница, где
 * такому игроку кнопку и вовсе не показывали. Партия не сдвинулась совсем.
 *
 * Поэтому закрывает подход первый по кругу, кто ещё НЕ отказывался. Так
 * выходит и по правилу владельца: сказал «пас» — до конца подхода тебя
 * больше не спрашивают, ни первым вопросом, ни вторым. Одного нажатия
 * по-прежнему хватает: «пас» сам видит, что ждать больше некого,
 * и заканчивает подход.
 *
 * Последний запасной ответ — тот, кто ходил. Досюда доходит только если
 * отказались вообще все, а такого положения в живой партии не бывает:
 * отказ последнего из круга сам закрывает подход (см. «пас»). Пусть
 * останется на случай, если правила когда-нибудь поменяют круг посреди
 * подхода: слово должно быть у кого-то всегда.
 */
function ктоХодит(партия) {
  const текущая = фаза(партия);
  if (текущая === 'конец') return null;
  if (текущая === 'защита') return защищается(партия);
  if (текущая === 'атака') return партия.атакует;
  for (const имя of подкидывающие(партия)) {
    if (ждётСлова(партия, имя)) return имя;
  }
  for (const имя of подкидывающие(партия)) {
    if (!ужеСпасовал(партия, имя)) return имя;   // подход закроет тот, кто ещё молчал
  }
  return партия.атакует;
}

/** Бьёт ли карта «чем» карту «что»: старше той же масти либо козырь по некозырю. */
function бьёт(чем, что, козырь) {
  if (чем.масть === что.масть) return чем.вес > что.вес;
  return чем.масть === козырь && что.масть !== козырь;
}

/** Сколько карт на столе ещё не отбито. */
function неотбитых(партия) {
  let счёт = 0;
  for (const пара of партия.стол) if (!пара.защита) счёт++;
  return счёт;
}

/** Достоинства всех карт на столе — только ими разрешено подкидывать. */
function достоинстваНаСтоле(партия) {
  const список = [];
  for (const пара of партия.стол) {
    if (список.indexOf(пара.атака.имя) === -1) список.push(пара.атака.имя);
    if (пара.защита && список.indexOf(пара.защита.имя) === -1) список.push(пара.защита.имя);
  }
  return список;
}

/**
 * Можно ли сейчас положить эту карту в атаку.
 * Два ограничения: не больше шести карт за подход и не больше,
 * чем карт в руке у того, кто отбивается (иначе ему нечем крыть).
 */
function можноПоложить(партия, карта) {
  const текущая = фаза(партия);
  if (текущая !== 'атака' && текущая !== 'подкидывание' && текущая !== 'докидывание') return false;
  if (партия.стол.length >= МАКС_КАРТ_В_ПОДХОДЕ) return false;
  if (неотбитых(партия) >= партия.руки[защищается(партия)].length) return false;
  if (текущая === 'атака') return true;
  return достоинстваНаСтоле(партия).indexOf(карта.имя) !== -1;
}

/**
 * Положить карту из руки в атаку. Возвращает true, если ход состоялся.
 *
 * Отдельно проверяем отказ. Обычно слово спасовавшему и не достаётся вовсе
 * (см. «ктоХодит»), но проверка стоит здесь на случай, если слово всё же
 * дошло до него запасным ответом: передумать и положить карту, от которой
 * сам же отказался, нельзя. Иначе выходило бы то самое, на что жаловался
 * игрок: человек спасовал, а через круг его снова дёргают тем же вопросом,
 * и подход тянется дальше его же картой.
 */
function положитьВАтаку(партия, игрок, индексКарты) {
  if (!можетПодкидывать(партия, игрок)) return false;
  if (ужеСпасовал(партия, игрок)) return false;
  const рука = партия.руки[игрок];
  const карта = рука ? рука[индексКарты] : null;
  if (!карта || !можноПоложить(партия, карта)) return false;
  рука.splice(индексКарты, 1);
  партия.стол.push({ атака: карта, защита: null });
  /* Отказы здесь нарочно не сбрасываются. Подкинуть можно только тем
     достоинством, которое на столе уже лежало, — значит, у сказавшего
     «больше не подкидываю» от чужой карты ничего нового не появилось,
     и спрашивать его заново не за что. Раньше список отказов чистился
     после каждой карты, и слово всё время возвращалось к атакующему:
     живой игрок жаловался, что его дёргают на каждый чужой ход. */
  return true;
}

/**
 * Отбить карту на столе. Возвращает true, если получилось.
 *
 * Здесь на столе может появиться достоинство, которого не было: подкидывают-то
 * только тем, что уже лежит, а отбиваются чем придётся. Раньше игра на это
 * забывала все отказы и спрашивала круг заново. Больше не забывает: владелец
 * ответил прямо — «нет, отказ держится до конца подхода». Сказал «больше
 * не подкидываю» — молчишь до тех пор, пока стол не уберут, даже если крыть
 * стало чем.
 */
function отбить(партия, индексПары, индексКарты) {
  if (фаза(партия) !== 'защита') return false;
  const пара = партия.стол[индексПары];
  if (!пара || пара.защита) return false;
  const защитник = защищается(партия);
  const карта = партия.руки[защитник][индексКарты];
  if (!карта || !бьёт(карта, пара.атака, партия.козырь)) return false;
  пара.защита = карта;
  партия.руки[защитник].splice(индексКарты, 1);
  return true;
}

/**
 * Можно ли сейчас перевести ход этой картой (только в переводном дураке).
 *
 * Перевод — это когда отбивающийся не кроет карту, а кладёт рядом свою
 * такого же достоинства: «не я отбиваюсь, а следующий за мной». Стол
 * при этом растёт, и разбираться с ним придётся уже соседу.
 *
 * Условий четыре, и каждое взято из живой игры:
 *   1. карта того же достоинства, что уже лежит на столе, — иначе это
 *      не перевод, а просто чужая карта;
 *   2. ни одна карта подхода ещё не отбита. Как только защитник хоть раз
 *      покрыл, он признал подход своим — переводить поздно;
 *   3. у того, кому переводят, карт в руке хватает на весь стол: иначе
 *      его загоняют в положение, где отбиться невозможно физически.
 *      Это то же правило, что и при подкидывании, только считаем наперёд;
 *   4. потолок в шесть карт за подход действует и здесь.
 * Переводить самому себе нельзя — за столом должен быть кто-то ещё.
 */
function можноПеревести(партия, карта) {
  if (!партия.переводной || !карта) return false;
  if (фаза(партия) !== 'защита') return false;
  if (неотбитых(партия) !== партия.стол.length) return false;      // условие 2
  if (партия.стол.length >= МАКС_КАРТ_В_ПОДХОДЕ) return false;     // условие 4
  if (достоинстваНаСтоле(партия).indexOf(карта.имя) === -1) return false;   // условие 1
  const защитник = защищается(партия);
  // Перевод сдвигает круг: отбиваться будет тот, кто отбивался бы за переводящим.
  const следующий = ктоОтбиваетсяЗа(партия, защитник);
  if (следующий === защитник) return false;                        // за столом больше никого
  return партия.руки[следующий].length >= партия.стол.length + 1;  // условие 3
}

/**
 * Перевести ход картой из руки защищающегося. Возвращает true, если получилось.
 *
 * Вся хитрость перевода умещается в одну строку: переведший становится
 * атакующим. Дальше круг сам разбирается, кто отбивается и кто подкидывает, —
 * поэтому остальные правила игры про перевод знать не обязаны.
 */
function перевести(партия, индексКарты) {
  if (партия.завершена || !партия.переводной) return false;
  if (фаза(партия) !== 'защита') return false;
  const защитник = защищается(партия);
  const рука = партия.руки[защитник];
  const карта = рука ? рука[индексКарты] : null;
  if (!карта || !можноПеревести(партия, карта)) return false;
  рука.splice(индексКарты, 1);
  партия.стол.push({ атака: карта, защита: null });
  /* Отказы здесь больше не забываются, и вот почему их незачем забывать.
     Переводить можно, только пока НИ ОДНА карта подхода не отбита (условие 2
     в «можноПеревести»), а сказать «больше не подкидываю» можно лишь тогда,
     когда всё уже отбито либо защитник берёт. Одно исключает другое: к мигу
     перевода отказов не бывает вовсе, список и так пуст.

     Осторожно на будущее: если условие 2 когда-нибудь ослабят и переводить
     разрешат после отбоя, отказы прежнего круга поедут в новый — а круг при
     переводе меняется целиком: отбиваться будет другой, прежний защитник
     встанет в число подкидывающих, и спрашивать его надо заново. Тогда сброс
     сюда придётся вернуть. */
  партия.атакует = защитник;
  return true;
}

/**
 * «Беру»: защищающийся отказался отбиваться, дальше остальные могут докинуть.
 *
 * Отказы держатся и здесь. Раньше игра их забывала — рассуждение было такое:
 * подкинуть берущему выгоднее, чем отбивающемуся, значит спасовавший вправе
 * передумать. Но подход-то не кончился: стол на месте, карты никуда не уехали,
 * а по правилу владельца отказ живёт до конца подхода. Кто сказал «больше
 * не подкидываю» — тот и молчит, иначе слово опять пойдёт по второму кругу
 * и человека снова будут дёргать тем же вопросом.
 *
 * Зависания отсюда не выходит: подкинуть в докидывании может тот, кто ещё
 * не отказался, а если подкинуть нечем никому — подход закрывает первый
 * по кругу, кто ещё не говорил «Пас» (см. «ктоХодит»), и стол уезжает
 * берущему. Спасовавшего для этого не тревожат: однажды именно на этом
 * партия у живых игроков и встала.
 */
function объявитьБеру(партия) {
  if (фаза(партия) !== 'защита') return false;
  партия.берёт = true;
  return true;
}

/**
 * «Больше не подкидываю». Пока в круге есть кто-то, от кого мы ещё ждём
 * слова, подход продолжается и слово переходит к нему. Ждать больше некого —
 * подход закончен.
 *
 * Отказ держится до конца подхода: сказавшего «не подкидываю» больше
 * не спрашивают, что бы на столе ни происходило, — до тех пор, пока стол
 * не уберут. Забываются отказы только там (см. «завершитьПодход»).
 *
 * Вдвоём подкидывающий один, поэтому его отказ сразу заканчивает подход:
 * это и есть привычное «Бито».
 */
function пас(партия, игрок) {
  if (партия.завершена) return false;
  const текущая = фаза(партия);
  if (текущая !== 'атака' && текущая !== 'подкидывание' && текущая !== 'докидывание') return false;
  // Отказаться может только тот, кому вообще разрешено класть карту:
  // при пустом столе это один ходящий, дальше — все, кроме отбивающегося.
  if (!можетПодкидывать(партия, игрок)) return false;
  // Стол пуст: подкидывать не к чему, значит подход заканчивается сразу.
  if (текущая === 'атака') return завершитьПодход(партия);

  if (!партия.пасы) партия.пасы = [];
  if (партия.пасы.indexOf(игрок) === -1) партия.пасы.push(игрок);
  for (const имя of подкидывающие(партия)) {
    if (ждётСлова(партия, имя)) return true;   // от кого-то ещё ждём слова
  }
  return завершитьПодход(партия);
}

/**
 * Порядок добора после подхода: первым добирает тот, кто ходил, дальше
 * по кругу, отбивавшийся — последним. Вдвоём это привычные «сначала
 * атакующий, потом защищающийся».
 *
 * Считаем по кругу, а не по списку подкидывающих: добирают все, кто за столом.
 * В игре парами напарник отбивающегося карт не подкидывает, но добирает
 * наравне со всеми — иначе он остался бы без карт ни за что.
 */
function порядокДобора(партия) {
  const защитник = защищается(партия);
  const остальные = поКругуОт(партия, партия.атакует).filter(function (имя) {
    return имя !== защитник;
  });
  return остальные.concat([защитник]);
}

/** Добор из колоды до шести карт. */
function добрать(партия) {
  for (const игрок of порядокДобора(партия)) {
    while (партия.руки[игрок].length < КАРТ_В_РУКЕ && партия.колода.length > 0) {
      партия.руки[игрок].push(партия.колода.shift());
    }
  }
}

/**
 * Кто остался без карт при пустой колоде — тот вышел из игры, и партия
 * продолжается без него. Смотрим только после добора: пока в колоде есть
 * карты, пустая рука — не выход, а повод добрать.
 */
function отметитьВыбывших(партия) {
  if (партия.колода.length > 0) return;
  for (const имя of оставшиеся(партия)) {
    if (партия.руки[имя].length === 0) партия.выбывшие.push(имя);
  }
}

/**
 * Обе пары стола — по двое сидящих через одного. Нужны только игре парами.
 */
function пары(партия) {
  return [
    [партия.игроки[0], партия.игроки[2]],
    [партия.игроки[1], партия.игроки[3]]
  ];
}

/**
 * Записать конец партии: кто остался дураком. Одному имени — имя, двоим —
 * «имя и имя», никому — ничья. Список имён кладём отдельно, чтобы экрану
 * и серверу не пришлось разбирать строку обратно.
 */
function записатьИтог(партия, проигравшие) {
  партия.завершена = true;
  партия.проигравшие = проигравшие;
  партия.результат = проигравшие.length === 0 ? 'ничья' : проигравшие.join(' и ');
}

/**
 * Партия кончается, когда за столом остался один игрок с картами — он
 * и есть дурак. Вышли все разом — ничья.
 * Вдвоём это прежнее правило: у кого-то кончились карты, значит остался один.
 *
 * В игре парами считают не людей, а пары: партия идёт, пока карты есть
 * у обеих пар. Поэтому игрок, оставшийся без карт при живом напарнике,
 * просто выходит из-за стола, а его пара продолжает играть. Проигрывают
 * оба из той пары, у которой карты остались, — даже если у одного из них
 * рука уже пуста: дурак тут не человек, а пара.
 */
function проверитьКонец(партия) {
  if (партия.колода.length > 0) return;

  if (партия.парами) {
    const сКартами = пары(партия).filter(function (пара) {
      return пара.some(function (имя) { return вИгре(партия, имя); });
    });
    if (сКартами.length > 1) return;    // карты есть у обеих пар — играем дальше
    записатьИтог(партия, сКартами.length === 0 ? [] : сКартами[0].slice());
    return;
  }

  const вживых = оставшиеся(партия);
  if (вживых.length > 1) return;
  записатьИтог(партия, вживых.slice());
}

/**
 * Кому достаётся ход. Названный игрок мог только что выйти из партии —
 * тогда ходит следующий за ним по кругу.
 * Это второе (вместе с «кто отбивается») место, где решается очерёдность.
 *
 * В игре парами есть разница: очередь принадлежит не человеку, а паре.
 * Вышел из партии тот, кому выпал ход, — ходит его напарник, а не сосед
 * по кругу. Иначе получалось так, на что и жаловался живой игрок: соперник
 * отбился последней картой, вышел — и ход доставался напарнику нападавшего,
 * то есть возвращался той же паре, которая только что нападала.
 * Вышли оба из пары — ход и правда идёт дальше по кругу.
 */
function назначитьХод(партия, игрок) {
  if (вИгре(партия, игрок)) { партия.атакует = игрок; return; }
  const напарникВышедшего = партнёр(партия, игрок);
  if (напарникВышедшего && вИгре(партия, напарникВышедшего)) {
    партия.атакует = напарникВышедшего;
    return;
  }
  партия.атакует = следующийВКруге(партия, игрок);
}

/**
 * Кому переходит ход после подхода.
 *
 * Отбился — ходит он сам: привычное правило и вдвоём, и компанией.
 * Взял — в обычной игре ход перешагивает через него и достаётся
 * следующему по кругу.
 *
 * А в игре парами нападавшая пара ход не отдаёт: раз соперник взял карты,
 * нападает второй из той же пары — напарник того, кто ходил. Так играют
 * по правилам, которые подтвердил владелец.
 *
 * НО ТОЛЬКО ПОКА НАПАРНИК В ИГРЕ, и это не мелочь. Раньше ход отдавали
 * напарнику всегда, а если тот уже выбыл — «назначитьХод» возвращал ход
 * его напарнику, то есть обратно нападавшему. Вот что из этого выходило:
 * стол на четверых, пары (1,3) и (2,4), третий выбыл. Первый нападает,
 * отбиваться по кругу достаётся второму, второй берёт — и ход снова
 * у первого. И так до конца партии: живой человек на четвёртом месте
 * не получал ни хода, ни защиты и досматривал партию зрителем.
 * Замерено на этой самой раздаче: за шестнадцать подходов он поучаствовал
 * один раз, а разных пар «кто нападает — кто отбивается» за всю партию
 * набралось две вместо восьми возможных.
 *
 * ИСКАТЬ ТУТ ЗАВИСАНИЕ БЕСПОЛЕЗНО — его нет. Партия честно кончается,
 * когда у нападавшего выйдут карты, и все ходы в ней законны: потому её
 * и не ловили ни автопрогоны, ни проверка тупиков. Беда не в остановке,
 * а в НЕСПРАВЕДЛИВОЙ ОЧЕРЕДИ: право хода замыкается на двоих, а остальных
 * обходят. Проверять это надо не законностью хода, а так: в партии,
 * которая длилась больше подходов, чем за столом игроков, каждый
 * невыбывший к её концу игрок обязан хотя бы раз оказаться атакующим
 * или защитником.
 *
 * Поэтому правило теперь такое: напарник выбыл — очередь пары исчерпана,
 * и ход идёт дальше по кругу от взявшего, как в обычной игре.
 */
function наследникХода(партия, защитник, защитникВзял) {
  if (!защитникВзял) return защитник;
  if (партия.парами) {
    const напарник = партнёр(партия, партия.атакует);
    if (напарник && вИгре(партия, напарник)) return напарник;
  }
  return следующийВКруге(партия, защитник);
}

/**
 * Закончить подход: карты со стола уходят в отбой либо к тому, кто берёт;
 * затем добор и передача хода. Кому достаётся ход, решает наследникХода —
 * в игре парами это правило своё.
 */
function завершитьПодход(партия) {
  if (партия.завершена) return false;
  const защитник = защищается(партия);
  const защитникВзял = партия.берёт;

  for (const пара of партия.стол) {
    if (защитникВзял) {
      партия.руки[защитник].push(пара.атака);
      if (пара.защита) партия.руки[защитник].push(пара.защита);
    } else {
      партия.отбой.push(пара.атака);
      if (пара.защита) партия.отбой.push(пара.защита);
    }
  }

  партия.стол = [];
  партия.берёт = false;
  партия.пасы = [];   // подход кончился — только здесь отказы и забываются
  добрать(партия);
  /* Сперва узнаём выбывших и только потом решаем, кому ходить дальше.
     Порядок был обратным, а рядом стояло пояснение «правило от выбывших
     не зависит» — оно и оказалось неправдой. В игре парами очередь
     передаётся напарнику, и вопрос «а он ещё в игре?» надо задавать, уже
     зная ответ: иначе напарник, вышедший в этом же подходе, ещё числится
     живым, ход уходит к нему, а оттуда возвращается нападавшему — и очередь
     замыкается на двоих (подробности у «наследникХода»).
     Назначать ход вышедшему по-прежнему нельзя, но с этим разбирается
     сам «назначитьХод». */
  отметитьВыбывших(партия);
  const наследник = наследникХода(партия, защитник, защитникВзял);
  назначитьХод(партия, наследник);
  упорядочитьРуку(партия, партия.игроки[0]);
  проверитьКонец(партия);
  return true;
}

/* ---------------------------------------------------------------------
   Бот. Три манеры игры — по выбранному уровню соперника:

   «обычный» — жадный расчёт: кроет самой мелкой подходящей картой,
               козырь придерживает, берёт, когда крыть нечем;
   «лёгкий»  — тот же бот, но время от времени ошибается, как новичок:
               бьёт козырем там, где хватило бы простой карты,
               и ходит случайной картой вместо самой мелкой;
   «сложный» — бережёт козыри всерьёз (за мелкую карту лучше возьмёт,
               чем потратит козырь), не отдаёт козыри тому, кто берёт,
               и помнит вышедшие карты: когда колода кончилась, он точно
               знает руку соперника и ходит тем, что тому не побить.
   --------------------------------------------------------------------- */

// Как часто лёгкий соперник играет не лучшей картой.
const ДОЛЯ_ОШИБОК_ЛЁГКОГО = 0.35;

/* Повадки сложного соперника подбирались замером — по 3000 партий против
   обычного бота на каждый вариант. Обычный выигрывает 40% партий; сложный
   со счётом карт и бережливостью к козырям — 49%, и ничьих вдвое меньше
   (10% против 21%). Ещё одну идею — «за мелкую карту лучше взять, чем крыть
   козырем» — замер отверг: с ней бот выигрывал только 38%, поэтому её тут нет. */

/** Из списка индексов руки выбрать индекс самой младшей карты. */
function индексМладшей(рука, индексы) {
  let лучший = индексы[0];
  for (const i of индексы) {
    if (рука[i].вес < рука[лучший].вес) лучший = i;
  }
  return лучший;
}

/** Из списка индексов руки выбрать индекс самой старшей карты. */
function индексСтаршей(рука, индексы) {
  let лучший = индексы[0];
  for (const i of индексы) {
    if (рука[i].вес > рука[лучший].вес) лучший = i;
  }
  return лучший;
}

/** Есть ли в руке ещё одна карта того же достоинства — такой картой хорошо ходить. */
function естьПара(рука, индекс) {
  for (let i = 0; i < рука.length; i++) {
    if (i !== индекс && рука[i].имя === рука[индекс].имя) return true;
  }
  return false;
}

/**
 * Какие карты могут быть у соперника. Считаем от обратного: вся колода
 * минус то, что бот видит своими глазами, — его рука, отбой и стол.
 * Пока в колоде есть карты, список получается «возможные», а когда
 * колода кончилась — это уже точная рука соперника.
 *
 * За столом втроём и больше в этот список попадают карты всех остальных
 * разом, а не одного отбивающегося. Бот от этого становится осторожнее,
 * чем нужно, но ошибок в правилах это не даёт — только манеру игры.
 */
function возможныеКартыСоперника(партия, игрок) {
  const видно = Object.create(null);
  const пометить = function (карта) { видно[карта.имя + карта.масть] = true; };
  for (const карта of партия.руки[игрок]) пометить(карта);
  for (const карта of партия.отбой) пометить(карта);
  for (const пара of партия.стол) {
    пометить(пара.атака);
    if (пара.защита) пометить(пара.защита);
  }
  const остальные = [];
  for (const карта of собратьКолоду(партия.размерКолоды)) {
    if (!видно[карта.имя + карта.масть]) остальные.push(карта);
  }
  return остальные;
}

/** Может ли соперник побить эту карту хоть чем-нибудь из возможных. */
function соперникПобьёт(партия, карта, чужие) {
  for (const чужая of чужие) {
    if (бьёт(чужая, карта, партия.козырь)) return true;
  }
  return false;
}

/** Самая мелкая карта, но при равных — та, к которой в руке есть пара: её потом подкинем. */
function мелкаяСОглядкойНаПару(рука, выбор) {
  let лучший = выбор[0];
  let лучшаяОценка = Infinity;
  for (const i of выбор) {
    const оценка = рука[i].вес - (естьПара(рука, i) ? 0.5 : 0);
    if (оценка < лучшаяОценка) {
      лучшаяОценка = оценка;
      лучший = i;
    }
  }
  return лучший;
}

/**
 * Чем ходит сложный соперник. Вернёт -1, если решил закончить подход.
 * Главная его сила — в концовке: когда колода пуста, он по отбою и по своей
 * руке точно знает карты соперника и кладёт то, что тому нечем крыть.
 */
function выборСложного(партия, игрок, годные, первыйХод) {
  const рука = партия.руки[игрок];
  const эндшпиль = партия.колода.length === 0;

  if (эндшпиль) {
    const чужие = возможныеКартыСоперника(партия, игрок);
    // Карта, которую сопернику нечем побить, — он вынужден будет взять.
    // Козырь здесь тоже в дело: в концовке он важнее бережливости.
    const неотбиваемые = годные.filter(function (i) {
      return !соперникПобьёт(партия, рука[i], чужие);
    });
    if (неотбиваемые.length > 0) return индексМладшей(рука, неотбиваемые);
    // Соперник и так берёт, а колоды больше нет: сбрасываем всё, чтобы
    // остаться с пустыми руками — это и есть победа.
    if (партия.берёт) return индексМладшей(рука, годные);
  }

  const некозырные = годные.filter(function (i) { return рука[i].масть !== партия.козырь; });
  if (некозырные.length > 0) return мелкаяСОглядкойНаПару(рука, некозырные);

  if (первыйХод) return индексМладшей(рука, годные);   // ходить всё равно надо
  // В руке одни козыри, а соперник берёт: отдавать их ему — расточительство,
  // лучше закончить подход.
  return -1;
}

/** Какую карту бот кладёт в атаку. Вернёт -1, если решил закончить подход. */
function выбратьКартуДляАтаки(партия, игрок, годные, первыйХод, сложность) {
  const рука = партия.руки[игрок];

  // Новичок время от времени кладёт что попало — бывает, что и козырь.
  if (сложность === 'лёгкий' && Math.random() < ДОЛЯ_ОШИБОК_ЛЁГКОГО) {
    return годные[Math.floor(Math.random() * годные.length)];
  }

  if (сложность === 'сложный') return выборСложного(партия, игрок, годные, первыйХод);

  const некозырные = годные.filter(function (i) { return рука[i].масть !== партия.козырь; });
  if (некозырные.length > 0) return индексМладшей(рука, некозырные);

  // В руке одни козыри: ходить всё равно надо, а берущему не жалко и козыря.
  if (первыйХод || партия.берёт) return индексМладшей(рука, годные);
  return -1;
}

/** Чем бот отбивается: список годных карт уже собран, надо выбрать одну. */
function выбратьКартуДляЗащиты(партия, игрок, годные, сложность) {
  const рука = партия.руки[игрок];

  // Новичок хватается за самую крупную карту, часто зря тратит козырь.
  if (сложность === 'лёгкий' && Math.random() < ДОЛЯ_ОШИБОК_ЛЁГКОГО) {
    return индексСтаршей(рука, годные);
  }

  // Бьём самой мелкой подходящей, козырь — только когда другого нет.
  const некозырные = годные.filter(function (i) { return рука[i].масть !== партия.козырь; });
  return индексМладшей(рука, некозырные.length > 0 ? некозырные : годные);
}

/**
 * Бот больше не кладёт карту. Вдвоём это сразу «Бито», а за столом побольше
 * подход продолжится: право подкинуть перейдёт следующему по кругу.
 *
 * Ответ «паса» проверяем: если правила отказали, бот не сделал ничего, и врать
 * об этом нельзя. Скажи он «бито» вхолостую — на сервере событие записалось бы,
 * бота через паузу позвали бы снова, и он крутился бы так без конца.
 */
function отказатьсяПодкидывать(партия, игрок, первыйХод) {
  if (!пас(партия, игрок)) return 'хода не было';
  if (первыйХод) return 'пас';
  return партия.стол.length === 0 ? 'бито' : 'не подкидывает';
}

/** Один ход бота в роли атакующего (первая карта, подкидывание или «Бито»). */
function атакаБота(партия, игрок, сложность) {
  const рука = партия.руки[игрок];
  const первыйХод = партия.стол.length === 0;

  /* Слово вернулось к тому, кто уже отказался подкидывать, — значит, ждать
     больше некого и от него нужно одно: закрыть подход. Карту он положить
     всё равно не вправе, поэтому даже не выбираем её. */
  if (ужеСпасовал(партия, игрок)) return отказатьсяПодкидывать(партия, игрок, первыйХод);

  const годные = [];
  for (let i = 0; i < рука.length; i++) {
    if (можноПоложить(партия, рука[i])) годные.push(i);
  }
  // Нечего класть: отказываемся подкидывать дальше. При пустом столе такое
  // возможно, только когда партия и так уже фактически доиграна.
  if (годные.length === 0) return отказатьсяПодкидывать(партия, игрок, первыйХод);

  const индекс = выбратьКартуДляАтаки(партия, игрок, годные, первыйХод, сложность);
  if (индекс === -1) return отказатьсяПодкидывать(партия, игрок, первыйХод);

  положитьВАтаку(партия, игрок, индекс);
  return первыйХод ? 'ходит' : 'подкидывает';
}

/**
 * Чем бот переведёт ход (только в переводном дураке). Вернёт -1, если
 * переводить нечем или незачем.
 *
 * Козырем не переводим никогда: козырь дороже тем, что им можно отбиться,
 * а перевести обычно есть чем и без него.
 */
function выборПеревода(партия, игрок) {
  if (!партия.переводной) return -1;
  const рука = партия.руки[игрок];
  const годные = [];
  for (let i = 0; i < рука.length; i++) {
    if (рука[i].масть === партия.козырь) continue;
    if (можноПеревести(партия, рука[i])) годные.push(i);
  }
  if (годные.length === 0) return -1;
  return индексМладшей(рука, годные);
}

/** Один ход бота в роли защищающегося: перевести, отбиться или взять. */
function защитаБота(партия, игрок, сложность) {
  const рука = партия.руки[игрок];

  // Перевод выгоднее защиты: карта уходит из руки, а отбиваться будет сосед.
  const переводом = выборПеревода(партия, игрок);
  if (переводом !== -1) {
    перевести(партия, переводом);
    return 'переводит';
  }

  let индексПары = -1;
  for (let i = 0; i < партия.стол.length; i++) {
    if (!партия.стол[i].защита) { индексПары = i; break; }
  }
  if (индексПары === -1) return 'нечего';

  const атака = партия.стол[индексПары].атака;
  const годные = [];
  for (let i = 0; i < рука.length; i++) {
    if (бьёт(рука[i], атака, партия.козырь)) годные.push(i);
  }
  if (годные.length === 0) {
    объявитьБеру(партия);
    return 'беру';
  }

  const индекс = выбратьКартуДляЗащиты(партия, игрок, годные, сложность);

  отбить(партия, индексПары, индекс);
  return 'отбивается';
}

/**
 * Сделать за игрока один ход по правилам бота.
 * Уровень можно передать третьим доводом — иначе берётся уровень партии.
 * Возвращает короткое название действия — оно нужно автотесту и отладке.
 */
function ходБота(партия, игрок, сложность) {
  if (партия.завершена) return 'конец';
  if (ктоХодит(партия) !== игрок) return 'не его ход';
  const уровень = проверитьСложность(сложность || партия.сложность);
  return фаза(партия) === 'защита'
    ? защитаБота(партия, игрок, уровень)
    : атакаБота(партия, игрок, уровень);
}

/* =====================================================================
   ЧАСТЬ 2. ЭКРАН
   ===================================================================== */

/* ---------------------------------------------------------------------
   ТЕМП ИГРЫ. Все задержки собраны здесь, одним блоком, — их приходится
   подбирать по живым игрокам, и делать это должно быть делом одной строки.

   Живой новичок сказал про игру две вещи разом: «партия быстрая, это
   хорошо» и «половина событий происходит без меня — карты моргнули,
   и стол уже пустой». Поэтому удлинена ровно ОДНА пауза — та, после
   которой карта вот-вот исчезнет со стола (ПАУЗА_ПОСЛЕ_СВОЕГО_ОТБОЯ).
   Все прочие задержки остались прежними.

   Так вышло не сразу: сперва пауза была добавлена после каждого хода
   человека и после каждой уборки стола. Замер это отверг — партия
   удлинялась с 27 до 39 секунд (+45%), а живой игрок как раз хвалил
   быструю игру. Понятность добралась другим, бесплатным способом:
   сообщение больше не гаснет само и называет карты поимённо.
   --------------------------------------------------------------------- */

const ЗАДЕРЖКА_БОТА = 700;      // пауза перед ходом бота, чтобы ход было видно
/* Сколько сообщение считается свежим. Пропасть оно уже не может — текст
   висит до следующего события, — но через это время гаснет подсветка
   и бот перестаёт из-за него ждать. Полутора секунд игроку не хватало:
   он тапал по карте, смотрел на руку, а надпись внизу успевала смениться,
   пока он переводил взгляд. */
const ПОКАЗ_СОБЫТИЯ = 3000;
const ПАУЗА_ПОД_СОБЫТИЕ = 1600; // столько бот даёт прочитать прошлое событие

/* Столько бот ждёт после того, как человек отбился последней неотбитой
   картой. Это самый «моргающий» миг партии: следующим движением соперник
   говорит «Бито» и стол уезжает целиком. С прежними 0,7 с игрок своего
   хода просто не видел — «карты моргнули, и уже написано, что соперник
   сказал Бито».

   Только этот случай и удлинён. Заманчиво было дать ту же паузу после
   каждого своего хода, но замер это отверг: обычная положенная карта
   никуда не девается, она остаётся лежать на столе, а машинное время
   партии выросло бы с 27 до 39 секунд (+45%). Здесь же карта вот-вот
   исчезнет, и полсекунды сверху окупаются. */
const ПАУЗА_ПОСЛЕ_СВОЕГО_ОТБОЯ = 1200;

/* Столько бот ждёт после того, как подход закончился: стол уехал в отбой
   или в руку, рука пересобралась, пришли карты из колоды.

   Сейчас это ровно та же величина, что и обычная пауза, — то есть темп
   здесь не изменился. Замер показал, что каждые лишние 200 мс тут стоят
   примерно 4% длины партии, а понятность добирается другим, бесплатным
   способом: сообщение о конце подхода теперь называет забранные карты
   поимённо и не гаснет само. Если живому игроку всё равно окажется мало —
   крутить надо здесь, одним числом (1800 ≈ +22% к машинному времени
   партии, 2000 ≈ +28%). */
const ПАУЗА_ПОСЛЕ_ПОДХОДА = 1600;

/* Столько соперники ждут после СВОЕГО хода за столом компанией.

   Вдвоём положенная карта спокойно лежит на столе, и ждать под неё незачем —
   там осталась прежняя короткая пауза. А компанией следом ходят до пяти ботов
   подряд, и живой новичок сказал прямо: «подкинул 8♦ — и сразу „Бот 5 забрал
   6 карт“. Я ни разу не увидел, как мой ход лежит на столе». Полторы секунды
   дают своей карте побыть на столе одной, прежде чем её накроет чужими. */
const ПАУЗА_ПОСЛЕ_СВОЕГО_ХОДА = 1500;

const ПОКАЗ_НАЧАЛА = 3000;      // сообщение «кто ходит первым» держим не меньше
const ПОКАЗ_ОТКАЗА = 700;       // сколько вздрагивает карта, которой нельзя ходить
/* Слова отказа висят меньше рассказа о ходе: строка подсказки одна на двоих,
   и отказ на все три секунды съедал бы сообщение вроде «Соперник подкинул Д♦» —
   то самое, ради чего человек и смотрит на экран. Потом рассказ возвращается
   сам и досиживает своё время.

   Было полторы секунды — хватало «прочитать три-четыре слова». Стало 2,4:
   отказ больше не сообщает голый запрет, он называет причину целой фразой
   («6♦ не побьёт К♠ — нужна ♠ старше или козырь»), а её ещё надо связать
   с картой под пальцем. Живой новичок на прежних словах успевал только
   моргнуть и решал, что игра не ответила вовсе. */
const ПОКАЗ_СЛОВ_ОТКАЗА = 2400;
const ПРОПОРЦИЯ_КАРТЫ = 1.45;   // высота карты относительно ширины

/* Запасная мерка строки подсказки — в знаках. Работает ровно в одном случае:
   когда у плашки со словами нет высоты. А это значит, что и слов никто
   не видит — игровой экран спрятан, страницы нет вовсе (в Node отрисовка
   и не вызывается) или это поддельный браузер проверки, которому высоту
   решили не давать.

   Раньше здесь было написано, что запасной путь работает «в Node и в
   поддельных браузерах». Это была неправда: поддельные узлы охотно отдают
   готовые высоты (40 и 40), и там идёт основной путь. Пишем как есть,
   чтобы следующий читатель не рассчитывал на защиту, которой нет.

   Число замерено на живых экранах: самая длинная пара, которая влезла, —
   78 знаков, самая короткая срезанная — 81. Берём 78, нижнюю границу:
   ошибиться в сторону «показать одну строку вместо двух» дешевле, чем
   срезать сообщение пополам.

   ВАЖНО: считать знаки — плохая мерка, и это доказано на живом экране.
   Пара в 81 знак не влезла, а пара в 85 влезла: дело в том, где браузер
   перенесёт слова, а не в их числе. Поэтому знаки — только запасной путь,
   а первым спрашивают саму страницу (см. «влезлоВСтроку»). */
const ЗНАКОВ_В_СТРОКУ = 78;

let партия = null;
let выбраннаяКарта = null;      // индекс карты в руке человека, поднятой для защиты
let таймер = null;              // отложенный ход соперника (или наш «Пас» за пустую руку)
/* Что именно сделает таймер, когда сработает. Нужно, чтобы уметь отодвинуть
   уже назначенный ход, не перепутав его с чужим: по таймеру ходит и бот,
   и «Пас» за человека с пустой рукой. */
let отложенныйХод = null;
/* Этот назначенный ход уже отодвигали из-за отказа. Второй раз не двигаем:
   иначе непрерывные нажатия отодвигали бы соперника бесконечно. */
let ходУжеОтодвинут = false;
/* Плашка итога всплывает не сразу, а через паузу — чтобы игрок успел увидеть
   последний ход. За эту паузу экран может смениться (человек вышел в меню,
   сеть увела на экран с кодом комнаты), и тогда плашка легла бы поверх
   чужого экрана. Поэтому её ожидание держим отдельно от хода бота: так его
   можно погасить, не трогая партию. */
let таймерИтога = null;
let итогЗасчитан = false;       // результат партии уже записан в серию и рекорды

/* Сколько рука не принимает касаний сразу после нажатия кнопки. Окно завели
   от «самоходной» карты: палец, нажавший «Бито» или «Готово», вторым
   касанием задевал руку, и карта улетала на стол сама собой.

   Число не выдумано, а замерено в браузере (замерялка тестировщика лежит
   в tests/замер-глухоты-в-браузере.js, повторить можно одной строкой):
     — рука перерисовывается через 1–3 мс после нажатия кнопки, то есть
       уже на третьей миллисекунде тап по карте — законный ход;
     — при 350 мс пропадали настоящие тапы на 150, 200 и 330 мс:
       окно съедало ход, который человек делал осознанно;
     — второе касание того же нажатия укладывается в сотню миллисекунд,
       поэтому от него 150 хватает с запасом;
     — за 28 нажатий ни один «хвост» касания до карты не долетел вовсе:
       между рукой и кнопками 5–9 точек, но панель кнопок держит своё
       место и принимает такое касание на себя.

   Чего мы НЕ знаем: на настоящем телефоне бывает «призрачный клик» —
   он приходит примерно через 300 мс после отрыва пальца. В десктопном
   браузере его не воспроизвести, замера по нему нет. Расчёт тот же:
   придёт он в ту же точку, где панель кнопок, а не карта.

   Поэтому окно не убрано совсем, а укорочено: вёрстка когда-нибудь
   поменяется, зазор станет больше — и защита снова понадобится. */
const ГЛУХОТА_ПОСЛЕ_КНОПКИ = 150;
let рукаГлухаДо = 0;
let ждёмОтветПроВыход = false;  // висит вопрос «точно выйти?», партия на паузе
const размерКарты = { ширина: 48, высота: 70 };

/* Строка подсказки состоит из двух частей:
     «событие» — что только что произошло,
     «действие» — что от человека ждут прямо сейчас (висит всегда).
   Так сообщение об ошибке или о ходе бота больше не затирает насовсем
   главное — напоминание, что делать.

   Событие само по себе больше не стирается: оно висит, пока не случится
   следующее. Живой игрок жаловался прямо: «отвернулся на пять секунд —
   надпись пропала, посмотреть, что было, негде». Отдельного окошка
   с историей ходов на телефоне не завести, места нет, а последняя новость
   на экране стоит ноль пикселей — строка подсказки и так там стоит.

   Через ПОКАЗ_СОБЫТИЯ событие только «остывает»: текст остаётся, но с него
   снимается пометка свежести, по которой оформление его подсвечивает.
   Внешне это выглядит как раньше — вспыхнуло и успокоилось, — только
   прочитать написанное можно и через минуту. */
let событие = null;             // текст, который сейчас стоит в строке (или null)
let событиеДо = 0;              // время (мс), до которого он считается свежим
let паузаСобытия = ПАУЗА_ПОД_СОБЫТИЕ;   // сколько бот выжидает под него
let таймерСобытия = null;       // по нему событие остывает

/* Отдельно храним последний рассказ о ходе — тот, к которому строка
   возвращается после слов отказа. Отказы («сейчас ходит соперник»,
   «этой картой не отбиться») сюда не пишутся никогда, поэтому сколько бы
   их ни было подряд, рассказ о ходе соперника не потеряется. */
let рассказ = null;
let рассказДо = 0;
let паузаРассказа = ПАУЗА_ПОД_СОБЫТИЕ;

/* В строке сейчас стоит отказ (ответ на нажатие), а не рассказ о ходе.
   Нужно ровно для одного: снять отказ досрочно, когда человек тут же сделал
   что-то законное (см. «снятьОтказ») — ругань за прошлое нажатие рядом
   с новой подсказкой ни к чему.

   На то, как строка делится между новостью и напоминанием, этот признак
   больше не влияет: там решает одна общая мерка «влезлоВСтроку», одинаковая
   для отказов и для рассказов о ходе. */
let событиеЭтоОтказ = false;

// Об одном и том же пропавшем элементе ругаемся один раз: перерисовка идёт
// десятки раз за партию, и повторы только засоряют консоль.
const ужеРугались = Object.create(null);

function эл(id) {
  const узел = document.getElementById(id);
  if (!узел && !ужеРугались[id]) {
    ужеРугались[id] = true;
    console.warn('Игра: в разметке нет элемента «' + id + '». ' +
                 'Часть экрана не отрисуется; возможно, браузер показывает старую страницу.');
  }
  return узел;
}

/** Записать текст в элемент, если он есть в разметке. */
function написать(id, текст) {
  const узел = эл(id);
  if (узел) узел.textContent = текст;
}

/**
 * Написать в рамку под заголовком итога — ту, где обычно стоит «Побед подряд: 3».
 * Пустой текст прячет её совсем: пустая рамка с обводкой и заливкой видна
 * как полоска ни о чём и только мешает читать экран.
 */
function написатьВРамкуИтога(текст) {
  написать('серия-итога', текст || '');
  показатьЭлемент('серия-итога', Boolean(текст));
}

/** Показать или спрятать элемент, если он есть в разметке. */
function показатьЭлемент(id, видно) {
  const узел = эл(id);
  if (узел) узел.classList.toggle('скрыт', !видно);
}

/** Название карты для сообщений: «10♠». */
function названиеКарты(карта) {
  return карта.имя + карта.масть;
}

/**
 * Правильно склоняем слово «карта» после числа: 1 карта, 2 карты, 5 карт.
 * Второй аргумент — винительный падеж («забрал 1 карту»).
 */
/**
 * «игрок», «игрока» или «игроков» — по числу. Правило то же, что у карт
 * (см. «словоКарты»): одиннадцать-четырнадцать особые, дальше решает
 * последняя цифра. Без этого за столом на шестерых выходило «5 игрока».
 */
function словоИгроков(сколько) {
  const двеПоследние = сколько % 100;
  const последняя = сколько % 10;
  if (двеПоследние >= 11 && двеПоследние <= 14) return 'игроков';
  if (последняя === 1) return 'игрок';
  if (последняя >= 2 && последняя <= 4) return 'игрока';
  return 'игроков';
}

function словоКарты(сколько, винительный) {
  const двеПоследние = сколько % 100;
  const последняя = сколько % 10;
  if (двеПоследние >= 11 && двеПоследние <= 14) return 'карт';
  if (последняя === 1) return винительный ? 'карту' : 'карта';
  if (последняя >= 2 && последняя <= 4) return 'карты';
  return 'карт';
}

/**
 * Поставить текст в строку подсказки. Общая часть у рассказа о ходе
 * и у слов отказа: обоим нужно лечь в строку, завести срок свежести
 * и сказать боту, сколько ждать.
 */
function поставитьСообщение(текст, свежесть, паузаБота) {
  const держим = свежесть || ПОКАЗ_СОБЫТИЯ;
  событие = текст;
  событиеДо = Date.now() + держим;
  паузаСобытия = паузаБота || ПАУЗА_ПОД_СОБЫТИЕ;
  if (таймерСобытия !== null) clearTimeout(таймерСобытия);
  таймерСобытия = setTimeout(function () {
    таймерСобытия = null;
    // Текст не трогаем — перерисовываем строку, чтобы снялась пометка свежести.
    if (партия) рисоватьПодсказкуИКнопки();
  }, держим);
}

/**
 * Показать рассказ о том, что случилось. Текст остаётся на экране до
 * следующего события; через заданное время он лишь перестаёт считаться
 * свежим (гаснет подсветка).
 *
 * Третьим доводом можно сказать, сколько бот выжидает под это сообщение:
 * под свой ход человека — меньше, под уборку стола — больше. Не сказали —
 * берётся обычная ПАУЗА_ПОД_СОБЫТИЕ.
 */
function показатьСобытие(текст, свежесть, паузаБота) {
  поставитьСообщение(текст, свежесть, паузаБота);
  событиеЭтоОтказ = false;   // это рассказ о ходе, а не ответ на нажатие
  // Запоминаем отдельно: именно сюда строка вернётся после слов отказа.
  рассказ = текст;
  рассказДо = событиеДо;
  паузаРассказа = паузаСобытия;
}

/**
 * Показать слова отказа, не отняв у человека рассказ о ходе. Отказ висит
 * своё короткое время, а потом рассказ возвращается и досиживает остаток.
 * Случится за это время что-то новое — показатьСобытие погасит наш возврат
 * само: свежая новость всегда важнее возвращённой старой.
 *
 * Возвращаем не то, что было в строке за миг до отказа, а последний
 * настоящий рассказ о ходе. Разница видна на двух отказах подряд —
 * а это обычное дело: нетерпеливый человек тапает по картам, пока
 * соперник думает. Раньше второй отказ запоминал «на возврат» первый,
 * и рассказ о ходе соперника пропадал совсем: пока сообщения гасли
 * за три секунды, это было незаметно, а теперь они висят до следующего
 * хода, и вместо «Соперник подкинул Д♦» человек до конца хода смотрел бы
 * на «Сейчас ходит соперник».
 */
function показатьОтказ(текст) {
  /* Соперник обязан выждать ровно столько, сколько висят слова отказа.
     Раньше он ждал обычные 1,6 с и обрывал ответ на полуслове — а если ход
     был назначен ещё до нажатия, то и вовсе через десятую долю секунды
     (см. «отодвинутьОтложенныйХод»). */
  поставитьСообщение(текст, ПОКАЗ_СЛОВ_ОТКАЗА, ПОКАЗ_СЛОВ_ОТКАЗА);
  событиеЭтоОтказ = true;
  /* Отсидев своё, отказ уходит: есть рассказ о ходе — возвращаем его,
     нет (в начале партии его ещё не было) — убираем строку вовсе, и остаётся
     одно напоминание «что делать».

     Раньше во втором случае возврата не заводилось совсем, и отказ висел
     в строке дальше — но уже остывший, а к остывшему пристраивается
     напоминание. Выходила та самая пара в 88 знаков, которая на узком
     экране не влезает. Теперь такой пары не бывает: пока отказ виден,
     строка его, а как отсидел — его нет. */
  clearTimeout(таймерСобытия);
  таймерСобытия = setTimeout(function () {
    таймерСобытия = null;
    if (рассказ) вернутьРассказ(); else убратьСобытие();
    событиеЭтоОтказ = false;
    if (партия) рисоватьПодсказкуИКнопки();
  }, ПОКАЗ_СЛОВ_ОТКАЗА);
}

/**
 * Вернуть в строку рассказ о ходе после слов отказа. Свежесть могла
 * кончиться, пока висел отказ, — тогда возвращаем текст сразу остывшим:
 * пропасть совсем он не должен, читать его человек вправе и потом.
 */
function вернутьРассказ() {
  событиеЭтоОтказ = false;
  const остаток = Math.max(0, рассказДо - Date.now());
  if (остаток > 0) {
    поставитьСообщение(рассказ, остаток, паузаРассказа);
    return;
  }
  событие = рассказ;
  событиеДо = 0;
  паузаСобытия = паузаРассказа;
}

/**
 * Снять отказ досрочно: человек сразу сделал что-то законное, и ругать его
 * за прошлое нажатие больше не за что. Строка возвращается к рассказу о ходе.
 */
function снятьОтказ() {
  if (!событиеЭтоОтказ) return;
  if (таймерСобытия !== null) {
    clearTimeout(таймерСобытия);
    таймерСобытия = null;
  }
  if (рассказ) вернутьРассказ(); else убратьСобытие();
  событиеЭтоОтказ = false;
}

/** Сколько миллисекунд событие ещё должно повисеть, чтобы его успели прочитать. */
function остатокСобытия() {
  if (!событие) return 0;
  return Math.max(0, событиеДо - Date.now());
}

/**
 * Сколько игра выжидает под сообщение. Само сообщение висит дольше,
 * но заставлять игрока ждать все три секунды между ходами бота незачем.
 * Потолок у каждого сообщения свой — его задаёт показатьСобытие.
 */
function ждатьПодСобытие() {
  return Math.min(остатокСобытия(), паузаСобытия);
}

/** Убрать сообщение совсем (новая партия, выход в меню). */
function убратьСобытие() {
  if (таймерСобытия !== null) clearTimeout(таймерСобытия);
  таймерСобытия = null;
  событиеЭтоОтказ = false;
  событие = null;
  событиеДо = 0;
  паузаСобытия = ПАУЗА_ПОД_СОБЫТИЕ;
  // Вместе с событием забываем и рассказ: возвращаться к вестям из прошлой
  // партии нельзя — карты уже другие.
  рассказ = null;
  рассказДо = 0;
  паузаРассказа = ПАУЗА_ПОД_СОБЫТИЕ;
}

/** Отменить отложенный показ плашки итога: показывать её уже некому или нечему. */
function отменитьПоказИтога() {
  if (таймерИтога === null) return;
  clearTimeout(таймерИтога);
  таймерИтога = null;
}

/** Показать один из трёх экранов, остальные спрятать. */
function показатьЭкран(id) {
  // Уходим со стола — отложенная плашка итога больше не нужна: иначе она
  // всплывёт поверх меню или экрана с кодом комнаты и перекроет кнопки.
  if (id !== 'экран-игры') отменитьПоказИтога();
  for (const экран of document.querySelectorAll('.экран')) {
    экран.classList.toggle('экран--виден', экран.id === id);
  }
  // Итог и вопрос про выход показываются по-особому — плашкой поверх стола.
  // При обычной смене экрана этот режим снимаем со всех.
  for (const экран of document.querySelectorAll('.экран')) {
    экран.classList.remove('экран--поверх');
  }
  /* Вернулись в меню — рассказ о том, что игра поменяла за человека, устарел:
     он про нажатие, которое было до партии. Стереть его надо и из памяти,
     и со строки, иначе он встретит человека как свежая новость. */
  if (id === 'экран-меню') {
    подменаВВыборе = '';
    написать('меню-пояснение-стола', словаПроСтолСБотами());
  }
}

/** Стоит ли человек прямо сейчас у игрового стола. */
function этоЭкранИгры() {
  const стол = эл('экран-игры');
  return Boolean(стол && стол.classList.contains('экран--виден'));
}

/**
 * Показать итог партии плашкой поверх стола: игровой экран не прячем,
 * чтобы было видно, чем всё кончилось.
 */
function показатьПлашкуИтога() {
  const итог = эл('экран-результата');
  if (!итог) return;
  итог.classList.add('экран--поверх');
  итог.classList.add('экран--виден');
}

/**
 * Узнать настоящий размер карты — тот, который получился в оформлении.
 * Своей формулы у игры больше нет: раньше она повторяла расчёт из style.css,
 * и стоило дизайнеру поменять там хоть одно число, как размеры расходились
 * и веер раскладывался с щелями. Теперь спрашиваем у браузера: ставим
 * невидимую карту, меряем её и по этому размеру раскладываем руку.
 */
function измеритьКарту() {
  const щуп = document.createElement('div');
  щуп.className = 'карта';
  щуп.style.position = 'absolute';
  щуп.style.left = '-9999px';
  щуп.style.visibility = 'hidden';
  document.body.appendChild(щуп);
  const место = щуп.getBoundingClientRect();
  document.body.removeChild(щуп);
  // Ноль означает, что оформление ещё не загрузилось: тогда оставляем прежние
  // значения, иначе рука схлопнется в точку.
  if (место.height > 0 && место.width > 0) {
    размерКарты.высота = место.height;
    размерКарты.ширина = место.width;
  }
}

/**
 * Сказать оформлению, какой ширины карта помещается в это окно: по ширине
 * экрана должно вставать шесть карт — столько их в руке при раздаче.
 * Насколько карта влезет по высоте и в какие пределы уложится, решает
 * style.css, а мы потом просто меряем, что получилось.
 */
function подобратьРазмерКарты() {
  const поШирине = Math.floor((window.innerWidth - 16) / 6) * ПРОПОРЦИЯ_КАРТЫ;
  document.documentElement.style.setProperty('--высота-карты', Math.round(поШирине) + 'px');
  измеритьКарту();
}

/* Своя пометка на каждую масть. Раньше карта говорила оформлению только
   «красная или чёрная», и отличить пику от трефы было нечем: разбирать
   значок внутри карты оформление не умеет. Живой игрок на это и жаловался —
   «не видно, крест это или пика», особенно когда от карты в веере видна
   полоска в несколько точек.

   С этими пометками style.css может раскрасить масти по-разному (например,
   трефы зелёным, бубны синим). Сама игра ими не пользуется и от них
   не меняется: пока оформление их не подхватит, карты выглядят как прежде. */
const КЛАСС_МАСТИ = {
  '♠': 'карта--пики',
  '♥': 'карта--черви',
  '♦': 'карта--бубны',
  '♣': 'карта--трефы'
};

/** Собрать картинку одной карты. */
function элементКарты(карта, добавочныйКласс) {
  const узел = document.createElement('div');
  узел.className = 'карта';
  if (КРАСНЫЕ_МАСТИ.indexOf(карта.масть) !== -1) узел.classList.add('карта--красная');
  // Пометка масти. Её нет у карты-невидимки (чужая рука приходит без мастей) —
  // и это правильно: наружу не должно уйти ничего про чужие карты.
  const пометкаМасти = КЛАСС_МАСТИ[карта.масть];
  if (пометкаМасти) узел.classList.add(пометкаМасти);
  if (добавочныйКласс) узел.classList.add(добавочныйКласс);

  // Угол собираем из двух частей: достоинство и масть — отдельные элементы.
  // Так они всегда встают столбиком, а не зависят от переноса строки.
  const угол = document.createElement('div');
  угол.className = 'карта__угол';
  const номинал = document.createElement('span');
  номинал.className = 'карта__номинал';
  номинал.textContent = карта.имя;
  const мастьВУглу = document.createElement('span');
  мастьВУглу.className = 'карта__масть-угла';
  мастьВУглу.textContent = карта.масть;
  угол.appendChild(номинал);
  угол.appendChild(мастьВУглу);

  const масть = document.createElement('div');
  масть.className = 'карта__масть';
  масть.textContent = карта.масть;

  узел.appendChild(угол);
  узел.appendChild(масть);
  return узел;
}

/** Карта рубашкой вверх. */
function элементРубашки() {
  const узел = document.createElement('div');
  узел.className = 'карта карта--рубашка';
  return узел;
}

/**
 * Шаг между картами в ряду. Он же — ширина полоски, которая остаётся видна
 * от каждой карты: именно по ней игрок целится пальцем.
 */
function шагВРяду(ширинаКарты, картВРяду, доступно) {
  if (картВРяду <= 1) return 0;
  return Math.min(ширинаКарты + ЗАЗОР_КАРТ, (доступно - ширинаКарты) / (картВРяду - 1));
}

/**
 * Сказать оформлению, какой ширины видна каждая карта в этом веере.
 *
 * Шаг между картами — он же ширина оставшейся видимой полоски: по ней
 * игрок целится пальцем, и от неё зависит, какого размера подпись на карте
 * ещё можно прочитать. Считает эту ширину игра (она знает, сколько карт
 * и сколько места), а нужна она оформлению — вот и передаём числом,
 * чтобы style.css не угадывал её по количеству карт.
 */
function записатьШагВеера(контейнер, шаг) {
  // Ноль означает, что карта в ряду одна: она видна целиком, во всю ширину.
  const полоска = шаг > 0 ? шаг : размерКарты.ширина;
  контейнер.style.setProperty('--шаг-карт', Math.round(полоска) + 'px');
}

/**
 * Разложить карты веером внахлёст: считаем шаг так, чтобы любое
 * количество карт уместилось в ширину экрана.
 */
function разложитьВеером(контейнер, отступСверху) {
  const карты = контейнер.children;
  if (карты.length === 0) return;
  const доступно = контейнер.clientWidth || window.innerWidth;
  const шаг = шагВРяду(размерКарты.ширина, карты.length, доступно);
  const занято = размерКарты.ширина + шаг * (карты.length - 1);
  const старт = Math.max(0, (доступно - занято) / 2);
  for (let i = 0; i < карты.length; i++) {
    карты[i].style.left = Math.round(старт + шаг * i) + 'px';
    карты[i].style.top = отступСверху + 'px';
  }
  записатьШагВеера(контейнер, шаг);
}

/* ---------------------------------------------------------------------
   Компания за столом

   За столом на шестерых веер рубашек показать негде: пять вееров в телефон
   не влезут физически. Поэтому каждый соперник показан строкой — имя,
   сколько у него карт и что с ним происходит прямо сейчас.

   Список мест бывает двух происхождений, и это главное, что тут надо знать.
   В игре по сети его присылает сервер: он один знает, кто уже сказал «пас»,
   поэтому там мы ему верим на слово. В местной игре с ботами правила лежат
   рядом, в этом же файле, и такой же список мы собираем сами из партии —
   поля называются одинаково, так что полоса соперников и все подсказки
   разницы не замечают.

   Вдвоём (и с ботом, и с другом) списка мест нет вовсе, и стол рисуется
   по-старому — веером рубашек одного соперника.
   --------------------------------------------------------------------- */

/**
 * Как зовут место за столом на экране. Ботов зовём по номеру места и теми же
 * словами, что и сервер игры по сети («Бот 3»), — чтобы в обоих режимах
 * соперники назывались одинаково.
 *
 * ВАЖНО: это про МЕСТНУЮ партию с ботами. За сетевым столом сидят живые люди,
 * и имена там приходят от сервера — брать их надо из списка мест (поле «имя»),
 * а не отсюда.
 */
function имяМеста(ключ) {
  if (ключ === 'человек') return 'Вы';
  const номер = партия ? партия.игроки.indexOf(ключ) + 1 : 0;
  return номер > 0 ? 'Бот ' + номер : 'Соперник';
}

/**
 * Места местной партии — тот же список, что присылает сервер, только
 * собранный из своей партии. Поля названы один в один как в ответе сервера
 * (см. «ктоЗаСтолом» в server/партия-по-сети.js): полосу соперников и все
 * подсказки писали под него, и переучивать их не нужно.
 */
function местаМестнойКомпании() {
  const идётИгра = !партия.завершена;
  const ходит = идётИгра ? ктоХодит(партия) : null;
  const отбивается = идётИгра ? защищается(партия) : null;
  const проигравшие = партия.проигравшие || [];
  return партия.игроки.map(function (ключ, место) {
    const напарник = партнёр(партия, ключ);
    return {
      номер: место + 1,
      имя: имяМеста(ключ),
      этоЯ: ключ === 'человек',
      этоБот: ключ !== 'человек',
      карт: партия.руки[ключ] ? партия.руки[ключ].length : 0,
      ходит: ключ === ходит,
      отбивается: ключ === отбивается,
      выбыл: !вИгре(партия, ключ),
      проиграл: партия.завершена && проигравшие.indexOf(ключ) !== -1,
      напарник: напарник ? партия.игроки.indexOf(напарник) + 1 : null
    };
  });
}

/** Список мест за столом — или null, если играем вдвоём. */
function местаКомпании() {
  if (!партия) return null;
  if (Array.isArray(партия.застолом)) return партия.застолом;          // прислал сервер
  // Местная партия с ботами: собираем такой же список сами.
  if (!этоСетеваяИгра() && партия.игроки && партия.игроки.length > 2) {
    return местаМестнойКомпании();
  }
  return null;
}

/** Играем ли компанией: за столом больше двоих. */
function этоКомпания() {
  const места = местаКомпании();
  return Boolean(места) && места.length > 2;
}

/**
 * Считает ли очередь хода сервер. Так бывает только за сетевым столом
 * компанией: кто из круга уже сказал «пас», знает он один, и спорить с ним
 * браузеру нечем. В местной игре правила лежат рядом — считаем сами.
 */
function очередьСчитаетСервер() {
  return Boolean(партия) && Array.isArray(партия.застолом);
}

/**
 * Моё ли сейчас слово. За сетевым столом компанией верим серверу,
 * в остальных случаях считаем как считали — по своим правилам.
 */
function сейчасМойХод() {
  if (!партия) return false;
  if (очередьСчитаетСервер()) return партия.яХожу === true;
  return ктоХодит(партия) === 'человек';
}

/** Я ли сейчас отбиваюсь. */
function этоЯОтбиваюсь() {
  if (!партия) return false;
  if (очередьСчитаетСервер()) return партия.яОтбиваюсь === true;
  return защищается(партия) === 'человек';
}

/**
 * Разрешено ли мне сейчас класть карту в атаку (подкидывать).
 *
 * Компанией слово ходит по кругу, поэтому спрашиваем правила напрямую —
 * и обязательно двумя вопросами сразу, ровно как их задаёт сервер
 * (см. «могуПодкинуть» в server/партия-по-сети.js). Второй вопрос про
 * сказанный «Пас»: слово возвращается и к тому, кто уже спасовал, — но
 * только затем, чтобы он закрыл подход, класть карту он больше не вправе.
 */
function мнеМожноПодкинуть() {
  if (!партия) return false;
  if (очередьСчитаетСервер()) return партия.могуПодкинуть === true;
  return можетПодкидывать(партия, 'человек') && !ужеСпасовал(партия, 'человек');
}

/** Как зовут соперника, помеченного признаком («ходит» или «отбивается»). */
function имяТого(признак) {
  const места = местаКомпании() || [];
  for (const место of места) {
    if (место[признак] && !место.этоЯ) return место.имя;
  }
  return '';
}

/** Мой номер места за столом: от сервера — или свой, если играем с ботами. */
function мойНомерЗаСтолом() {
  if (очередьСчитаетСервер()) return партия.мойНомер;
  return партия.игроки ? партия.игроки.indexOf('человек') + 1 : 0;
}

/** Это место — мой напарник по игре парами. */
function этоМойНапарник(место) {
  return Boolean(партия && партия.парами && место.напарник &&
                 место.напарник === мойНомерЗаСтолом());
}

/** Соперники по кругу, начиная с соседа слева: в том же порядке ходит стол. */
function соперникиПоКругу() {
  const места = местаКомпании();
  if (!места) return [];
  let моёМесто = 0;
  for (let i = 0; i < места.length; i++) {
    if (места[i].этоЯ) моёМесто = i;
  }
  const круг = [];
  for (let шаг = 1; шаг < места.length; шаг++) {
    круг.push(места[(моёМесто + шаг) % места.length]);
  }
  return круг;
}

/**
 * Что с этим игроком прямо сейчас — одним словом. Порядок важен: сначала
 * то, из-за чего он вообще не играет (ушёл, кончились карты, пропала
 * связь), и только потом очередь хода. Иначе за столом висит «ходит»,
 * а человек не понимает, почему ничего не происходит.
 */
function состояниеСоперника(место) {
  if (место.ушёл) return 'ушёл';
  if (место.выбыл) return 'без карт';
  if (место.наСвязи === false) return 'нет связи';
  if (место.отбивается) return 'отбивается';
  if (место.ходит) return 'ходит';
  return '';
}

/**
 * Кто он за этим столом: играет со мной заодно или это робот.
 *
 * Слово нарочно короткое. Восемь букв («напарник») на экране шириной
 * 280 точек съедали пол-плашки, и от имени оставалась одна буква с
 * многоточием — оформлением это не лечится, места нет физически.
 *
 * Из двух коротких слов взято «свой», а не «пара»: «пара» в карточной
 * игре занято дважды — так зовут две карты одного достоинства и так же
 * называется связка «карта атаки плюс карта защиты» на столе. Новичок
 * прочитал бы её как подпись про карты, а не про человека. «Свой» же
 * ни с чем не спорит и говорит главное: он играет за меня.
 * Напарник опознаётся не только словом — у него своя пометка в оформлении.
 */
function рольСоперника(место) {
  if (этоМойНапарник(место)) return 'свой';
  if (!место.этоБот) return '';
  /* В игре с ботами вместо слова «бот» пишем уровень. В плашке это выглядит
     как «Бот 3» и рядом «сложный»: имя и уровень — две отдельные подписи,
     никакого разделителя между ними в коде нет, его рисует оформление.
     Вдвоём уровень видно всегда — он стоит в подписи под рубашками
     («Сложный соперник: 6 карт»), а компанией той подписи нет вовсе,
     и после нескольких партий уже не помнишь, с кем играешь. Слово встаёт
     на то же место и той же длины, что и «напарник», — значит, в плашку
     влезает (проверено оформлением: значку роли отдано 60% ширины).

     За сетевым столом остаётся «бот»: там робот садится на место ушедшего
     игрока, уровень ему выбирали не мы, и называть его было бы выдумкой. */
  return этоСетеваяИгра() ? 'бот' : партия.сложность;
}

/** Одна подпись внутри плашки соперника. */
function ячейкаСоперника(плашка, класс, текст) {
  const узел = document.createElement('span');
  узел.className = класс;
  узел.textContent = текст;
  плашка.appendChild(узел);
  return узел;
}

/** Плашка одного соперника: имя, сколько карт и что с ним происходит. */
function плашкаСоперника(место) {
  const плашка = document.createElement('div');
  плашка.className = 'соперник';
  // Пометки классами — чтобы оформление могло выделить и того, кто ходит,
  // и того, кто уже не играет, не разбирая надписи.
  if (место.ходит) плашка.classList.add('соперник--ходит');
  if (место.отбивается) плашка.classList.add('соперник--отбивается');
  if (место.выбыл) плашка.classList.add('соперник--выбыл');
  if (место.ушёл) плашка.classList.add('соперник--ушёл');
  if (место.наСвязи === false) плашка.classList.add('соперник--нет-связи');
  if (место.этоБот) плашка.classList.add('соперник--бот');
  if (место.проиграл) плашка.classList.add('соперник--проиграл');
  if (этоМойНапарник(место)) плашка.classList.add('соперник--напарник');

  ячейкаСоперника(плашка, 'соперник__имя', место.имя);
  const роль = рольСоперника(место);
  if (роль) ячейкаСоперника(плашка, 'соперник__роль', роль);
  const карт = целоеИзОтвета(место.карт);
  /* «0 карт» посреди подхода читается как «игрока больше нет» — та же беда,
     что и в игре вдвоём. Выбывших и ушедших это не касается: у них ноль
     настоящий, а их карты уже не на столе, и про них всё скажет метка. */
  const своиКартыНаСтоле = укартСоперникаТолькоСтол(карт) && !место.выбыл && !место.ушёл;
  ячейкаСоперника(плашка, 'соперник__карт',
    своиКартыНаСтоле ? ТЕКСТ_ВСЁ_НА_СТОЛЕ : (карт + ' ' + словоКарты(карт)));
  const метка = состояниеСоперника(место);
  if (метка) ячейкаСоперника(плашка, 'соперник__метка', метка);
  return плашка;
}

/**
 * Полоса соперников. В разметке её нет — она появилась позже игры вдвоём,
 * поэтому создаём её из кода и кладём первой на игровом экране: соперники
 * сидят напротив, значит и на экране они сверху.
 */
function полосаСоперников() {
  const готовая = document.getElementById('соперники');
  if (готовая) return готовая;
  const экран = эл('экран-игры');
  if (!экран) return null;
  const полоса = document.createElement('div');
  полоса.id = 'соперники';
  полоса.className = 'соперники скрыт';
  экран.insertBefore(полоса, экран.firstChild);
  return полоса;
}

/**
 * Кто сидит напротив. Вдвоём это привычный веер рубашек, компанией —
 * полоса плашек: чужие карты не рисуем никогда, только их количество.
 */
function рисоватьСоперников() {
  const компания = этоКомпания();
  показатьЭлемент('рука-бота', !компания);
  const полоса = полосаСоперников();
  if (полоса) полоса.classList.toggle('скрыт', !компания);
  if (!компания) {
    рисоватьРукуБота();
    return;
  }
  if (!полоса) return;
  полоса.innerHTML = '';
  for (const место of соперникиПоКругу()) полоса.appendChild(плашкаСоперника(место));
}

/** Сколько карт у соперника напротив — в игре вдвоём он один. */
function картУСоперникаВдвоём() {
  const места = местаКомпании();
  if (места) {
    for (const место of места) {
      if (!место.этоЯ) return целоеИзОтвета(место.карт);
    }
    return 0;
  }
  return партия.руки.бот ? партия.руки.бот.length : 0;
}

function рисоватьРукуБота() {
  const веер = эл('карты-бота');
  if (!веер) return;
  const сколько = картУСоперникаВдвоём();
  веер.innerHTML = '';
  for (let i = 0; i < сколько; i++) {
    веер.appendChild(элементРубашки());
  }
  разложитьВеером(веер, 2);
  // Пишем и уровень: иначе после «Играть ещё» непонятно, с кем сейчас играешь.
  // В игре вдвоём уровня нет вовсе — там за столом живой человек.
  const кто = этоСетеваяИгра()
    ? 'Друг'
    : партия.сложность.charAt(0).toUpperCase() + партия.сложность.slice(1) + ' соперник';
  написать('счётчик-бота', кто + ': ' + хвостСчётчикаСоперника(сколько));
}

/**
 * Чем заканчивается подпись под картами соперника. Обычно это просто число
 * карт, но у нуля есть два разных смысла, и путать их нельзя.
 *
 * «0 карт» человек читает как «соперника уже нет, игра сломалась» — так
 * и случилось у живого новичка: бот выложил последнюю карту, она лежала
 * на столе, подход не кончился, а сверху висело «Сложный соперник: 0 карт»
 * все семнадцать секунд, пока человек думал. Надпись не врала — врало
 * слово: счётчик про руку, а читается как «карты в игре».
 *
 * Правила при этом верные, и трогать их не надо: пока стол не убран, карты
 * соперника лежат на нём и вернутся к нему, если он берёт. Поэтому говорим
 * прямо, где они, и заодно видно, что соперник из партии не исчез.
 */
function хвостСчётчикаСоперника(сколько) {
  if (укартСоперникаТолькоСтол(сколько)) return ТЕКСТ_ВСЁ_НА_СТОЛЕ;
  return сколько + ' ' + словоКарты(сколько);
}

/* Короткая замена числу «0». Длинную фразу сюда не поставить: подпись
   соперника рисуется одной строкой и обрезается многоточием, а в компании
   та же мысль должна влезть в плашку шириной 128 точек. «Всё на столе»
   говорит и что рука пуста (карт не осталось совсем), и где эти карты. */
const ТЕКСТ_ВСЁ_НА_СТОЛЕ = 'всё на столе';

/**
 * Тот самый случай: карт в руке ноль, но игрок из партии не выбыл — его
 * карты лежат на столе и вернутся к нему, если он берёт.
 * Партия завершена — считаем обычным нулём: в сетевой партии стол приходит
 * от сервера и может оказаться непустым уже после конца игры, и тогда под
 * плашкой «Друг вышел из игры» висела бы надпись про карты на столе.
 */
function укартСоперникаТолькоСтол(сколько) {
  return сколько === 0 && !партия.завершена && партия.стол.length > 0;
}

function рисоватьКолоду() {
  const козырь = эл('козырная-карта');
  const верх = эл('верх-колоды');
  const счётчик = эл('счётчик-колоды');
  if (козырь) козырь.innerHTML = '';
  if (верх) верх.innerHTML = '';

  // Козырная карта видна, пока она ещё в колоде; рубашка — пока над ней есть карты.
  if (козырь && партия.колода.length > 0) козырь.appendChild(элементКарты(партия.козырнаяКарта));
  if (верх && партия.колода.length > 1) верх.appendChild(элементРубашки());

  // Подписываем счётчик и не прячем его: когда колода кончилась,
  // важно прямо сказать об этом, а не убирать угол с экрана.
  const осталось = партия.колода.length;
  if (счётчик) {
    счётчик.textContent = осталось > 0
      ? 'В колоде ' + осталось + ' ' + словоКарты(осталось)
      : 'Колода пуста';
    счётчик.classList.remove('скрыт');
  }
  // Масть в сетевой партии приходит от сервера: обычно она есть всегда,
  // но при пустой в рамке висело бы «Козырь » с лишним пробелом на конце.
  написать('метка-козыря', партия.козырь ? 'Козырь ' + партия.козырь : 'Козырь');
}

function рисоватьСтол() {
  const стол = эл('стол');
  if (!стол) return;
  стол.innerHTML = '';
  const человекЗащищается = этоЯОтбиваюсь() && фаза(партия) === 'защита';
  const поднятая = выбраннаяКарта !== null ? партия.руки.человек[выбраннаяКарта] : null;

  партия.стол.forEach(function (пара, индекс) {
    const узел = document.createElement('div');
    узел.className = 'пара';
    узел.appendChild(элементКарты(пара.атака, 'карта--атака'));
    if (пара.защита) узел.appendChild(элементКарты(пара.защита, 'карта--защита'));

    // Подсвечиваем те карты, которые человек может побить выбранной картой.
    if (человекЗащищается && поднятая && !пара.защита &&
        бьёт(поднятая, пара.атака, партия.козырь)) {
      узел.classList.add('пара--цель');
    }
    узел.addEventListener('click', function () { тапПоПаре(индекс); });
    стол.appendChild(узел);
  });
}

/* Когда рука раскладывается в два ряда.
   Раньше порогом было 20 карт и ряд не ниже 40 точек — из-за этого на
   невысоком экране два ряда не включались никогда, а перед самым порогом
   получался провал: 19 карт — полоска 17 точек, 20 карт — сразу 30.
   Теперь порог низкий, ряд может быть мелким, а решает сравнение: два ряда
   берём, только если видимая полоска карты станет заметно шире. Мелкая
   карта хуже читается, но подпись оформление уменьшает ступенями, а вот
   попасть пальцем в полоску шириной 6 точек нельзя вовсе. */
const ПОРОГ_ДВУХ_РЯДОВ = 12;
const МИН_ВЫСОТА_В_РЯДУ = 24;
const ВЫГОДА_ДВУХ_РЯДОВ = 1.15;   // насколько шире должна стать полоска
const ЗАЗОР_КАРТ = 4;             // просвет между картами, пока рука не тесная
const ОТСТУП_РУКИ = 14;    // запас сверху: выбранная карта приподнимается
/* На сколько поднимается выбранная карта, когда рука лежит в два ряда.
   Это своя величина, с зазором между рядами она не связана.
   Больше 14 брать нельзя: столько запаса оставлено сверху полоски руки,
   и карта верхнего ряда полезла бы на строку подсказки. Снизу подъём
   закрывает у верхних карт только нижние 8 точек — номинал с мастью
   сидят в верхнем углу и остаются видны. */
const ПОДЪЁМ_В_ДВА_РЯДА = 14;
// Зазор между рядами. При двух точках щель тоньше рамки карты, и ряды
// сливаются в сплошную сетку. Больше шести брать нельзя: на телефоне
// шириной 360 точек ряд становится ниже порога и рука схлопывается в один.
const ЗАЗОР_РЯДОВ = 6;

/**
 * Нужны ли два ряда и какой высоты будут в них карты. Возвращает 0, если
 * рука остаётся в один ряд: карт мало, высоты не хватает или два ряда
 * ничего не выигрывают.
 */
function высотаРядаДляДвух(картВРуке, доступно) {
  if (картВРуке < ПОРОГ_ДВУХ_РЯДОВ) return 0;

  const рука = эл('карты-человека');
  // Высоту полоски берём из вёрстки, а не считаем заново.
  const полоска = рука && рука.clientHeight > 0 ? рука.clientHeight : размерКарты.высота + 18;
  const высотаРяда = Math.floor((полоска - ОТСТУП_РУКИ - ЗАЗОР_РЯДОВ) / 2);
  if (высотаРяда < МИН_ВЫСОТА_В_РЯДУ) return 0;

  // Считаем оба варианта и сравниваем то, ради чего всё затевалось, —
  // ширину полоски, в которую надо попасть пальцем.
  const вОдинРяд = шагВРяду(размерКарты.ширина, картВРуке, доступно);
  const вДваРяда = шагВРяду(размерКарты.ширина, Math.ceil(картВРуке / 2), доступно);
  return вДваРяда > вОдинРяд * ВЫГОДА_ДВУХ_РЯДОВ ? высотаРяда : 0;
}

/**
 * Разложить руку в два ряда. В одном ряду 35 карт превращаются в полоски
 * по 9 точек, и палец попадает в соседнюю; в двух рядах карт вдвое меньше,
 * и каждая шире.
 */
function разложитьДвумяРядами(контейнер, высотаРяда) {
  const карты = контейнер.children;
  if (карты.length === 0) return;
  const ширинаКарты = размерКарты.ширина;   // по ширине карта не ужимается
  const доступно = контейнер.clientWidth || window.innerWidth;
  const вВерхнем = Math.ceil(карты.length / 2);
  const вНижнем = карты.length - вВерхнем;
  const шагВерхнего = шагВРяду(ширинаКарты, вВерхнем, доступно);
  const шагНижнего = шагВРяду(ширинаКарты, вНижнем, доступно);

  for (let i = 0; i < карты.length; i++) {
    const верхний = i < вВерхнем;
    const вРяду = верхний ? вВерхнем : вНижнем;
    const номерВРяду = верхний ? i : i - вВерхнем;
    const шаг = верхний ? шагВерхнего : шагНижнего;
    const занято = ширинаКарты + шаг * (вРяду - 1);
    const старт = Math.max(0, (доступно - занято) / 2);
    карты[i].style.left = Math.round(старт + шаг * номерВРяду) + 'px';
    карты[i].style.top = (верхний ? ОТСТУП_РУКИ : ОТСТУП_РУКИ + высотаРяда + ЗАЗОР_РЯДОВ) + 'px';
  }
  /* Оформлению отдаём самую узкую полоску из двух рядов: подпись должна
     читаться и в том ряду, где карты сжаты сильнее. Нулевой шаг бывает
     у ряда из одной карты — тогда меркой служит второй ряд. */
  записатьШагВеера(контейнер,
    Math.min(шагВерхнего || шагНижнего, шагНижнего || шагВерхнего));
}

/**
 * Можно ли сейчас сходить этой картой. Игра это и так знает — иначе не умела бы
 * отказывать; показываем знание игроку, чтобы он не считал в уме.
 * Не наш ход — возвращаем null: тогда карты остаются обычными, без пометок.
 */
function картаСейчасХодит(карта) {
  const текущая = фаза(партия);
  if (!сейчасМойХод()) return null;
  if (текущая === 'защита') {
    for (const пара of партия.стол) {
      if (!пара.защита && бьёт(карта, пара.атака, партия.козырь)) return true;
    }
    // В переводном ход можно не крыть, а перевести — такая карта тоже ходит.
    return можноПеревестиЭтой(карта);
  }
  if (текущая === 'атака' || текущая === 'подкидывание' || текущая === 'докидывание') {
    /* Слово наше, а класть карту нельзя — значит мы уже сказали «Пас», и его
       вернули нам только затем, чтобы мы закрыли подход. Такие карты красим
       серым: иначе рука зовёт нажать, а нажатие отвечает отказом. Мерка тут
       ровно та же, что и у самого нажатия (см. «тапПоКартеЧеловека»), — если
       они разойдутся, подсветка снова начнёт обещать невозможное. */
    if (текущая !== 'атака' && этоКомпания() && !мнеМожноПодкинуть()) return false;
    return можноПоложить(партия, карта);
  }
  return null;
}

/**
 * Отказ без карты под пальцем: человек нажал туда, где вздрагивать нечему
 * (карта соперника на столе, стопка колоды). Остаются слова и короткий
 * звук — но и этого хватает, чтобы нажатие не выглядело провалившимся.
 */
/**
 * Есть ли в руке хоть одна карта, которой сейчас можно сходить, — та самая
 * «светлая с зелёной чертой». Спрашиваем ровно ту же мерку, по которой
 * рука и красится (см. «картаСейчасХодит»), иначе слова разойдутся с видом.
 */
function естьЧемХодитьСейчас() {
  if (!партия || !партия.руки.человек) return false;
  for (const карта of партия.руки.человек) {
    if (картаСейчасХодит(карта) === true) return true;
  }
  return false;
}

/**
 * Что сказать на повторное нажатие по карте. Обычно объясняем подсветку —
 * человек как раз в этот миг и спрашивает себя, чем же тогда ходить.
 *
 * Но если ходить нечем вовсе (вся рука серая), звать искать зелёную черту —
 * прямая неправда: её нет ни на одной карте, а рядом в той же строке стоит
 * «Подкинуть нечем — нажмите „Бито“». Замер тестировщика: из 149 показов
 * подсказки 70 пришлись ровно на такую руку. Тогда говорим то, что есть.
 */
function словаПроВыборКарты() {
  return естьЧемХодитьСейчас()
    ? ТЕКСТ_ПРО_ПОДСВЕТКУ
    : 'Подходящей карты в руке сейчас нет';
}

/* Что сказали в прошлый отказ. Нужно ровно для одного: не отвечать дважды
   подряд теми же словами — на телефоне это неотличимо от «игра не ответила».
   Второй раз объясняем не запрет, а подсветку: человек как раз в этот миг
   и спрашивает себя, чем же тогда ходить. */
let прошлыеСловаОтказа = '';

function отказатьСловами(текст) {
  звукОтказа();
  // Запоминаем здесь, в одном месте: так «повтор» видят все отказы сразу,
  // от какой бы части экрана он ни пришёл.
  прошлыеСловаОтказа = текст;
  показатьОтказ(текст);
  /* Ход соперника был назначен ещё до нажатия и придёт по своему расписанию —
     отодвигаем его, иначе он сотрёт и слова, и вздрагивание карты. Двигаем
     после «показатьОтказ»: он же и говорит, сколько теперь ждать. */
  отодвинутьОтложенныйХод();
  // Отказ сервера может прийти, когда партии уже нет (человек вышел в меню,
  // пока ход летел): рисовать подсказку тогда нечем и незачем.
  if (партия) рисоватьПодсказкуИКнопки();
}

/* ---------------------------------------------------------------------
   ПОЧЕМУ ЭТОТ КУСОК ТАКОЙ, КАКОЙ ОН ЕСТЬ. Живой новичок сказал про игру
   самое обидное: «нажатие на карту, которой сейчас нельзя, — ноль реакции,
   я решил, что игра подвисла». Прежде чем чинить, это замерили: прогон
   на 125 партий тыкал в каждую карту руки на своём ходу и считал ответы.
   Молчаливых нажатий не нашлось НИ ОДНОГО: карта вздрагивала 223 раза,
   строка подсказки менялась 80 раз.

   То есть игра отвечала всегда — ответ не доходил. Причин две, и обе
   не в коде, а в том, как это выглядит в руке:
     — вздрагивает карта, по которой только что попал палец, а на телефоне
       палец её и закрывает;
     — на ПОВТОРНЫЙ тап по той же карте строка подсказки не менялась вовсе:
       текст отказа тот же самый, экран замирал буквально.
   Отсюда и починка: отказ называет причину человеческими словами, а если
   его повторяют слово в слово — вторым разом объясняем не запрет, а как
   вообще отличить карту, которой можно ходить.

   ЭТО ВАЖНО ДЛЯ ТОГО, КТО БУДЕТ ЧИТАТЬ ПОСЛЕ НАС: не «чините» молчание
   заново, его тут не было. Чинилась заметность ответа.
   --------------------------------------------------------------------- */

/**
 * Достоинства на столе человеческим списком: «6 или 9».
 *
 * Длинный список сюда не годится: на столе бывает до семи разных достоинств,
 * и строка «Подкидывают только то, что уже на столе: 6, 7, 8, 9, 10, В или Д»
 * не влезает ни в один телефон — её обрезает на полуслове. Поэтому перечисляем
 * не больше двух, а дальше говорим общим правилом: какие карты подойдут,
 * человеку и так видно по зелёной черте.
 */
const ДОСТОИНСТВ_СПИСКОМ = 2;

function достоинстваСписком() {
  const достоинства = достоинстваНаСтоле(партия);
  if (достоинства.length === 0 || достоинства.length > ДОСТОИНСТВ_СПИСКОМ) return '';
  if (достоинства.length === 1) return достоинства[0];
  return достоинства.join(' или ');
}

/**
 * Почему этой картой сейчас не сходить и не подкинуть. Причин у запрета
 * три, и они совсем разные — общее «нельзя» не объясняло ни одной.
 * Порядок тот же, что в самом правиле (см. «можноПоложить»).
 */
function почемуНельзяПоложить(карта) {
  if (партия.стол.length >= МАКС_КАРТ_В_ПОДХОДЕ) {
    return 'В подход кладут не больше шести карт';
  }
  const защитник = защищается(партия);
  const рукаЗащитника = партия.руки[защитник] ? партия.руки[защитник].length : 0;
  if (неотбитых(партия) >= рукаЗащитника) {
    return 'Больше не подкинуть — отбиваться будет нечем';
  }
  if (фаза(партия) === 'атака') return 'Сейчас этой картой ходить нельзя';
  const список = достоинстваСписком();
  return список
    ? названиеКарты(карта) + ' не подкинуть: на столе только ' + список
    : названиеКарты(карта) + ' не подкинуть: такой карты на столе нет';
}

/**
 * Почему этой картой не отбиться. Называем обе карты и правило: новичок
 * жаловался, что «не отбиться» — это про какую из карт на столе и почему,
 * он понять не мог. Масть цели ставим значком: «нужна ♠ старше или козырь»
 * и короче, и точнее, чем «карта той же масти, но старше».
 */
/* Старшая карта в игре — туз. Берём его из списка правил, а не пишем буквой:
   список общий на обе колоды, и подсказка не разойдётся с правилами. */
const СТАРШЕЕ_ДОСТОИНСТВО = ВСЕ_ДОСТОИНСТВА[ВСЕ_ДОСТОИНСТВА.length - 1];

function почемуНельзяОтбиться(карта) {
  let цель = null;
  for (const пара of партия.стол) {
    if (!пара.защита) { цель = пара.атака; break; }
  }
  if (!цель) return 'Отбивать сейчас нечего';
  const чем = названиеКарты(карта) + ' не побьёт ' + названиеКарты(цель);
  const почемуПеревод = почемуНельзяПеревести(карта);
  const хвост = почемуПеревод ? ', и ' + почемуПеревод : '';
  /* Туз — старшая карта, и «нужна ♠ старше» ведёт в тупик: старше не бывает.
     Говорим то, что правда: некозырного туза бьёт только козырь, а козырного
     не бьёт ничто. */
  if (цель.имя === СТАРШЕЕ_ДОСТОИНСТВО) {
    return цель.масть === партия.козырь
      ? чем + ' — козырного туза не бьёт ничто' + хвост
      : чем + ' — туза бьёт только козырь' + хвост;
  }
  if (цель.масть === партия.козырь) return чем + ' — нужен козырь старше' + хвост;
  return чем + ' — нужна ' + цель.масть + ' старше или козырь' + хвост;
}

/**
 * Почему этой картой не перевести ход. Возвращает пустую строку, если
 * человек и не собирался переводить (достоинство не с этого стола) или
 * если переводить как раз можно.
 *
 * Ревьюер поймал на живом: в переводном человек кладёт карту того же
 * достоинства, явно желая перевести, а игра отвечает про «не побьёт»
 * и про перевод молчит вовсе. Причины перечислены в том же порядке,
 * что и в самом правиле (см. «можноПеревести»).
 */
function почемуНельзяПеревести(карта) {
  if (!партия.переводной || фаза(партия) !== 'защита') return '';
  if (достоинстваНаСтоле(партия).indexOf(карта.имя) === -1) return '';
  if (неотбитых(партия) !== партия.стол.length) return 'перевести уже поздно';
  if (партия.стол.length >= МАКС_КАРТ_В_ПОДХОДЕ) return 'переводить некуда';
  const следующий = ктоОтбиваетсяЗа(партия, защищается(партия));
  if (следующий === защищается(партия)) return 'переводить некому';
  const рука = партия.руки[следующий] || [];
  if (рука.length < партия.стол.length + 1) return 'у следующего мало карт';
  return '';
}

/**
 * Отказ по карте: пометка под пальцем плюс объяснение в подсказке.
 * Руку целиком не перерисовываем — иначе пометка отказа тут же исчезнет.
 *
 * Третьим доводом — что сказать, если человек повторил то же самое нажатие.
 * Не сказали — повторим прежние слова: так бывает у отказов, которые
 * от выбора карты не зависят вовсе («сейчас ходит Бот 3»).
 */
function отказатьПоКарте(индекс, текст, словаНаПовтор) {
  const слова = (словаНаПовтор && текст === прошлыеСловаОтказа) ? словаНаПовтор : текст;
  отказатьСловами(слова);
  вздрогнуть(эл('карты-человека'), индекс);
}

/**
 * Заставить карту вздрогнуть — тот самый ответ под пальцем.
 * Вынесено отдельно, потому что вздрагивают карты в двух местах:
 * своя рука и карта атаки на столе.
 */
/* Чем сейчас вздрагивает карта: по какому таймеру пометку снимут и с какого
   узла. Без этого второй тап раньше 0,7 секунды гасился ТАЙМЕРОМ ПЕРВОГО:
   пометка вспыхивала и через несколько миллисекунд пропадала — со стороны
   опять «ноль реакции». Теперь прежний таймер снимается перед новым. */
let таймерВздрагивания = null;
let ктоВздрагивает = null;

function вздрогнуть(веер, индекс) {
  const узел = веер ? веер.children[индекс] : null;
  if (!узел) return;
  // На столе вздрагивать должна сама карта, а не связка «атака + защита».
  const кто = узел.classList.contains('пара') ? (узел.children[0] || узел) : узел;
  if (таймерВздрагивания !== null) {
    clearTimeout(таймерВздрагивания);
    таймерВздрагивания = null;
    // Прошлая карта могла быть другой — снимаем пометку и с неё.
    if (ктоВздрагивает && ктоВздрагивает !== кто) {
      ктоВздрагивает.classList.remove('карта--отказ');
    }
  }
  ктоВздрагивает = кто;
  кто.classList.remove('карта--отказ');
  // Пауза в один кадр нужна, чтобы пометка сработала и на повторный тап
  // по той же карте: без неё браузер не заметит, что класс возвращали.
  requestAnimationFrame(function () {
    кто.classList.add('карта--отказ');
  });
  таймерВздрагивания = setTimeout(function () {
    таймерВздрагивания = null;
    ктоВздрагивает = null;
    кто.classList.remove('карта--отказ');
  }, ПОКАЗ_ОТКАЗА);
}

/**
 * Отказ по карте на столе. Раньше он был только словами внизу экрана,
 * и на повторное нажатие не менялось ничего: новичок записал это в
 * «ноль реакции». Теперь чужая карта отвечает тем же вздрагиванием,
 * что и своя, — ответ появляется там, куда смотрит палец.
 */
function отказатьПоПаре(индексПары, текст, словаНаПовтор) {
  const слова = (словаНаПовтор && текст === прошлыеСловаОтказа) ? словаНаПовтор : текст;
  отказатьСловами(слова);
  вздрогнуть(эл('стол'), индексПары);
}

function рисоватьРукуЧеловека() {
  const веер = эл('карты-человека');
  if (!веер) return;
  веер.innerHTML = '';

  const доступно = веер.clientWidth || window.innerWidth;
  const высотаРяда = высотаРядаДляДвух(партия.руки.человек.length, доступно);

  партия.руки.человек.forEach(function (карта, индекс) {
    const узел = элементКарты(карта);
    // Подсказка глазами: чем можно ходить прямо сейчас, а чем нельзя.
    const ходит = картаСейчасХодит(карта);
    if (ходит === true) узел.classList.add('карта--можно');
    else if (ходит === false) узел.classList.add('карта--нельзя');
    if (высотаРяда) {
      // Ужимаем карту только по высоте: её не хватает на два ряда. Ширину
      // не трогаем — от неё оформление считает кегль подписи, а ужатая
      // пропорционально карта на невысоком экране выходит шириной в 21
      // точку, и номинал на ней уже не прочесть.
      узел.style.setProperty('--в', высотаРяда + 'px');
    }
    if (индекс === выбраннаяКарта) {
      узел.classList.add('карта--выбрана');
      // Подъём в два ряда не привязан к зазору — это своя величина.
      if (высотаРяда) узел.style.transform = 'translateY(-' + ПОДЪЁМ_В_ДВА_РЯДА + 'px)';
    }
    узел.addEventListener('click', function () { тапПоКартеЧеловека(индекс); });
    веер.appendChild(узел);
  });

  if (высотаРяда) разложитьДвумяРядами(веер, высотаРяда);
  else разложитьВеером(веер, ОТСТУП_РУКИ);
}

/** Есть ли у человека хоть одна карта, которую сейчас разрешено подкинуть. */
function естьЧемПодкинуть() {
  for (const карта of партия.руки.человек) {
    if (можноПоложить(партия, карта)) return true;
  }
  return false;
}

/** Есть ли чем крыть хоть одну карту на столе. */
function естьЧемОтбиться() {
  for (const пара of партия.стол) {
    if (пара.защита) continue;
    for (const карта of партия.руки.человек) {
      if (бьёт(карта, пара.атака, партия.козырь)) return true;
    }
  }
  return false;
}

/**
 * Можно ли этой картой перевести ход (только в переводном дураке).
 *
 * За СЕТЕВЫМ столом компанией возможность перевода считает сервер: она
 * зависит от того, сколько карт у следующего игрока, а чужие руки браузеру
 * не присылают. От самой карты там зависит одно — её достоинство:
 * прочие условия перевода одинаковы для всей руки. В игре с ботами
 * правила лежат рядом, поэтому спрашиваем их напрямую.
 */
function можноПеревестиЭтой(карта) {
  if (!партия || !карта) return false;
  if (очередьСчитаетСервер()) {
    return партия.могуПеревести === true &&
           достоинстваНаСтоле(партия).indexOf(карта.имя) !== -1;
  }
  return можноПеревести(партия, карта);
}

/** Есть ли в руке хоть одна карта, которой можно перевести ход. */
function естьЧемПеревести() {
  for (const карта of партия.руки.человек) {
    if (можноПеревестиЭтой(карта)) return true;
  }
  return false;
}

/** Что делать с поднятой картой — когда выбор есть, его надо назвать вслух. */
function текстВыбраннойКарты() {
  const карта = партия.руки.человек[выбраннаяКарта];
  if (карта && можноПеревестиЭтой(карта)) {
    // Этой картой можно и крыть, и переводить — называем оба выхода.
    for (const пара of партия.стол) {
      if (!пара.защита && бьёт(карта, пара.атака, партия.козырь)) {
        return 'Укажите карту на столе или нажмите «Перевести»';
      }
    }
    // Крыть ею нечего: остаётся только перевод, так и говорим.
    return 'Этой картой можно только перевести — нажмите «Перевести»';
  }
  return 'Укажите карту на столе, которую бьёте';
}

/** Что от человека ждут прямо сейчас. Эта строка видна всегда. */
function текстДействия() {
  const текущая = фаза(партия);
  const ходит = ктоХодит(партия);
  const человекАтакует = партия.атакует === 'человек';

  /* Карт в руке нет, а слово наше — игра сейчас нажмёт «Пас» сама
     (см. «пораПасоватьСамим»), и требовать нажатия было бы издевательством:
     «подкинуть нечем, жмите „Пас“» — а чем жать, если рука пуста.
     Стоит эта проверка первой нарочно: и вдвоём, и компанией слова одни. */
  if (пораПасоватьСамим()) return ТЕКСТ_ПАСУЕМ_ЗА_ВАС;

  // За столом компанией всё рассказывается иначе: там мало сказать
  // «соперник», надо назвать, кто именно ходит и кто отбивается.
  if (этоКомпания()) return текстДействияВКомпании();

  if (текущая === 'атака') {
    return человекАтакует ? 'Ваш ход — выберите карту' : 'Соперник ходит…';
  }
  if (текущая === 'защита') {
    if (ходит !== 'человек') return 'Соперник отбивается…';
    if (выбраннаяКарта !== null) return текстВыбраннойКарты();
    // Перевод проверяем раньше защиты: крыть бывает нечем, а перевести можно.
    if (естьЧемПеревести()) return 'Отбивайтесь или переведите — выберите карту';
    // Не зовём выбирать карту, если крыть нечем: игра это знает заранее.
    return естьЧемОтбиться()
      ? 'Отбивайтесь — выберите карту'
      : 'Отбиться нечем — жмите «Беру»';
  }
  if (текущая === 'подкидывание') {
    if (!человекАтакует) return 'Соперник думает, что подкинуть…';
    return естьЧемПодкинуть()
      ? 'Можете подкинуть или нажать «Бито»'
      : 'Подкинуть нечем — нажмите «Бито»';
  }
  if (текущая === 'докидывание') {
    if (!человекАтакует) return 'Вы забираете карты. Соперник может подкинуть…';
    // Тексты нарочно короткие: вместе с рассказом о событии они делят одну
    // строку подсказки, а влезут ли — решает сама игра, спрашивая страницу
    // (см. «влезлоВСтроку»). Что не влезло, будет показано порознь.
    return естьЧемПодкинуть()
      ? 'Соперник берёт — можно подкинуть или «Готово»'
      : 'Соперник берёт — подкинуть нечем, жмите «Готово»';
  }
  // Партия доиграна: между последним ходом и экраном итога строка не пустует.
  return 'Партия окончена';
}

/**
 * То же самое, но за столом компанией. Отдельно от игры вдвоём нарочно:
 * там довольно слова «соперник», а здесь соперников до пяти, и главный
 * вопрос человека — кто именно сейчас ходит и кто отбивается.
 *
 * СТРОКИ ЗДЕСЬ НАРОЧНО КОРОТКИЕ, и это не вкусовщина. Внизу экрана одна
 * строка на всё, высота у неё неподвижная, а лишнее не переносится, а
 * срезается — живой игрок за столом на троих уже прочитал обрубок
 * «Бот 3 берёт карты…».
 *
 * Мерить надо ПАРУ целиком: слева рассказ о событии (он приходит с сервера,
 * см. РАССКАЗ_О_СОБЫТИИ в server/партия-по-сети.js), потом « · », потом
 * фраза отсюда. Влезет ли пара, игра теперь спрашивает у самой страницы
 * («влезлоВСтроку»), а не считает знаки: перенос слов решает больше, чем
 * их число. Но короче — по-прежнему лучше: не влезшая пара показывается
 * порознь, и человек видит за раз только половину. Длину смотреть
 * командой `node tests/самая-длинная-подсказка.js`, на глаз не прикидывать.
 *
 * И помните про имя: за столом компанией оно подставляется в обе половинки
 * разом и бывает длиной до 16 знаков — каждое лишнее слово во фразе
 * дорожает вдвое.
 */
function текстДействияВКомпании() {
  const текущая = фаза(партия);
  if (текущая === 'конец') return 'Партия окончена';
  if (пораПасоватьСамим()) return ТЕКСТ_ПАСУЕМ_ЗА_ВАС;
  if (пораСказатьПроПаруСоперников()) return словаПроПодходМимо();

  if (текущая === 'защита') {
    if (!этоЯОтбиваюсь()) {
      const кто = имяТого('отбивается');
      return (кто || 'Соперник') + ' отбивается…';
    }
    if (выбраннаяКарта !== null) return текстВыбраннойКарты();
    if (естьЧемПеревести()) return 'Отбивайтесь или переведите — выберите карту';
    return естьЧемОтбиться()
      ? 'Отбивайтесь — выберите карту'
      : 'Отбиться нечем — жмите «Беру»';
  }

  if (текущая === 'атака') {
    if (сейчасМойХод()) return 'Ваш ход — выберите карту';
    const кто = имяТого('ходит');
    return 'Ходит ' + (кто || 'соперник') + '…';
  }

  // Подкидывание и докидывание: слово обходит круг, и оно бывает не наше.
  const берёт = имяТого('отбивается');
  if (!сейчасМойХод()) {
    if (текущая === 'докидывание') {
      return этоЯОтбиваюсь()
        ? 'Вы берёте — вам ещё могут подкинуть…'
        : (берёт || 'Соперник') + ' берёт — ждём остальных…';
    }
    const кто = имяТого('ходит');
    return кто ? кто + ' думает, что подкинуть…' : 'Ждём соперников…';
  }
  /* Слово наше, а класть карту нельзя — значит мы уже сказали «Пас», и слово
     вернулось только затем, чтобы закрыть подход. Говорим об этом прямо,
     иначе человек будет тыкать в карты и получать отказы. */
  if (!мнеМожноПодкинуть()) {
    return текущая === 'докидывание'
      ? (берёт || 'Соперник') + ' берёт — вы пасовали, жмите «Пас»'
      /* Было «Подкидывать больше некому» — и длинно, и мимо: некому тут ни при
         чём, дело в нас самих. Слово вернулось только потому, что мы пасовали
         (иначе сервер не выключил бы «могуПодкинуть»), и говорим ровно это —
         теми же словами, что и в соседней ветке про докидывание. */
      : 'Вы пасовали — жмите «Пас»';
  }
  const хвост = естьЧемПодкинуть() ? 'подкиньте или «Пас»' : 'подкинуть нечем, жмите «Пас»';
  if (текущая === 'докидывание') return (берёт || 'Соперник') + ' берёт — ' + хвост;
  return 'Ваше слово: ' + хвост;
}

/* Слова тому, кого давно не звали.

   ОБЕЩАНИЯ ЗДЕСЬ НЕТ, И ЭТО ГЛАВНОЕ. Раньше стояло «ваш ход ещё придёт»,
   и замер показал, чего это стоит: 29 партий из 500 кончались цепочкой
   «ваш ход ещё придёт» → «Партия окончена» → «Ваша пара проиграла», и во
   всех ста процентах таких случаев человек проигрывал — соперники скидывали
   последние карты и выходили, а он так и не сходил. Игра не может знать,
   что партия не кончится через два хода, значит и обещать не вправе.
   Теперь надпись описывает настоящее.

   И называет она то, что есть на самом деле. В подходе участвуют ровно
   двое: нападающий из одной пары и отбивающийся из другой. Раз человек
   не участвует и не в нападающей паре (см. условие ниже), значит его пару
   представляет напарник — и отбивается именно он, а не «пара соперников»
   играет сама с собой. На плашках это видно, и слова обязаны совпадать
   с тем, что человек видит глазами. */
const ТЕКСТ_ПОДХОД_МИМО = 'Подход мимо вас — играет напарник';

/* Отдельные слова на тот случай, когда напарник сказал «Беру».

   Ради чего. Прежняя надпись висела не мигая весь подход и к середине его
   переставала быть правдой: напарник объявил «Беру» и отбиваться перестал,
   а строка всё ещё уверяла «Отбивается ваш напарник» — да ещё и спорила
   с новостью слева: «Бот 3 не смог отбиться · Отбивается ваш напарник».
   Замер тестировщика: восьмая-десятая часть времени показа, 21 партия из 53.
   К тому же «напарник берёт карты» — новость про НАШУ пару: карты уходят
   к нам, и сказать это полезнее, чем повторять, что подход не наш. */
const ТЕКСТ_НАПАРНИК_БЕРЁТ = 'Подход мимо вас — напарник берёт карты';

/**
 * Что написать прямо сейчас. Слова следуют за столом, а не за подходом
 * целиком: «отбивается» верно не всегда, а «играет напарник» верно в любой
 * миг показа — и когда стол пуст, и когда всё уже отбито.
 *
 * И то и другое нарочно коротко. Фраза встаёт справа от рассказа о ходе,
 * а вдвоём они должны влезть в строку подсказки: длинная пара («Бот 3 отбил
 * 10♠ картой В♣ · Играет напарник с соперником — этот подход мимо вас»)
 * выходила в 79 знаков — ровно на границу среза, и тогда игра показывает
 * что-то одно, а объяснение до человека не доходит вовсе.
 */
function словаПроПодходМимо() {
  return партия.берёт ? ТЕКСТ_НАПАРНИК_БЕРЁТ : ТЕКСТ_ПОДХОД_МИМО;
}

/**
 * Уместна ли эта надпись при таком положении стола.
 *
 * Функция нарочно ЧИСТАЯ: смотрит только на свои доводы и ничего не знает
 * ни про экран, ни про счётчики игры. Поэтому её может спросить и проверка
 * из Node — вместо того чтобы пересказывать условие своими словами
 * и однажды разойтись с игрой (в этом проекте копии правил расходились
 * с игрой уже трижды).
 *
 * Условий семь, и каждое стоит здесь по своей причине:
 *   — только игра ПАРАМИ: там обход до шести подходов заложен самим
 *     правилом («пока напарник нападавшего в игре, ход остаётся
 *     у нападавшей пары»). В непарных слово идёт по кругу и очередь видна;
 *   — партия не доиграна: мёртвому столу объяснять нечего;
 *   — подходов мимо человека накопилось довольно (до двух это обычное дело);
 *   — прямо сейчас слово не у человека и отбивается не он. Спрашиваем это
 *     у правил, чтобы проверка из Node получала тот же ответ, что и экран;
 *     сам экран за сетевым столом спрашивает вдобавок сервер — см. обёртку
 *     «пораСказатьПроПаруСоперников»;
 *   — В ЭТОМ подходе человек ещё не играл. Без этой проверки надпись
 *     зажигалась прямо посреди его собственного хода: счёт пропущенных
 *     подходов сбрасывается только когда стол опустеет, а слово успевает
 *     уйти к соседу раньше. На экране выходило «Вы сходили 10♣ · …играет
 *     пара соперников» — три четверти всех показов были такими;
 *   — человек не в НАПАДАЮЩЕЙ паре. Если нападает напарник, человеку
 *     вправе достаться слово, едва тот скажет «Пас», — и вместо полезного
 *     «Бот 2 думает, что подкинуть…» он читал бы, что его тут нет;
 *   — карты на руках: без них у него своя надпись, «пасуем за вас».
 */
function надписьПроНапарникаУместна(партия, подходовМимо, былЯвПодходе) {
  if (!партия || !партия.парами || партия.завершена) return false;
  if (подходовМимо < ПОДХОДОВ_МИМО_ДО_СЛОВ) return false;
  if (былЯвПодходе) return false;
  if (ктоХодит(партия) === 'человек' || защищается(партия) === 'человек') return false;
  if (самИлиНапарник(партия, партия.атакует, 'человек')) return false;
  const рука = партия.руки['человек'];
  return Boolean(рука && рука.length > 0);
}

/** То же самое, но про партию, которая идёт на экране прямо сейчас. */
function пораСказатьПроПаруСоперников() {
  /* Экран знает про очередь точнее правил: за сетевым столом её считает
     сервер. Поэтому свой ход спрашиваем и у экрана тоже, а всё остальное —
     у чистой мерки выше. */
  if (сейчасМойХод() || этоЯОтбиваюсь()) return false;
  return надписьПроНапарникаУместна(партия, счётПодходовМимо.подходовМимо,
                                    счётПодходовМимо.былЯвПодходе);
}

/**
 * Почему нажатие не сработало, когда слово не наше. Слова берём те же, что
 * в подсказке: вдвоём соперник один и зовётся «соперник», а за столом
 * компанией их до пяти — там называем имя, иначе непонятно, кого ждать.
 */
function текстНеВашХод() {
  const компания = этоКомпания();
  // Пока идёт защита, ждут именно отбивающегося — про него и говорим.
  if (фаза(партия) === 'защита' && !этоЯОтбиваюсь()) {
    const кто = компания ? имяТого('отбивается') : '';
    return 'Сейчас отбивается ' + (кто || 'соперник');
  }
  const кто = компания ? имяТого('ходит') : '';
  return 'Сейчас ходит ' + (кто || 'соперник');
}

/**
 * Могу ли я сейчас закончить свой подход — сказать «Бито», «Готово» или «Пас».
 * Вдвоём это по-прежнему право того, кто ходил. В компании закончить подход
 * может тот, чьё сейчас слово, — и только слово тут и спрашиваем.
 *
 * Раньше спрашивали ещё и «могу ли подкинуть», и это оказалось ошибкой:
 * слово бывает и у того, кому класть карту уже нельзя, — тогда кнопка
 * пропадала, и закончить подход становилось некому. Партия у живых игроков
 * из-за этого встала намертво. С тех пор чинили с двух сторон: кнопку
 * показываем по одному лишь слову, а само слово спасовавшему больше
 * не достаётся (см. «ктоХодит»).
 */
function мнеМожноЗакончитьПодход(текущая) {
  if (текущая !== 'подкидывание' && текущая !== 'докидывание') return false;
  if (этоКомпания()) return сейчасМойХод();
  return партия.атакует === 'человек';
}

/**
 * Надпись на кнопке конца подхода. Вдвоём всё как было: отбился соперник —
 * «Бито», забирает карты — «Готово». В компании эта же кнопка значит другое:
 * «я больше не подкидываю, пусть решают остальные», и это называется «Пас».
 */
function надписьЗавершения(текущая) {
  if (этоКомпания()) return 'Пас';
  return текущая === 'докидывание' ? 'Готово' : 'Бито';
}

/**
 * Кнопка «Перевести». В разметке её нет — перевод появился позже, поэтому
 * кнопку создаём из кода и кладём в ту же строку, где «Бито» и «Беру».
 */
function кнопкаПеревода() {
  const готовая = document.getElementById('кнопка-перевести');
  if (готовая) return готовая;
  const панель = эл('панель-кнопок');
  if (!панель) return null;
  const кнопка = document.createElement('button');
  кнопка.id = 'кнопка-перевести';
  кнопка.className = 'кнопка кнопка--перевод скрыт';
  кнопка.textContent = 'Перевести';
  кнопка.addEventListener('click', нажатьПеревести);
  панель.appendChild(кнопка);
  return кнопка;
}

/**
 * Куда писать текст подсказки: во вложенный span внутри коробки.
 * Коробка при этом стоит неподвижно и держит свою высоту, а цветная плашка
 * обтягивает текст — поэтому стол больше не подпрыгивает, когда сообщение
 * выросло в три строки, а через три секунды сложилось обратно в две.
 *
 * ЛОВУШКА для того, кто будет править это после нас: запись
 * «подсказка.textContent = …» прямо в коробку стирает всё, что внутри, —
 * первый же такой вызов уничтожит span, и дальше игра будет писать в пустоту.
 * Текст подсказки ставить только через эту функцию.
 *
 * Запасной путь. Telegram у части игроков отдаёт страницу из своей памяти,
 * старую — без вложенного span. Тогда пишем в саму коробку, как раньше:
 * высота опять будет прыгать, но подсказки будут видны, а без запасного пути
 * такие игроки увидели бы пустую строку и играли бы вообще без подсказок.
 */
function строкаПодсказки() {
  const коробка = эл('подсказка');
  if (!коробка) return null;
  // Намеренно без «эл»: отсутствие span — не поломка, ругаться в консоль не о чем.
  return document.getElementById('подсказка-текст') || коробка;
}

/**
 * Влезло ли в строку подсказки то, что в неё только что написали.
 *
 * Спрашиваем не себя, а страницу: коробка подсказки держит неподвижную высоту
 * и прячет лишнее (overflow: hidden), поэтому «не влезло» — это когда
 * содержимому нужно больше высоты, чем у коробки есть. Такая мерка сама
 * подстраивается под любой экран, кегль и длину слов, а счёт знаков — нет:
 * на живом экране пара в 81 знак не влезла, а пара в 85 влезла.
 *
 * Довод «текст» нужен только запасному пути — там, где высоты не существует
 * вовсе (Node, поддельный браузер проверок). Тогда меряем знаками.
 *
 * Мерка одна на всю игру и живёт здесь одна. Расхождение двух копий одной
 * мерки в этом проекте уже трижды было причиной бед.
 */
/* Допуск в одну точку — на дробные доли: браузер округляет высоту строки,
   и ровно влезающий текст порой отличается на десятую долю точки.

   ЧТО С ЧЕМ СРАВНИВАЕТСЯ, это здесь главное. Сравниваем внутренность ОДНОГО
   узла — плашки со словами: сколько места её содержимому НУЖНО
   («scrollHeight», «scrollWidth») против того, сколько ей ОТВЕДЕНО
   («clientHeight», «clientWidth»). Один и тот же узел, одна и та же величина.
   Точно так же меряет проверка тестировщика (tests/влезает-ли-отказ-в-строку.js),
   и допуск там тот же самый — одна точка сверх отведённого.

   А вот с допуском 2,5 точки в стендах вёрстки путать нельзя, хотя число
   рядом: там меряют другую величину — насколько буквы вылезли ЗА КОРОБКУ
   (сумма выхода вверх и вниз, по рамкам самих букв). Буквы всегда стоят
   чуть свободнее своей строки, поэтому пара точек выхода есть даже там,
   где ничего не срезано. Здесь же сравниваются строки, а не буквы:
   сколько высоты просят строки текста против того, сколько им отведено.
   Величины разные, и совпадать числа не обязаны.

   Прошлая попытка мерила не то и не срабатывала ни разу: высота коробки
   против высоты плашки. Обе упираются в один потолок — у плашки
   «max-height: 100%», у коробки «overflow: hidden», и лишние строки
   обрезаются ВНУТРИ плашки, до коробки не доходя. Оба числа всегда
   отвечали «помещается», а на экране текст резало пополам. */
const ЗАПАС_СТРОКИ = 1;

function влезлоВСтроку(текст, гдеИзмерить) {
  /* Вторым доводом можно назвать другой узел — например строку связи над
     столом: она тоже одна на всё и тоже режет лишнее. Не сказали — меряем
     строку подсказки, как и звали раньше (на этом стоит стенд проверки). */
  const слова = гдеИзмерить || строкаПодсказки();
  const отведеноВысоты = Number(слова && слова.clientHeight);
  /* Высоты нет вовсе — мерить нечем: игровой экран спрятан (тогда и показывать
     некому) либо страницы нет совсем. Тогда считаем знаки, см. ЗНАКОВ_В_СТРОКУ. */
  if (!Number.isFinite(отведеноВысоты) || отведеноВысоты <= 0) {
    return String(текст).length <= ЗНАКОВ_В_СТРОКУ;
  }
  const нужноВысоты = Number(слова.scrollHeight);
  const нужноШирины = Number(слова.scrollWidth);
  const отведеноШирины = Number(слова.clientWidth);
  if (Number.isFinite(нужноВысоты) && нужноВысоты > отведеноВысоты + ЗАПАС_СТРОКИ) return false;
  // Ширину тоже спрашиваем: длинное слово, которое негде перенести, режется вбок.
  if (Number.isFinite(нужноШирины) && Number.isFinite(отведеноШирины) &&
      отведеноШирины > 0 && нужноШирины > отведеноШирины + ЗАПАС_СТРОКИ) return false;
  return true;
}

/** Строка подсказки и кнопки хода. */
function рисоватьПодсказкуИКнопки() {
  const текущая = фаза(партия);
  const действие = текстДействия();

  // Сначала рассказ о событии, через точку — напоминание, что делать.
  const подсказка = строкаПодсказки();
  if (подсказка) {
    /* ПОРЯДОК ЗДЕСЬ НАРОЧНЫЙ: сперва пометки, потом текст и замер.

       Пометки меняют место, куда влезают слова. «Ваш ход» рисует слева
       кружок-огонёк — восемь точек плюс восемь отступа: у слов на шестнадцать
       точек меньше, и перенос выходит другой. Свежесть меняет начертание
       на жирное, а жирные буквы шире обычных примерно на девятую часть.
       Повесь пометки после замера — и мерить будешь одно, а рисовать другое. */
    /* Обе пометки висят на тексте, а не на коробке: и та и другая рисуют
       плашку, а плашка должна обтягивать слова. Останься они на коробке —
       под коротким сообщением висел бы пустой цветной прямоугольник
       в три строки высотой. */
    /* Подсвечиваем только свежую новость. Остывшее сообщение остаётся
       на экране обычным текстом: прочитать, что случилось, можно и через
       минуту, но в глаза оно уже не бросается и с новостями не спорит. */
    подсказка.classList.toggle('подсказка--событие', Boolean(событие) && остатокСобытия() > 0);
    // Отдельная пометка «сейчас ходите вы» — её оформление задаёт style.css.
    подсказка.classList.toggle('подсказка--ваш-ход', сейчасМойХод());

    /* Строка одна на двоих: слева новость, справа напоминание, что делать.
       Пишем пару и тут же спрашиваем страницу, влезла ли она. Не влезла —
       показываем что-то одно, потому что срезанная пара не читается вовсе:
       лишнее не переносится, а срезается сверху и снизу, то есть портится
       всё сообщение сразу.

       Что оставить из двух: пока новость свежая — её (человек только что
       что-то сделал и ждёт ответа), а как остыла — напоминание (оно нужно
       всегда, и прятать его надолго нельзя: тому, кто застрял, именно оно
       и говорит, что делать).

       Мерка одна на любые пары, не только на отказы. Раньше сторожили только
       отказы, а длинный рассказ вроде «Ян возвращается за стол — дальше
       играет вместо бота» уходил на экран любой длины и срезался ровно так же. */
    const пара = событие && действие ? событие + ' · ' + действие : '';
    подсказка.textContent = пара || событие || действие;
    if (пара && !влезлоВСтроку(пара)) {
      подсказка.textContent = остатокСобытия() > 0 ? событие : действие;
    }
  }

  const можноБито = мнеМожноЗакончитьПодход(текущая);
  const можноБеру = текущая === 'защита' && сейчасМойХод();
  /* Перевод показываем только на поднятую карту: одной и той же картой
     часто можно и отбиться, и перевести, и выбирать за человека нельзя.
     Пока карта не поднята, кнопке нечем работать — и её нет. */
  const можноПеревод = выбраннаяКарта !== null &&
                       можноПеревестиЭтой(партия.руки.человек[выбраннаяКарта]);

  написать('кнопка-завершить', надписьЗавершения(текущая));
  const завершить = эл('кнопка-завершить');
  // Пометка для оформления: «Пас» — это не то же самое, что «Бито».
  if (завершить) завершить.classList.toggle('кнопка--пас', этоКомпания());
  показатьЭлемент('кнопка-завершить', можноБито);
  показатьЭлемент('кнопка-беру', можноБеру);
  const перевод = кнопкаПеревода();
  if (перевод) перевод.classList.toggle('скрыт', !можноПеревод);
}

/** Единственная точка отрисовки: экран целиком собирается заново по состоянию. */
/* Сколько подходов подряд человека не звали ни нападать, ни отбиваться.

   Зачем считать. В игре парами это бывает и в совершенно здоровой партии:
   пока напарник нападавшего в игре, ход остаётся у нападавшей пары, и пара
   напротив может обмениваться подходами между собой, пока круг не дойдёт
   до человека. Замер тестировщика на 64 тысячах партий: вдвоём такого нет
   вовсе, втроём бывает один подход, вчетвером два, а вчетвером ПАРАМИ —
   до шести подряд.

   А главное — отличить это от настоящей поломки глазами нельзя: экран
   одинаковый, твоя плашка бездействует, играют двое других. Разница только
   в будущем. Поэтому игра сама говорит человеку, что его слово вернётся
   (см. словаПроПодходМимо). */
const ПОДХОДОВ_МИМО_ДО_СЛОВ = 2;

/** Счёт с чистого листа: подходов мимо не было, стол пуст. */
function пустойСчётПодходов() {
  return { подходовМимо: 0, былЯвПодходе: false, столБылПуст: true };
}

/**
 * Пересчитать счёт пропущенных подходов после очередного хода.
 *
 * Функция нарочно ЧИСТАЯ: получает прежний счёт и партию, возвращает новый
 * счёт и больше ничего не трогает. Так её может позвать и проверка из Node —
 * вместо того чтобы пересказывать правило подсчёта своими словами. Пересказ
 * уже жил в проверке отдельно от игры, а в этом проекте копии правил
 * расходились с игрой трижды; двум меркам одного и того же тут не место.
 *
 * Само правило: подход считается законченным, когда стол опустел. Участием
 * считаем нападение и защиту — подкидывание не в счёт, потому что человек
 * жалуется как раз на то, что ему не дают ни ходить, ни отбиваться.
 *
 * Про очередь спрашиваем правила (кто атакует, кто отбивается), а не экран.
 * За сетевым столом очередь считает сервер, и его слово точнее, — но здесь
 * важнее, чтобы игра и проверка считали ОДИНАКОВО: расхождение в один подход
 * стоит дешевле, чем вторая мерка.
 */
function пересчитатьПропущенныеПодходы(прежний, партия) {
  const было = прежний || пустойСчётПодходов();
  if (!партия) return было;
  const столПуст = партия.стол.length === 0;
  let былЯ = было.былЯвПодходе;
  let мимо = было.подходовМимо;
  if (!столПуст && (партия.атакует === 'человек' || защищается(партия) === 'человек')) {
    былЯ = true;
  }
  if (столПуст && !было.столБылПуст) {
    мимо = былЯ ? 0 : мимо + 1;
    былЯ = false;
  }
  return { подходовМимо: мимо, былЯвПодходе: былЯ, столБылПуст: столПуст };
}

/* Тот же счёт, но про партию, которая идёт на экране прямо сейчас. */
let счётПодходовМимо = пустойСчётПодходов();

/** Забыть счёт пропущенных подходов: началась новая партия или раздача. */
function забытьПропущенныеПодходы() {
  счётПодходовМимо = пустойСчётПодходов();
}

/** Следить, проходят ли подходы мимо человека. Зовётся из отрисовки. */
function следитьЗаПропущеннымиПодходами() {
  счётПодходовМимо = пересчитатьПропущенныеПодходы(счётПодходовМимо, партия);
}

function перерисовать() {
  if (!партия) return;
  следитьЗаПропущеннымиПодходами();
  рисоватьСоперников();
  рисоватьКолоду();
  рисоватьСтол();
  рисоватьРукуЧеловека();
  рисоватьПодсказкуИКнопки();
}

/* ---------------------------------------------------------------------
   Ход игры: после каждого действия перерисовываем экран и,
   если очередь бота, ставим его ход на таймер.
   --------------------------------------------------------------------- */

/**
 * Сколько соперники выжидают под свой ход человека. Вдвоём — как было,
 * компанией — дольше: там за спиной очередь из ботов (см. ПАУЗА_ПОСЛЕ_СВОЕГО_ХОДА).
 */
function паузаПодСвойХод() {
  return этоКомпания() ? ПАУЗА_ПОСЛЕ_СВОЕГО_ХОДА : ЗАДЕРЖКА_БОТА;
}

/** Снимок стола перед чужим ходом — по нему потом поймём, что именно случилось. */
function снимокДляРассказа() {
  return {
    парНаСтоле: партия.стол.length,
    отбитые: партия.стол.map(function (пара) { return Boolean(пара.защита); }),
    картыСтола: картыСоСтола(),
    берёт: партия.берёт,
    защитник: защищается(партия),
    // Нужно, чтобы после подхода сказать, сколько карт пришло из колоды.
    вРукеЧеловека: партия.руки.человек ? партия.руки.человек.length : 0
  };
}

/** Все карты со стола по порядку: сначала та, которой ходили, следом — которой били. */
function картыСоСтола() {
  const карты = [];
  for (const пара of партия.стол) {
    карты.push(пара.атака);
    if (пара.защита) карты.push(пара.защита);
  }
  return карты;
}

/* Сколько забранных карт называем поимённо. Больше четырёх в строку
   подсказки не влезает, да и читать список из десяти названий на телефоне
   никто не станет — там уже важнее само число. */
const КАРТ_СПИСКОМ = 4;

/**
 * Как назвать соперника в рассказе о ходе. Вдвоём он один и зовётся
 * «Соперник» — все прежние фразы от этого не меняются. Компанией соперников
 * до пяти, и без имени человек не поймёт, кто именно сходил.
 *
 * Рассказы о чужих ходах в сетевой партии сочиняет сервер, а не мы, поэтому
 * досюда сетевой стол не доходит — и имена местных мест ему не грозят.
 */
function имяВРассказе(ключ) {
  return этоКомпания() ? имяМеста(ключ) : 'Соперник';
}

/**
 * Чем кончился подход. Считать нужно ДО завершения подхода:
 * после него стол уже пуст и сказать нечего.
 *
 * Свои забранные карты называем поимённо: игрок жаловался, что понимал,
 * что именно забрал, только пересчитав руку. Чужие — числом: чем ходил
 * соперник, уже было сказано в своё время.
 */
function текстКонцаПодхода(карты, берёт, защитник, добрано) {
  const сколько = карты.length;
  if (берёт) {
    const слово = словоКарты(сколько, true);
    // Карты забрал соперник, а из колоды в это время добирали мы — про свой
    // добор человеку надо сказать в любом случае, чей бы ни был подход.
    if (защитник !== 'человек') {
      return приписатьДобор(имяВРассказе(защитник) + ' забрал ' + сколько + ' ' + слово, добрано);
    }
    const текст = сколько <= КАРТ_СПИСКОМ
      ? 'Вы забрали ' + карты.map(названиеКарты).join(', ')
      : 'Вы забрали ' + сколько + ' ' + слово;
    return приписатьДобор(текст, добрано);
  }
  return приписатьДобор('Бито — в отбой ' + сколько + ' ' + словоКарты(сколько), добрано);
}

/**
 * Приписка про добор из колоды. Живой игрок сказал: «карты в руке сами
 * прибавляются, откуда у меня валет бубён — непонятно». Показывать добор
 * картинкой дорого, а одной строкой — ровно тот знак, которого он ждал.
 *
 * Слова считаны, а не подобраны на глаз. Строка подсказки высотой ровно
 * в две строки, и лишнее в ней не обрезается с хвоста, а срезается сверху
 * и снизу — то есть портится всё сообщение сразу. На телефоне 360 точек
 * в две строки влезает около 80 знаков, а самая длинная строка игры без
 * этой приписки — 76 знаков («Соперник сказал «Бито» — в отбой 4 карты ·
 * Ваш ход — выберите карту» и подобные). Значит на приписку есть
 * одиннадцать знаков, и полная фраза «, вы добрали 2 карты из колоды»
 * (30 знаков, строка вырастала до 97) в них не укладывается никак.
 *
 * Отсюда короткое «, вы добрали 2» (14 знаков): слово «добрать» в картах
 * и значит «взять из колоды», а рядом на экране стоит счётчик «В колоде
 * 12 карт», так что откуда пришли эти карты, видно тут же. «Вы» добавлено
 * позже и не от щедрости: компанией добирают все разом, и без него человек
 * читал приписку как «кто-то из нас, а кто — неизвестно». На деле строка
 * выглядит так: «Бито — в отбой 2 карты, вы добрали 1» или «Бот 5 забрал
 * 5 карт, вы добрали 3».
 */
function приписатьДобор(текст, добрано) {
  if (!добрано || добрано <= 0) return текст;
  /* «вы» здесь стоит трёх лишних знаков не зря. Компанией добирают все разом,
     и живой новичок читал «добрали 1» как «кто-то из нас, а кто — неизвестно».
     Приписка же всегда про его собственную руку: добор остальных мы не считаем
     и посчитать не можем — чужие руки видны только числом. */
  return текст + ', вы добрали ' + добрано;
}

/**
 * Сколько карт пришло человеку именно из колоды. Считается после подхода:
 * рука выросла и на карты со стола (если он их забрал), и на добор,
 * поэтому взятое со стола вычитаем.
 */
function сколькоДобрали(былоВРуке, взятоСоСтола) {
  const стало = партия.руки.человек ? партия.руки.человек.length : 0;
  return Math.max(0, стало - былоВРуке - взятоСоСтола);
}

/** Подход закончился на этом ходу: стол уехал в отбой или в чью-то руку. */
function подходЗакончился(было) {
  return было.парНаСтоле > 0 && партия.стол.length === 0;
}

/**
 * Что сделал бот: сравниваем стол до хода и после.
 *
 * Довод «кто» — место того, кто ходил, «что» — короткое слово от самих
 * правил («подкидывает», «переводит», «не подкидывает»). Слово нужно там,
 * где по столу ничего не понять: отказ подкидывать стола не меняет вовсе.
 *
 * За столом с одним ботом все фразы остались прежними, слово в слово:
 * там соперник один, и звать его по имени незачем.
 */
function рассказатьОХодеБота(было, кто, что) {
  const имя = имяВРассказе(кто);
  // Подход закончился: стол опустел.
  if (подходЗакончился(было)) {
    const взятоСоСтола = было.берёт && было.защитник === 'человек' ? было.картыСтола.length : 0;
    const добрано = сколькоДобрали(было.вРукеЧеловека, взятоСоСтола);
    if (было.берёт) return текстКонцаПодхода(было.картыСтола, true, было.защитник, добрано);
    /* Компанией подход закрывает тот, кто последним сказал «Пас», и называть
       его по имени нечего: важно, что стол уехал в отбой. Вдвоём же соперник
       один, и привычная фраза остаётся какой была. */
    const начало = этоКомпания() ? 'Бито' : имя + ' сказал «Бито»';
    return приписатьДобор(начало + ' — в отбой ' + было.картыСтола.length +
                          ' ' + словоКарты(было.картыСтола.length), добрано);
  }
  // Бот положил карту.
  if (партия.стол.length > было.парНаСтоле) {
    const карта = названиеКарты(партия.стол[партия.стол.length - 1].атака);
    // В переводном карта могла лечь не в атаку, а переводом: отбиваться теперь другому.
    if (что === 'переводит') return имя + ' перевёл ход картой ' + карта;
    if (было.парНаСтоле === 0) return имя + ' ходит ' + карта;
    return имя + ' подкинул ' + карта;
  }
  // Бот решил взять.
  if (!было.берёт && партия.берёт) return имя + ' не смог отбиться';
  // Бот отбился: ищем пару, у которой появилась защита.
  for (let i = 0; i < партия.стол.length; i++) {
    if (партия.стол[i].защита && !было.отбитые[i]) {
      return имя + ' отбил ' + названиеКарты(партия.стол[i].атака) +
             ' картой ' + названиеКарты(партия.стол[i].защита);
    }
  }
  /* Сказал «больше не подкидываю», а подход продолжается: слово ушло дальше
     по кругу. На столе от этого не меняется ничего, поэтому без слова правил
     такой ход выглядел бы как пустая пауза. Вдвоём этого не бывает вовсе —
     там отказ единственного подкидывающего сразу заканчивает подход. */
  if (что === 'не подкидывает') return имя + ' пасует';
  return '';
}

/** Звук под ход бота: карты по столу шуршат иначе, чем забранная охапка. */
function озвучитьХодБота(было) {
  if (подходЗакончился(было)) {
    if (было.берёт) звукВзятия(); else звукКарты();
    return;
  }
  if (партия.стол.length > было.парНаСтоле) { звукКарты(); return; }   // положил карту
  if (!было.берёт && партия.берёт) { звукВзятия(); return; }          // решил взять
  for (let i = 0; i < партия.стол.length; i++) {
    if (партия.стол[i].защита && !было.отбитые[i]) { звукКарты(); return; }  // отбился
  }
}

/**
 * Ход бота на экране: сходил — рассказали, что сделал.
 *
 * Чей сейчас ход, спрашиваем прямо здесь, а не запоминаем заранее: ботов
 * за столом бывает до пяти, ходят они по очереди, и за ту секунду, что этот
 * ход ждал своего времени, слово могло уйти дальше по кругу.
 */
function сделатьХодБота() {
  таймер = null;
  // Партии может уже не быть: игрок вышел в меню, пока ход был отложен.
  if (!партия || партия.завершена) return;
  const кто = ктоХодит(партия);
  if (!кто || кто === 'человек') return;   // очередь уже не бота — ходить нечего
  const было = снимокДляРассказа();
  const что = ходБота(партия, кто);
  /* Имя нарочно не «рассказ»: так зовут общую переменную игры (последний
     рассказ о ходе, к которому возвращается строка подсказки). Одинаковые
     имена рядом читаются как одна и та же вещь, а это разные. */
  const рассказОХоде = рассказатьОХодеБота(было, кто, что);
  // Под уборку стола выжидаем дольше: там меняется весь экран разом.
  if (рассказОХоде) {
    показатьСобытие(рассказОХоде, ПОКАЗ_СОБЫТИЯ,
      подходЗакончился(было) ? ПАУЗА_ПОСЛЕ_ПОДХОДА : ПАУЗА_ПОД_СОБЫТИЕ);
  }
  озвучитьХодБота(было);
  продолжить();
}

/* Строка про подсветку.
   Слово «выбрать» взято не случайно: рядом в той же строке стоит
   напоминание «Ваш ход — выберите карту» или «Отбивайтесь — выберите
   карту», и человек связывает подсветку с ним сразу. Слово «ходить»
   для этого не годится: в игре им зовут только первый ход в подходе
   («Соперник ходит…», «Сейчас этой картой ходить нельзя»), а зелёная
   черта горит и на картах, которыми отбиваются.
   Длину держим короткой нарочно: коробка подсказки держит неподвижную
   высоту в три строки, и вместе с напоминанием фраза должна в них влезать
   (влезла или нет — решает «влезлоВСтроку», спрашивая страницу).
   Про серые карты здесь молчим: это ясно от обратного, а полностью
   объяснено на экране «Как играть». */
const ТЕКСТ_ПРО_ПОДСВЕТКУ = 'Зелёная черта — эту карту можно выбрать';

/**
 * Объяснить подсветку карт — один раз за всю жизнь игры, перед первым
 * же своим ходом.
 *
 * Живой новичок не понял, чем светлая карта с зелёной чертой отличается
 * от серой под вуалью: игра это знала, но молчала. Объясняем в той же
 * строке подсказки, где и так идут все объяснения, — отдельного окна,
 * которое надо закрывать, здесь нарочно нет.
 *
 * Ждём остаток текущего сообщения: перебивать «У вас младший козырь —
 * вы ходите первым» нельзя, иначе новичок опять не узнает, почему партия
 * началась именно с него.
 */
function подсказатьПроПодсветку() {
  if (подсказкиНовичкуПоказаны) return;
  if (!партия || партия.завершена) return;
  if (ктоХодит(партия) !== 'человек') return;   // подсвечивать пока нечего
  подсказкиНовичкуПоказаны = true;
  записатьНастройку(КЛЮЧ_ПОДСКАЗОК_НОВИЧКУ, 'показаны');
  setTimeout(function () {
    // За это время человек мог выйти в меню, доиграть партию или сесть
    // играть с другом — тогда подсказка уже не к месту.
    if (!партия || партия.завершена || этоСетеваяИгра()) return;
    if (ктоХодит(партия) !== 'человек') return;
    показатьСобытие(ТЕКСТ_ПРО_ПОДСВЕТКУ, ПОКАЗ_НАЧАЛА);
    рисоватьПодсказкуИКнопки();
  }, остатокСобытия());
}

/** Назначить отложенный ход, запомнив, какой именно. */
function отложить(действие, задержка) {
  if (таймер !== null) clearTimeout(таймер);
  отложенныйХод = действие;
  /* ПОРЯДОК ЗДЕСЬ НАРОЧНЫЙ, не переставляйте. Флаг сбрасывается ДО того, как
     ставится таймер, потому что «отодвинутьОтложенныйХод» зовёт эту же
     функцию и сразу после неё ставит флаг обратно. Поменяйте строки местами —
     и отодвигать можно будет без конца: соперник не сходит ни разу, партия
     не доиграется. Проверено прогоном: 150 партий из 150 вставали намертво. */
  ходУжеОтодвинут = false;   // это новое назначение, отодвигать его ещё можно
  таймер = setTimeout(действие, задержка);
}

/**
 * Отодвинуть уже назначенный ход соперника, чтобы он не стёр наш ответ.
 *
 * Ради чего. Замер тестировщика на живом экране: человек тычет в карту,
 * пока думает соперник, — и ответ живёт не положенные 2,4 секунды, а от
 * 0,08. Причина не в сроке показа, а в том, что ход соперника был назначен
 * ЕЩЁ ДО нажатия: он приходит по своему расписанию, ставит в строку свой
 * рассказ и перерисовывает руку — вместе с вздрагиванием карты. Поэтому
 * первый же отказ отодвигает ход соперника: пусть ответ доживёт своё.
 *
 * ОДИН РАЗ НА КАЖДЫЙ НАЗНАЧЕННЫЙ ХОД, и это главное здесь. Отодвигать
 * на каждое нажатие нельзя: нетерпеливый человек тычет чаще, чем раз
 * в две секунды, и соперник не сходил бы никогда — игра встала бы
 * намертво. Проверено прогоном: тычешь без остановки — партия не
 * доигрывается вовсе. Поэтому первый отказ покупает ответу полное время,
 * а следующие показываются в оставшееся: слова они всё равно меняют.
 */
function отодвинутьОтложенныйХод() {
  if (таймер === null || отложенныйХод === null) return;   // никто не ходит — двигать нечего
  if (ходУжеОтодвинут) return;
  const действие = отложенныйХод;
  отложить(действие, Math.max(ЗАДЕРЖКА_БОТА, ждатьПодСобытие()));
  ходУжеОтодвинут = true;
}

function продолжить() {
  /* Гасим прежний отложенный ход первой же строкой. «Продолжить» значит
     «за столом что-то изменилось, считаем заново», и всё, что было
     назначено раньше, устарело. Пока за столом сидел один бот, лишний
     таймер ничем не грозил, а теперь их до пяти: два живых таймера — это
     два хода подряд, и очередь потеряется. */
  if (таймер !== null) {
    clearTimeout(таймер);
    таймер = null;
  }
  // Страховка для игры вдвоём: там ходы приходят с сервера, а бот не играет
  // вовсе. Проверка стоит в самой развилке — так ни один забытый путь
  // не сможет случайно разбудить робота посреди партии с живым другом.
  if (этоСетеваяИгра()) {
    перерисовать();
    return;
  }
  подсказатьПроПодсветку();
  перерисовать();
  if (партия.завершена) {
    // Итог засчитываем прямо сейчас, а плашку показываем чуть позже.
    // Раньше и то и другое ждало показа: игрок успевал выйти в меню
    // за эти две секунды, и проигрыш просто не записывался.
    засчитатьИтог();
    отменитьПоказИтога();
    таймерИтога = setTimeout(показатьРезультат, Math.max(900, ждатьПодСобытие() + 500));
    return;
  }
  /* Рука пуста, а слово наше — жмём за человека сами (см. «пораПасоватьСамим»).
     Пауза тут не лишняя: за неё видно последний ход, прежде чем стол уедет. */
  if (пораПасоватьСамим()) {
    отложить(пасЗаПустуюРуку, Math.max(ЗАДЕРЖКА_БОТА, ждатьПодСобытие()));
    return;
  }
  /* Слово не наше — значит оно у кого-то из ботов, и неважно, у которого:
     кто именно ходит, разберётся сам ход бота. Ботов за столом бывает
     до пяти, и ходят они друг за другом — каждый следующий ход ставится
     на таймер отсюда же, поэтому пауза между ходами остаётся одна и та же
     и глазом успеваешь за всеми. */
  if (ктоХодит(партия) !== 'человек') {
    // Бот не спешит: пока висит сообщение о прошлом событии, он ждёт.
    отложить(сделатьХодБота, Math.max(ЗАДЕРЖКА_БОТА, ждатьПодСобытие()));
  }
}

/**
 * Чем партия кончилась ДЛЯ МЕНЯ: 'победа', 'поражение' или 'ничья'.
 * Отсюда берут ответ и звук итога, и серия побед, и рекорды — все трое,
 * чтобы разойтись во мнениях они не могли.
 *
 * Смотрим на список проигравших, а не на строку «результат». Строка — это
 * ИМЯ дурака, и вдвоём оно случайно совпадало со словами, которые счёт умел
 * разбирать («бот» — выиграл, «человек» — проиграл). За столом компанией имя
 * бывает любым («бот-4»), а в игре парами их сразу два («человек и бот-3»), —
 * и такой итог счёт считал ничьёй: победа не шла ни в серию, ни в рекорды.
 * Причём вчетвером часть побед «работала» по совпадению — когда дураком
 * оказывался сосед на втором месте, которого правила зовут просто «бот».
 * Список проигравших таких совпадений не знает: там прямо сказано, кто
 * остался с картами, а в игре парами — оба из проигравшей пары.
 *
 * Функция нарочно не смотрит ни на что, кроме своего довода: её зовут
 * и проверки, у которых экрана нет вовсе.
 */
function чемКончилосьДляМеня(партия) {
  if (!партия) return 'ничья';
  const проигравшие = Array.isArray(партия.проигравшие) ? партия.проигравшие : [];
  if (проигравшие.length > 0) {
    return проигравшие.indexOf('человек') !== -1 ? 'поражение' : 'победа';
  }
  /* Списка нет — так приходит партия по сети: там итог считает сервер
     и присылает одним словом. Заодно сюда попадают концовки без дурака
     («друг ушёл», «связь потеряна») — их считаем ничьёй, серию они не трогают. */
  if (партия.результат === 'бот') return 'победа';
  if (партия.результат === 'человек') return 'поражение';
  return 'ничья';
}

/**
 * Надо ли нажать «Пас» («Бито») за человека.
 *
 * Живой новичок: «сходил последней картой, рука пустая, а игра всё равно
 * требует нажать «Пас». Карт нет, а меня спрашивают». И он прав: с пустой
 * рукой решать нечего и решать никогда не станет чем — подкинуть нечего
 * по определению, а слово к нему пришло только затем, чтобы закрыть подход.
 *
 * Условие нарочно узкое — именно ПУСТАЯ рука, а не «нечем подкинуть».
 * Когда карты в руке есть, кнопку оставляем человеку: нажимая её сам,
 * он выбирает, когда стол уедет, и успевает на него посмотреть. Тот же
 * новичок жаловался и на обратное — что не успевает разглядеть стол.
 */
function пораПасоватьСамим() {
  if (!партия || партия.завершена || этоСетеваяИгра() || ждёмОтветПроВыход) return false;
  const рука = партия.руки.человек;
  if (!рука || рука.length > 0) return false;
  return мнеМожноЗакончитьПодход(фаза(партия));
}

/* Что стоит в напоминании ту секунду с небольшим, пока игра собирается
   нажать «Пас» за человека с пустой рукой.

   Раньше эти слова стояли в другом месте — в рассказе о событии, в ветке
   «пас сказан, а подход продолжается». Тестировщик не увидел их ни разу
   за двенадцать партий, и правильно: до той ветки с пустой рукой не дойти
   никогда. Слово приходит к безрукому игроку только тогда, когда подкинуть
   нечем ВООБЩЕ НИКОМУ (см. «ктоХодит»: сперва спрашивают всех, кому есть
   чем), а его «пас» в этом случае сразу закрывает подход — и рассказом
   становится «Бито — в отбой 2 карты». Ветка была мёртвой, её больше нет.

   Здесь фраза видна: она стоит в напоминании всю паузу перед нажатием,
   ровно там, где до этого требовали «жмите „Пас“» у человека без карт. */
const ТЕКСТ_ПАСУЕМ_ЗА_ВАС = 'Карт у вас нет — пасуем за вас…';

/** Нажать «Пас» вместо человека, у которого не осталось карт. */
function пасЗаПустуюРуку() {
  таймер = null;
  // За паузу всё могло измениться: пришли карты, человек вышел в меню.
  if (пораПасоватьСамим()) нажатьБито();
}

/**
 * Партия кончилась: записываем результат и звучим об этом.
 * Делается ровно один раз и сразу — до всяких показов и задержек,
 * чтобы выход в меню уже ничего не отменял.
 */
function засчитатьИтог() {
  if (итогЗасчитан || !партия) return;
  итогЗасчитан = true;
  const чемКончилось = чемКончилосьДляМеня(партия);
  if (чемКончилось === 'победа') звукПобеды();
  else if (чемКончилось === 'поражение') звукПроигрыша();
  подвестиСерию(чемКончилось);
}

/**
 * Заголовок итога и объяснение под ним: чем кончилась партия.
 * Вынесено отдельно, потому что в игре вдвоём эти надписи приходится
 * освежать и после показа плашки — друг может выйти из-за стола или
 * позвать на реванш уже тогда, когда итог на экране.
 */
function текстыИтога() {
  if (!партия) return { заголовок: '', пояснение: '' };
  /* За столом компанией дурака зовут по имени, а в парной игре дурак —
     не человек, а пара. Слово «соперник» там не годится: соперников
     было пятеро, и надо сказать, кто именно остался с картами.
     Прерванная связь — про нас самих, и рассказывается одинаково. */
  if (этоКомпания() && партия.результат !== 'связь-потеряна') {
    return текстыИтогаКомпании();
  }
  if (партия.результат === 'бот') {
    return {
      заголовок: 'Вы выиграли!',
      пояснение: 'Соперник остался с картами — он и есть дурак.'
    };
  }
  if (партия.результат === 'человек') {
    return {
      заголовок: 'Вы проиграли',
      пояснение: 'Вы остались с картами — на этот раз дурак вы.'
    };
  }
  if (партия.результат === 'друг-ушёл') {
    // Никого не обвиняем: чаще всего у друга просто пропала связь.
    return {
      заголовок: 'Друг вышел из игры',
      пояснение: 'Партия прервалась на середине — возможно, у друга пропала связь. ' +
                 'Дурака в такой партии нет.'
    };
  }
  if (партия.результат === 'связь-потеряна') {
    // Человек не виноват: у него пропал интернет, и партия закрылась без него.
    return {
      заголовок: 'Партия прервалась',
      пояснение: 'Связь пропадала слишком долго, и игра закончилась без вас. ' +
                 'Дурака в такой партии нет — вернитесь в меню и начните новую игру.'
    };
  }
  return { заголовок: 'Ничья', пояснение: 'Карты кончились у обоих — дурака нет.' };
}

/** Имена тех, кто остался дураком. Про себя пишем «вы», а не своё имя. */
function именаДураков() {
  const имена = [];
  for (const место of местаКомпании() || []) {
    if (место.проиграл) имена.push(место.этоЯ ? 'вы' : место.имя);
  }
  return имена;
}

/** Чем кончилась партия компанией: кто дурак, а в парной игре — какая пара. */
function текстыИтогаКомпании() {
  if (партия.результат === 'друг-ушёл') {
    return {
      заголовок: 'Партия прервалась',
      пояснение: 'За столом не осталось соперников — дурака в этой партии нет.'
    };
  }
  const дураки = именаДураков();
  if (дураки.length === 0) {
    // Ничья бывает, когда карты кончились у всех разом.
    return {
      заголовок: партия.результат === 'ничья' ? 'Ничья' : 'Партия окончена',
      пояснение: 'Карты кончились у всех разом — дурака нет.'
    };
  }

  const яДурак = дураки.indexOf('вы') !== -1;
  const списком = дураки.join(' и ');
  if (партия.парами) {
    // Дурак в парной игре — не человек, а пара: проигрывают оба сразу.
    return яДурак
      ? { заголовок: 'Ваша пара проиграла',
          пояснение: 'Дураки — ' + списком + '. В игре парами проигрывают вдвоём.' }
      : { заголовок: 'Ваша пара выиграла!',
          пояснение: 'Проиграла пара: ' + списком + '.' };
  }
  return яДурак
    ? { заголовок: 'Вы проиграли',
        пояснение: 'Вы остались с картами — на этот раз дурак вы.' }
    : { заголовок: 'Вы выиграли!',
        пояснение: 'Дурак — ' + списком + ': карты остались у него.' };
}

/**
 * Написать заголовок итога и подпись под ним. В игре вдвоём к подписи
 * добавляется вторая фраза — что делать дальше. Такие объяснения занимают
 * две-три строки, и в рамку для короткой строки «Побед подряд: 3» им нельзя:
 * там они кричат громче самого заголовка.
 */
function обновитьТекстыИтога() {
  const тексты = текстыИтога();
  const хвост = этоСетеваяИгра() && подсказкаПослеПартии ? ' ' + подсказкаПослеПартии : '';
  написать('текст-результата', тексты.заголовок);
  написать('пояснение-результата', тексты.пояснение + хвост);
}

function показатьРезультат() {
  таймерИтога = null;
  // За паузу перед показом всё могло измениться, поэтому проверяем заново:
  // партия есть, она действительно доиграна, человек стоит у стола и не занят
  // вопросом «точно выйти?». Иначе плашка легла бы поверх чужого экрана
  // и перекрыла бы кнопки.
  if (!партия || !партия.завершена) return;
  if (!этоЭкранИгры() || ждёмОтветПроВыход) return;
  обновитьТекстыИтога();
  // В игре вдвоём эта же кнопка предлагает не новую партию с ботом,
  // а реванш в той же комнате — с тем же другом и тем же кодом.
  написать('кнопка-ещё', этоСетеваяИгра() ? 'Ещё партию' : 'Играть ещё');
  показатьЭлемент('кнопка-ещё', реваншВозможен());
  показатьПлашкуИтога();
}

/* ---------------------------------------------------------------------
   Действия человека
   --------------------------------------------------------------------- */

/**
 * Положить карту в атаку. Развилка по режиму стоит здесь, а не в обработчике
 * нажатия: проверки «можно ли так ходить» и подсветка карт для обоих режимов
 * одни и те же, различается только последний шаг — свой стол или сервер.
 */
function сходитьКартой(индекс) {
  if (этоСетеваяИгра()) {
    отправитьХодНаСервер({ действие: 'ходить', карта: индекс });
    return;
  }
  const карта = партия.руки.человек[индекс];
  const перваяВПодходе = партия.стол.length === 0;
  if (!положитьВАтаку(партия, 'человек', индекс)) return;
  /* Свой ход называем вслух наравне с чужим. Раньше про ход человека
     не говорилось ничего, и после отбоя последней карты стол успевал
     опустеть быстрее, чем игрок переводил на него взгляд: он видел
     только «Соперник сказал Бито» и не понимал, куда делся его ход. */
  /* Ждать под это сообщение бот не обязан: положенная карта остаётся лежать
     на столе, её видно и без паузы. Поэтому темп здесь прежний. */
  показатьСобытие((перваяВПодходе ? 'Вы сходили ' : 'Вы подкинули ') + названиеКарты(карта),
                  ПОКАЗ_СОБЫТИЯ, паузаПодСвойХод());
  звукКарты();
  выбраннаяКарта = null;
  продолжить();
}

/** Отбить карту на столе. Та же развилка: свой стол либо сервер. */
function отбитьсяКартой(индексПары, индексКарты) {
  if (этоСетеваяИгра()) {
    отправитьХодНаСервер({ действие: 'отбить', пара: индексПары, карта: индексКарты });
    return true;
  }
  // Названия берём до хода: после него карта уже уехала из руки на стол.
  const пара = партия.стол[индексПары];
  const атака = пара ? пара.атака : null;
  const карта = партия.руки.человек[индексКарты];
  if (!отбить(партия, индексПары, индексКарты)) return false;
  /* Отбились последней неотбитой картой — соперник вот-вот скажет «Бито»
     и стол уедет. Только в этом случае просим бота подождать подольше. */
  const столЗакрыт = неотбитых(партия) === 0;
  показатьСобытие('Вы отбили ' + названиеКарты(атака) + ' картой ' + названиеКарты(карта),
                  ПОКАЗ_СОБЫТИЯ,
                  столЗакрыт ? ПАУЗА_ПОСЛЕ_СВОЕГО_ОТБОЯ : паузаПодСвойХод());
  звукКарты();
  выбраннаяКарта = null;
  продолжить();
  return true;
}

/* Слова про напарника взяты у сервера слово в слово (см. отказ в
   server/партия-по-сети.js): в игре парами это главное правило круга,
   и обе половины игры — своя и сетевая — обязаны объяснять его одинаково,
   иначе человек решит, что это разные запреты. */
const ТЕКСТ_НАПАРНИКУ_НЕ_ПОДКИДЫВАЮТ =
  'Подкидывать может только соперник того, кто отбивается, — напарнику не подкидывают';

/**
 * Отбивается наш напарник — значит, в этом подходе класть карты нам нельзя
 * вовсе, и слово к нам не придёт (см. «подкидывающие»: из круга выпадают
 * и отбивающийся, и его напарник).
 */
function напарникОтбивается() {
  if (!партия || !партия.парами) return false;
  if (фаза(партия) === 'атака' || фаза(партия) === 'конец') return false;
  const защитник = защищается(партия);
  return защитник !== 'человек' && самИлиНапарник(партия, защитник, 'человек');
}

/* Что отвечаем на нажатия в те секунду-две, пока партия уже доиграна,
   а плашка итога ещё не всплыла. Раньше все обработчики стола выходили
   на этом молча — а это ровно тот миг, когда новичок тычет в карты
   и не понимает, почему ничего не происходит. */
const ТЕКСТ_ПАРТИЯ_ОКОНЧЕНА = 'Партия окончена — сейчас появится итог';

function тапПоКартеЧеловека(индекс) {
  if (!партия || ждёмОтветПроВыход) return;
  /* Только что нажали кнопку — это касание может оказаться её же «хвостом»
     (подробности и замеры — у ГЛУХОТА_ПОСЛЕ_КНОПКИ).
     Молчим здесь нарочно: отвечать вспышкой и звуком на палец, который
     ничего не нажимал, значит ругать человека за то, чего он не делал.
     Проверка стоит раньше «не ваш ход» ещё и поэтому: после «Беру» слово
     уходит сопернику, и хвост касания получил бы отказ «сейчас ходит
     соперник» — прямо в ответ на удачно нажатую кнопку. */
  if (Date.now() < рукаГлухаДо) return;
  /* Проверка стоит ПОСЛЕ глухоты нарочно. Партию часто заканчивает своя же
     кнопка («Бито» последним ходом), и её «хвост» попадает в руку: стой
     проверка выше — человек получал бы писк и вздрагивание карты в ответ
     на удачное нажатие, которое он только что сделал сам. */
  if (партия.завершена) { отказатьПоКарте(индекс, ТЕКСТ_ПАРТИЯ_ОКОНЧЕНА); return; }
  if (ждёмОтветаНаХод()) {
    отказатьСловами(ТЕКСТ_ХОД_ЛЕТИТ);
    return;
  }
  /* Бот думает от 0,7 до 3 секунд и делает несколько ходов подряд — за это
     время нетерпеливый игрок успевает потыкать в свои карты. Раньше игра
     на это молчала, и человек решал, что нажатие не дошло. */
  if (!сейчасМойХод()) {
    /* Отбивается свой напарник — слово в этом подходе к нам не придёт вовсе,
       и обещать «игра сама скажет, когда ваш ход» тут нельзя: тестировщик
       ткнул тридцать раз за два подхода и не дождался ни разу. */
    if (напарникОтбивается()) {
      отказатьПоКарте(индекс, ТЕКСТ_НАПАРНИКУ_НЕ_ПОДКИДЫВАЮТ,
                      'Ваше слово вернётся в следующем подходе');
      return;
    }
    отказатьПоКарте(индекс, текстНеВашХод(), 'Игра сама скажет, когда ваш ход');
    return;
  }
  const карта = партия.руки.человек[индекс];
  if (!карта) return;
  const текущая = фаза(партия);
  /* Прошлую новость здесь больше не стираем. Раньше она гасла на любом
     касании руки — в том числе когда человек просто поднимал карту, чтобы
     выбрать, что ею бить: сообщение о чужом ходе исчезало ни за что.
     Свой ход заменит её сам, сразу же и своим текстом. */

  if (текущая === 'атака' || текущая === 'подкидывание' || текущая === 'докидывание') {
    /* Слово наше, но подкидывать мы уже отказались: слово вернулось только
       затем, чтобы закрыть подход. Отвечаем словами сразу — иначе ход уйдёт
       на сервер и вернётся оттуда отказом, а человек так и не поймёт, почему
       игра предлагала подкинуть. */
    if (текущая !== 'атака' && этоКомпания() && !мнеМожноПодкинуть()) {
      отказатьПоКарте(индекс, 'Вы сказали «Пас» — подкидывать больше нельзя',
                      'Ждём остальных, потом стол уедет');
      return;
    }
    if (!можноПоложить(партия, карта)) {
      отказатьПоКарте(индекс, почемуНельзяПоложить(карта), словаПроВыборКарты());
      return;
    }
    сходитьКартой(индекс);
    return;
  }

  if (текущая === 'защита') {
    // Ищем, какие карты на столе эта карта вообще может побить.
    const цели = [];
    партия.стол.forEach(function (пара, i) {
      if (!пара.защита && бьёт(карта, пара.атака, партия.козырь)) цели.push(i);
    });
    // В переводном той же картой можно не крыть, а перевести ход дальше.
    const переводом = можноПеревестиЭтой(карта);
    if (цели.length === 0 && !переводом) {
      отказатьПоКарте(индекс, почемуНельзяОтбиться(карта), словаПроВыборКарты());
      return;
    }
    if (цели.length === 1 && !переводом) {
      // Крыть нечего выбирать — сразу бьём единственную подходящую карту.
      отбитьсяКартой(цели[0], индекс);
      return;
    }
    // Выбор есть (несколько целей или перевод) — карту только поднимаем,
    // а решает человек: за него такое не решают.
    выбраннаяКарта = (выбраннаяКарта === индекс) ? null : индекс;
    /* Человек тут же сделал законный ход — ругань за прошлое нажатие больше
       ни к чему: иначе она висит рядом с новой подсказкой все свои 2,4 с. */
    снятьОтказ();
    перерисовать();
    return;
  }

  /* Досюда фаза «конец» уже не доходит: доигранную партию ловит первая
     же строка обработчика (ТЕКСТ_ПАРТИЯ_ОКОНЧЕНА). Ответ на всякий случай
     оставляем: пусть у любого пути будет свой конец, а не тишина. */
  отказатьПоКарте(индекс, ТЕКСТ_ПАРТИЯ_ОКОНЧЕНА);
}

/**
 * Нажатие в руку, но мимо карт — в просвет между рядами или в край полосы.
 * Это единственный случай, когда игра и вправду могла промолчать: обработчик
 * висит на каждой карте, а между картами обработчика не было вовсе.
 * Именно так и выглядит жалоба «ноль реакции»: человек уверен, что попал
 * по карте, а попал мимо неё на пару точек.
 */
function тапМимоКарты(событиеМыши) {
  if (!партия || ждёмОтветПроВыход) return;
  if (Date.now() < рукаГлухаДо) return;
  const цель = событиеМыши && событиеМыши.target;
  /* Попали в саму карту — молчим: ответит её собственный обработчик, а два
     ответа на одно нажатие хуже одного. Карты лежат внутри веера, поэтому
     «мимо» — это когда нажатие досталось самой полосе руки или вееру. */
  const мимо = !цель || цель.id === 'рука-человека' || цель.id === 'карты-человека';
  if (!мимо) return;
  if (партия.завершена) { отказатьСловами(ТЕКСТ_ПАРТИЯ_ОКОНЧЕНА); return; }
  // По сети ход мог уже улететь: отвечать «сейчас ходит соперник» нечестно —
  // мы и сами не знаем, чей теперь ход, пока не ответит сервер.
  if (ждёмОтветаНаХод()) { отказатьСловами(ТЕКСТ_ХОД_ЛЕТИТ); return; }
  const мойХод = сейчасМойХод();
  const текст = мойХод ? 'Мимо карты — нажмите прямо по ней' : текстНеВашХод();
  /* Второй промах подряд теми же словами — тот же замерший экран, что и с картами.
     Но слова на повтор зависят от того, чей ход: звать искать зелёную черту,
     когда ход вообще не наш, — прямая неправда. Рука может быть полна козырей,
     подсветки на ней нет просто потому, что сейчас говорит соперник. */
  const наПовтор = мойХод ? словаПроВыборКарты() : 'Игра сама скажет, когда ваш ход';
  отказатьСловами(текст === прошлыеСловаОтказа ? наПовтор : текст);
}

function тапПоПаре(индексПары) {
  if (!партия || ждёмОтветПроВыход) return;
  if (партия.завершена) { отказатьПоПаре(индексПары, ТЕКСТ_ПАРТИЯ_ОКОНЧЕНА); return; }
  if (ждёмОтветаНаХод()) {
    отказатьСловами(ТЕКСТ_ХОД_ЛЕТИТ);
    return;
  }
  if (!сейчасМойХод()) {
    отказатьПоПаре(индексПары, текстНеВашХод(), 'Игра сама скажет, когда ваш ход');
    return;
  }
  // Ход наш, но мы не отбиваемся: по столу бить нечем, карта идёт из руки.
  if (фаза(партия) !== 'защита') {
    отказатьПоПаре(индексПары, 'Играйте картой из своей руки — эта не ваша',
                   словаПроВыборКарты());
    return;
  }
  /* Порядок тут не всем очевиден: сначала поднять свою карту, потом указать,
     что ею бьёшь. Новичок делает наоборот — тычет в карту соперника. */
  if (выбраннаяКарта === null) {
    отказатьПоПаре(индексПары, 'Сначала выберите карту в своей руке',
                   словаПроВыборКарты());
    return;
  }
  отбитьсяКартой(индексПары, выбраннаяКарта);
}

/**
 * Нажатие по стопке колоды. Брать из неё руками нельзя — карты добираются
 * сами в конце подхода, но об этом нигде не сказано, и новичок тыкает
 * в стопку, ожидая объяснения. Теперь оно приходит.
 */
function тапПоКолоде() {
  if (!партия || ждёмОтветПроВыход) return;
  if (партия.завершена) { отказатьСловами(ТЕКСТ_ПАРТИЯ_ОКОНЧЕНА); return; }
  const осталось = партия.колода.length;
  отказатьСловами(осталось > 0
    ? 'В колоде ' + осталось + ' ' + словоКарты(осталось) + ' — карты добираются сами'
    : 'Колода пуста — добирать больше нечего');
}

/**
 * Нажатие по подписи «Козырь ♣». В разметке она лежит не внутри блока колоды,
 * а рядом с ним, поэтому нажатие на неё приходится ловить отдельно — на вид
 * же это тот самый угол с колодой, и человек тычет туда наравне со стопкой.
 * Отвечаем главным правилом игры: новичок как раз не понимает, почему одни
 * карты подсвечены как «можно», а козырная бьёт что угодно.
 */
function тапПоКозырю() {
  if (!партия || ждёмОтветПроВыход) return;
  if (партия.завершена) { отказатьСловами(ТЕКСТ_ПАРТИЯ_ОКОНЧЕНА); return; }
  /* Слово «козырь» один раз, а не два: строка подсказки показывает это
     сообщение вместе с напоминанием о действии через « · », и места им
     на двоих в обрез — что не влезло, игра покажет порознь (см.
     «влезлоВСтроку»), то есть половину человек увидит не сразу.
     Масть в сетевой партии приходит от сервера и может оказаться пустой:
     тогда говорим то же самое без неё, иначе получится «Козырь  бьёт»
     с дырой посередине. */
  отказатьСловами(партия.козырь
    ? 'Козырь ' + партия.козырь + ' бьёт любую карту другой масти'
    : 'Козырь бьёт любую карту другой масти');
}

function нажатьБито() {
  if (!партия || партия.завершена || ждёмОтветПроВыход) return;
  const текущая = фаза(партия);
  if (!мнеМожноЗакончитьПодход(текущая)) return;
  рукаГлухаДо = Date.now() + ГЛУХОТА_ПОСЛЕ_КНОПКИ;
  if (этоСетеваяИгра()) {
    // Рассказ о конце подхода в сети придёт от сервера — своего не сочиняем,
    // иначе у двух игроков будут разные версии одного события.
    отправитьХодНаСервер({ действие: 'бито' });
    return;
  }
  // Карты и руку запоминаем до завершения: после него стол уже пуст,
  // а рука выросла — только по разнице и видно, сколько пришло из колоды.
  const заберёт = партия.берёт;
  const защитник = защищается(партия);
  const карты = картыСоСтола();
  const былоВРуке = партия.руки.человек.length;
  /* Компанией эта кнопка называется «Пас» и значит другое: «я больше
     не подкидываю». Подход от неё закончится только тогда, когда подкинуть
     будет некому. Вдвоём подкидывающий один, его отказ — это и есть привычное
     «Бито», и тамошний путь оставлен ровно таким, каким был. */
  if (этоКомпания()) {
    if (!пас(партия, 'человек')) return;
  } else {
    завершитьПодход(партия);
  }
  if (партия.стол.length > 0) {
    // Слово ушло дальше по кругу, стол остался лежать — подход продолжается.
    показатьСобытие('Вы сказали «Пас»', ПОКАЗ_СОБЫТИЯ, ПАУЗА_ПОД_СОБЫТИЕ);
    звукКарты();
    выбраннаяКарта = null;
    продолжить();
    return;
  }
  const взятоСоСтола = заберёт && защитник === 'человек' ? карты.length : 0;
  показатьСобытие(текстКонцаПодхода(карты, заберёт, защитник,
                                    сколькоДобрали(былоВРуке, взятоСоСтола)),
                  ПОКАЗ_СОБЫТИЯ, ПАУЗА_ПОСЛЕ_ПОДХОДА);
  if (заберёт) звукВзятия(); else звукКарты();
  выбраннаяКарта = null;
  продолжить();
}

function нажатьБеру() {
  if (!партия || партия.завершена || ждёмОтветПроВыход) return;
  if (фаза(партия) !== 'защита' || !сейчасМойХод()) return;
  рукаГлухаДо = Date.now() + ГЛУХОТА_ПОСЛЕ_КНОПКИ;
  if (этоСетеваяИгра()) {
    отправитьХодНаСервер({ действие: 'беру' });
    return;
  }
  объявитьБеру(партия);
  /* Раньше здесь было «Вы берёте карты», а строка действия рядом писала
     «Вы забираете карты. Соперник может подкинуть…» — одно и то же дважды
     в одной строке. Пока событие гасло за три секунды, это было незаметно;
     теперь оно висит до следующего хода, и повтор бросался бы в глаза.
     Оставляем короткое подтверждение нажатия, а что будет дальше,
     рассказывает строка действия. Сколько карт забрали и какие именно —
     скажет сообщение в конце подхода, когда они и вправду уедут в руку. */
  показатьСобытие('Вы сказали «Беру»', ПОКАЗ_СОБЫТИЯ, ПАУЗА_ПОД_СОБЫТИЕ);
  звукВзятия();
  выбраннаяКарта = null;
  продолжить();
}

/**
 * «Перевести» — вместо того, чтобы крыть, кладём на стол свою карту того же
 * достоинства, и отбиваться приходится следующему. Кнопка работает с той
 * картой, которую человек поднял: другой она не переведёт.
 */
function нажатьПеревести() {
  if (!партия || партия.завершена || ждёмОтветПроВыход) return;
  if (фаза(партия) !== 'защита' || !сейчасМойХод()) return;
  const индекс = выбраннаяКарта;
  if (индекс === null) return;
  const карта = партия.руки.человек[индекс];
  if (!можноПеревестиЭтой(карта)) return;
  рукаГлухаДо = Date.now() + ГЛУХОТА_ПОСЛЕ_КНОПКИ;
  if (этоСетеваяИгра()) {
    отправитьХодНаСервер({ действие: 'перевести', карта: индекс });
    return;
  }
  if (!перевести(партия, индекс)) return;
  показатьСобытие('Вы перевели ход картой ' + названиеКарты(карта),
                  ПОКАЗ_СОБЫТИЯ, ПАУЗА_ПОД_СОБЫТИЕ);
  звукКарты();
  выбраннаяКарта = null;
  продолжить();
}

/**
 * То же самое за столом компанией: соперников до пяти, и слово «соперник»
 * там ничего не объясняет — надо назвать, кто именно начинает.
 * Чужие козыри не показываем: это закрытая рука.
 */
function текстКтоПервыйВКомпании() {
  const мой = младшийКозырь(партия, 'человек');
  if (партия.атакует === 'человек') {
    return мой
      ? 'У вас младший козырь ' + названиеКарты(мой) + ' — вы ходите первым'
      : 'Козырей нет ни у кого — первым ходите вы';
  }
  // Раз первым вышел не человек, козырь у того игрока точно есть:
  // без козырей за столом первым ходит тот, кто сидит первым, а это мы.
  return 'Первым ходит ' + имяМеста(партия.атакует) + ' — у него младший козырь';
}

/** Почему партия начинается именно с этого игрока — иначе первый ход выглядит случайным. */
function текстКтоПервый() {
  if (этоКомпания()) return текстКтоПервыйВКомпании();
  const мой = младшийКозырь(партия, 'человек');
  const чужой = младшийКозырь(партия, 'бот');
  if (партия.атакует === 'человек') {
    if (мой && чужой) return 'У вас младший козырь ' + названиеКарты(мой) + ' — вы ходите первым';
    if (мой) return 'Козырь только у вас (' + названиеКарты(мой) + ') — вы ходите первым';
    return 'Козырей нет ни у кого — первым ходите вы';
  }
  // Карту бота не показываем: это его закрытая рука.
  return чужой && мой
    ? 'Младший козырь у соперника — он первый'
    : 'Козырь только у соперника — он первый';
}

/** Новая партия с нуля: старые таймеры гасим, всё состояние создаём заново. */
function начатьПартию() {
  if (таймер !== null) {
    clearTimeout(таймер);
    таймер = null;
  }
  отменитьПоказИтога();   // итог прошлой партии новой уже не касается
  убратьСобытие();
  прошлыеСловаОтказа = '';   // отказы прошлой партии новой не считаются повтором
  событиеЭтоОтказ = false;
  забытьПропущенныеПодходы();
  выбраннаяКарта = null;
  итогЗасчитан = false;
  ждёмОтветПроВыход = false;
  /* Не обнуляем, а наоборот заводим окно: новую партию начинают кнопкой,
     и первые доли секунды рука не должна принимать «хвост» этого нажатия —
     иначе первый ход партии может сделаться сам. Начало партии — как раз
     то место, где эти доли секунды никому не мешают. */
  рукаГлухаДо = Date.now() + ГЛУХОТА_ПОСЛЕ_КНОПКИ;
  // Обычная партия всегда против бота: если до этого играли с другом,
  // сетевой режим здесь заканчивается.
  оставитьСетевуюПартию();
  режим = РЕЖИМ_БОТ;
  партия = создатьПартию({
    сложность: сложность,                          // уровень тот, что выбран в меню
    игроков: настройкиИгрыСБотами.игроков,         // человек и остальные места — боты
    переводной: настройкиИгрыСБотами.переводной,
    парами: настройкиИгрыСБотами.парами
  });
  показатьЭкран('экран-игры');
  подобратьРазмерКарты();
  /* Первому в жизни игроку даём дочитать, кто ходит первым и почему.
     Раньше бот выжидал под это сообщение обычные 1,6 секунды и перебивал
     его своим ходом — живой новичок сыграл четыре партии и так и не понял,
     есть ли тут правило. Тому, кто уже играл, всё остаётся как было. */
  показатьСобытие(текстКтоПервый(), ПОКАЗ_НАЧАЛА,
                  подсказкиНовичкуПоказаны ? ПАУЗА_ПОД_СОБЫТИЕ : ПОКАЗ_НАЧАЛА);
  продолжить();
}

/**
 * Чем обернётся выход — три разных случая, и путать их нельзя.
 *
 * За ОБЩИМ столом на троих и больше партия не прерывается: сервер сажает
 * на освободившееся место бота, и он доигрывает нашими картами, а остальные
 * играют дальше. Прежняя надпись обещала одинокого друга за столом — при
 * пятерых соперниках это была прямая неправда.
 *
 * А вот компания из ботов держится на нашем же телефоне: ушли — и партии
 * больше нет, продолжать её некому. Поэтому там подпись обычная.
 */
function подписьВыхода() {
  if (этоСетеваяИгра() && этоКомпания()) {
    return 'Вы выйдете из партии — ваши карты доиграет бот, остальные продолжат.';
  }
  // Вдвоём уход — это не только своя брошенная партия: друг останется
  // за столом один и должен понять, почему.
  if (этоСетеваяИгра()) return 'Партия прервётся, друг останется за столом один.';
  return 'Партия прервётся, результат не запишется.';
}

/**
 * Спросить, точно ли выходить. Пока висит вопрос, партия стоит на паузе:
 * отложенный ход соперника гасим, чтобы за время раздумий ничего не менялось.
 */
function спроситьПроВыход() {
  // Партия уже доиграна (итог засчитан) — терять нечего, спрашивать не о чем.
  if (!партия || партия.завершена) { выйтиВМеню(); return; }
  if (таймер !== null) {
    clearTimeout(таймер);
    таймер = null;
  }
  ждёмОтветПроВыход = true;
  написать('подпись-выхода', подписьВыхода());
  const плашка = эл('экран-выхода');
  if (!плашка) { выйтиВМеню(); return; }   // нет плашки — выходим сразу, как раньше
  плашка.classList.add('экран--поверх');
  плашка.classList.add('экран--виден');
}

/** «Продолжить партию»: убираем вопрос и возвращаем игру в ход. */
function остатьсяВПартии() {
  ждёмОтветПроВыход = false;
  /* Здесь окно глухоты нужнее, чем у кнопок нижней панели. Плашка выхода
     прижата к низу, и «Продолжить партию» идёт во всю ширину как раз там,
     где лежит рука. Плашка пропадает мгновенно, рука перерисовывается
     тут же — и второе касание того же пальца попадает уже в карту, которая
     улетает на стол без возможности отменить. Внизу под кнопкой панели
     такое касание принимает на себя сама панель, а здесь принимать некому. */
  рукаГлухаДо = Date.now() + ГЛУХОТА_ПОСЛЕ_КНОПКИ;
  const плашка = эл('экран-выхода');
  if (плашка) {
    плашка.classList.remove('экран--виден');
    плашка.classList.remove('экран--поверх');
  }
  // Пока человек думал над выходом, партия вдвоём могла закончиться:
  // плашку итога тогда придержали, чтобы она не легла поверх вопроса.
  // Вопрос убран — показываем итог сейчас.
  if (партия && партия.завершена) { показатьРезультат(); return; }
  if (партия) продолжить();
}

/** Бросить партию и вернуться в меню — чтобы не спасаться перезагрузкой страницы. */
function выйтиВМеню() {
  ждёмОтветПроВыход = false;
  if (таймер !== null) {
    clearTimeout(таймер);
    таймер = null;
  }
  отменитьПоказИтога();
  убратьСобытие();
  выбраннаяКарта = null;
  // Друга предупреждаем до того, как забудем партию: иначе он будет ждать
  // ходов от игрока, который уже ушёл.
  оставитьСетевуюПартию();
  режим = РЕЖИМ_БОТ;
  партия = null;
  показатьЭкран('экран-меню');
}

/* =====================================================================
   ЧАСТЬ 3. НАСТРОЙКИ, ЗВУК И РЕКОРДЫ
   ===================================================================== */

/* Рекорды хранит js/telegram.js (облако Telegram, а без него — память
   браузера). Здесь лежат только три мелочи самой игры: какой выбран
   соперник, включён ли звук и сколько побед подряд набрано сейчас.
   Они нужны мгновенно, ещё до ответа облака, поэтому лежат рядом. */
const КЛЮЧ_СЛОЖНОСТИ = 'подкидной-дурак:сложность';
const КЛЮЧ_ЗВУКА = 'подкидной-дурак:звук';
const КЛЮЧ_СЕРИИ = 'подкидной-дурак:серия';
/* Четвёртая мелочь: показывали ли уже подсказки самому первому игроку.
   Стоит здесь, а не в облаке, нарочно: подсказка нужна ровно один раз
   и ровно на этом устройстве, а гонять её через сеть — значит показать
   новичку пустую строку, пока облако отвечает. */
const КЛЮЧ_ПОДСКАЗОК_НОВИЧКУ = 'подкидной-дурак:подсказки-новичку';

/** Прочитать настройку. Памяти нет (или она запрещена) — вернём null, игра переживёт. */
function прочитатьНастройку(ключ) {
  try {
    return window.localStorage.getItem(ключ);
  } catch (ошибка) {
    return null;
  }
}

function записатьНастройку(ключ, значение) {
  try {
    window.localStorage.setItem(ключ, значение);
  } catch (ошибка) {
    /* запрещённая память — не повод ломать игру */
  }
}

let сложность = проверитьСложность(прочитатьНастройку(КЛЮЧ_СЛОЖНОСТИ));
let звукВключён = прочитатьНастройку(КЛЮЧ_ЗВУКА) !== 'выключен';
let серияПобед = Math.max(0, Number(прочитатьНастройку(КЛЮЧ_СЕРИИ)) || 0);
// Один раз в жизни объясняем подсветку карт и даём дочитать, кто ходит первым.
let подсказкиНовичкуПоказаны = прочитатьНастройку(КЛЮЧ_ПОДСКАЗОК_НОВИЧКУ) === 'показаны';

/** Слово «победа» после числа: 1 победа, 2 победы, 5 побед. */
function словоПобед(сколько) {
  const двеПоследние = сколько % 100;
  const последняя = сколько % 10;
  if (двеПоследние >= 11 && двеПоследние <= 14) return 'побед';
  if (последняя === 1) return 'победа';
  if (последняя >= 2 && последняя <= 4) return 'победы';
  return 'побед';
}

/* ---------------------------------------------------------------------
   Выбор соперника
   --------------------------------------------------------------------- */

function выбратьСложность(новая) {
  сложность = проверитьСложность(новая);
  записатьНастройку(КЛЮЧ_СЛОЖНОСТИ, сложность);
  показатьВыбраннуюСложность();
}

/**
 * Отметить нажатую кнопку в ряду выбора и погасить остальные.
 * Рядов таких в меню четыре — соперник и три про стол, — и пометка у всех
 * одна и та же. Отвечает «нет», если ряда в разметке нет вовсе: тогда
 * зовущий сам решает, ругаться ему или промолчать.
 */
function отметитьКнопкиВыбора(идРяда, значение) {
  const ряд = эл(идРяда);
  if (!ряд) return false;
  for (const кнопка of ряд.querySelectorAll('.кнопка--выбор')) {
    кнопка.classList.toggle('кнопка--активная', кнопка.value === значение);
  }
  return true;
}

/** Повесить одно действие на все кнопки одного ряда выбора. */
function наКнопкиВыбора(идРяда, действие) {
  const ряд = эл(идРяда);
  if (!ряд) return false;
  for (const кнопка of ряд.querySelectorAll('.кнопка--выбор')) {
    кнопка.addEventListener('click', function () {
      действие(кнопка.value);
      звукКарты();
    });
  }
  return true;
}

/** Показать в меню выбранного соперника: словами в подписи и нажатой кнопкой. */
function показатьВыбраннуюСложность() {
  /* Подпись пишем первой, до кнопок, и это важно. Она заведена ровно для того
     случая, когда нажатую кнопку не видно, — а самый крайний такой случай
     тот, где ряда кнопок нет вовсе (браузер отдал старую страницу). Стой она
     после отметки, именно тогда бы и пропала. */
  написать('подпись-сложности', 'Соперник: ' + сложность);
  отметитьКнопкиВыбора('выбор-сложности', сложность);
}

function подключитьВыборСложности() {
  if (!наКнопкиВыбора('выбор-сложности', выбратьСложность)) {
    console.warn('Игра: не нашёл выбор сложности — играем обычным соперником.');
  }
}

/* ---------------------------------------------------------------------
   Каким будет стол с ботами: сколько играет, по каким правилам и кто
   против кого. Это те же три выбора, что человек делает, создавая стол
   для игры с другом, — и кнопки в меню стоят такие же нарочно.

   По умолчанию здесь двое и обычные правила: тот, кто просто жмёт
   «Играть», не должен заметить, что кнопки вообще появились.

   Выбор запоминается в памяти браузера — так же, как уровень соперника
   и звук. Человек, собравший стол на четверых, завтра садится за тот же
   стол, а не за вчерашний.
   --------------------------------------------------------------------- */

const КЛЮЧ_МЕСТ_С_БОТАМИ = 'подкидной-дурак:мест-с-ботами';
const КЛЮЧ_ПЕРЕВОДНОГО_С_БОТАМИ = 'подкидной-дурак:переводной-с-ботами';
const КЛЮЧ_ПАР_С_БОТАМИ = 'подкидной-дурак:парами-с-ботами';

/**
 * Число мест из памяти. Всё, что не число (пусто, буквы, чужая запись), —
 * это двое; число вгоняем в разрешённые границы, поэтому «9» станет шестью,
 * а «0» — двумя. Так игра не падает ни от чьей правки в памяти браузера.
 */
function прочитатьЧислоМест() {
  const число = Number(прочитатьНастройку(КЛЮЧ_МЕСТ_С_БОТАМИ));
  if (!Number.isFinite(число)) return МИН_ИГРОКОВ;
  return Math.min(МАКС_ИГРОКОВ, Math.max(МИН_ИГРОКОВ, Math.floor(число)));
}

const настройкиИгрыСБотами = {
  игроков: прочитатьЧислоМест(),
  переводной: прочитатьНастройку(КЛЮЧ_ПЕРЕВОДНОГО_С_БОТАМИ) === 'да',
  парами: прочитатьНастройку(КЛЮЧ_ПАР_С_БОТАМИ) === 'да'
};

/* Память могла остаться от прежней игры или быть поправлена руками:
   приводим её к тому, что правила вообще умеют, — парная игра бывает только
   вчетвером. Делаем это один раз при запуске, а не при каждой партии. */
if (настройкиИгрыСБотами.парами) настройкиИгрыСБотами.игроков = ИГРОКОВ_В_ПАРАХ;

/* Тот же самый объект отдан наружу под именем «ИграСБотами». Он нужен
   проверкам: тестировщик собирает стол из консоли браузера
   (`ИграСБотами.игроков = 4`) и жмёт «Играть» — так прогоны не зависят
   от вёрстки меню. Кнопки пишут в него же, поэтому вторая правда
   не заводится.

   Два честных предупреждения тому, кто ею пользуется. Первое: изменение
   из консоли кнопки в меню не перерисовывает — они так и останутся стоять
   на прежнем выборе. Второе, неочевидное: само по себе оно в память
   не сохраняется, НО первое же нажатие любой кнопки меню запишет в память
   весь этот объект целиком — вместе с тем, что вписано из консоли. То есть
   собранный из консоли стол способен пережить прогон и достаться следующему.
   Хотите начать с чистого листа — соберите стол кнопками. */
if (typeof window !== 'undefined') window.ИграСБотами = настройкиИгрыСБотами;

/** Запомнить выбранный стол, чтобы он пережил закрытие игры. */
function запомнитьСтолСБотами() {
  записатьНастройку(КЛЮЧ_МЕСТ_С_БОТАМИ, String(настройкиИгрыСБотами.игроков));
  записатьНастройку(КЛЮЧ_ПЕРЕВОДНОГО_С_БОТАМИ, настройкиИгрыСБотами.переводной ? 'да' : 'нет');
  записатьНастройку(КЛЮЧ_ПАР_С_БОТАМИ, настройкиИгрыСБотами.парами ? 'да' : 'нет');
}

/** Человек ничего не менял — значит это прежняя игра с одним ботом. */
function столСБотамиОбычный() {
  return настройкиИгрыСБотами.игроков === МИН_ИГРОКОВ &&
         !настройкиИгрыСБотами.переводной && !настройкиИгрыСБотами.парами;
}

/* Числа словами: «играют трое» читается легче, чем «играют 3».
   Те же слова, что и на экране игры с другом. Ботов считаем отдельным
   списком, чтобы не заводить склонение ради пяти слов. */
const ЧИСЛО_ИГРОКОВ_СЛОВАМИ = { 2: 'двое', 3: 'трое', 4: 'четверо', 5: 'пятеро', 6: 'шестеро' };
const СКОЛЬКО_БОТОВ_СЛОВАМИ = { 1: 'бот', 2: 'два бота', 3: 'три бота',
                                4: 'четыре бота', 5: 'пять ботов' };

/* Что игра поменяла за человека в последнее нажатие. Живой новичок поймал
   игру на молчаливой подмене: «нажал „Парами“ при шестерых — число мест
   само перескочило на 4, заметил только потому, что специально читал строку
   внизу», и наоборот — «нажал „6“ при парах, и „парами“ молча слетело».
   Поэтому подмена теперь называется вслух и стоит ПЕРВОЙ фразой: её читают
   раньше всего остального, а остальное никуда не денется. */
let подменаВВыборе = '';

/**
 * Что получится при нынешнем выборе — обычными словами, без терминов.
 *
 * Фразы здесь короткие нарочно. Строка стоит прямо над кнопкой «Играть»,
 * и чем сильнее она меняется в высоте, тем заметнее кнопка уезжает
 * из-под пальца. Самое длинное объяснение — 118 знаков: это когда к обычному
 * рассказу («Мест стало четверо — парами играют только вчетвером.») добавлен
 * ещё и переводной. Место под такую строку в оформлении отложено заранее,
 * поэтому кнопка не прыгает; выходить за него всё же не стоит.
 */
function словаПроСтолСБотами() {
  if (столСБотамиОбычный()) return подменаВВыборе + 'Двое, обычные правила — привычная игра с ботом.';
  const мест = настройкиИгрыСБотами.игроков;
  const сколько = ЧИСЛО_ИГРОКОВ_СЛОВАМИ[мест] || мест;
  const ботов = СКОЛЬКО_БОТОВ_СЛОВАМИ[мест - 1] || (мест - 1);
  let текст = 'Играют ' + сколько + ': вы и ' + ботов + '. ';
  /* С пяти игроков правила сами берут колоду в 52 карты: обычной на такой стол
     не хватает (см. «выбратьРазмерКолоды»). Сказать об этом надо заранее —
     иначе человек увидит на столе двойки и тройки, каких в дураке отродясь
     не видел, и решит, что игра сломалась. */
  if (мест >= ПОРОГ_БОЛЬШОЙ_КОЛОДЫ) текст += 'В колоде 52 карты — есть и двойки. ';
  /* Про «только вчетвером» говорим ровно тогда, когда это к месту: человек
     нажал «Парами», и число мест у него на глазах стало четыре. Заранее,
     до нажатия, эта фраза только пугала бы лишним условием. */
  /* «Только вчетвером» здесь больше не говорим: ровно эту мысль несёт фраза
     о подмене, и рядом они читались как заикание. Тут — что такое парами. */
  if (настройкиИгрыСБотами.парами) текст += 'Парами: 2 на 2, напарник напротив. ';
  if (настройкиИгрыСБотами.переводной) текст += 'Переводной: ход можно перевести соседу.';
  return (подменаВВыборе + текст).trim();
}

/** Показать выбранный стол на кнопках и объяснить словами, что получится. */
function показатьВыборСтолаСБотами() {
  отметитьКнопкиВыбора('меню-выбор-мест', String(настройкиИгрыСБотами.игроков));
  отметитьКнопкиВыбора('меню-выбор-правил',
    настройкиИгрыСБотами.переводной ? 'переводной' : 'обычный');
  отметитьКнопкиВыбора('меню-выбор-пар', настройкиИгрыСБотами.парами ? 'парами' : 'каждый');
  написать('меню-пояснение-стола', словаПроСтолСБотами());
}

/**
 * Сколько человек за столом. Выбрали не четверых, когда включено «Парами», —
 * «Парами» выключается само: парной игры на троих или пятерых в правилах нет
 * вовсе, и молча оставлять кнопку нажатой значило бы обещать невыполнимое.
 * Ровно так же ведут себя такие же кнопки на экране «Игра с другом».
 */
function выбратьМестаСБотами(сколько) {
  const число = Number(сколько);
  if (!(число >= МИН_ИГРОКОВ && число <= МАКС_ИГРОКОВ)) return;
  настройкиИгрыСБотами.игроков = число;
  подменаВВыборе = '';
  if (настройкиИгрыСБотами.парами && число !== ИГРОКОВ_В_ПАРАХ) {
    настройкиИгрыСБотами.парами = false;
    подменаВВыборе = 'Парами выключились — их играют только вчетвером. ';
  }
  запомнитьСтолСБотами();
  показатьВыборСтолаСБотами();
}

/**
 * Включить или выключить игру парами. Включили при другом числе мест —
 * сами ставим четыре: человек выбирал игру, а не число мест, и упираться
 * тут не во что. Об этом же говорит строка пояснения под кнопками.
 */
function выбратьПарыСБотами(парами) {
  подменаВВыборе = '';
  if (парами && настройкиИгрыСБотами.игроков !== ИГРОКОВ_В_ПАРАХ) {
    подменаВВыборе = 'Мест стало четверо — парами играют только вчетвером. ';
  }
  настройкиИгрыСБотами.парами = парами;
  if (парами) настройкиИгрыСБотами.игроков = ИГРОКОВ_В_ПАРАХ;
  запомнитьСтолСБотами();
  показатьВыборСтолаСБотами();
}

function подключитьВыборСтолаСБотами() {
  /* Каждый ряд подключаем отдельно и только потом смотрим на итог: пропал
     один ряд — остальные обязаны работать. Через «&&» в одной строке
     первый же пропавший ряд оставил бы игру вовсе без выбора стола. */
  const мест = наКнопкиВыбора('меню-выбор-мест', выбратьМестаСБотами);
  const правил = наКнопкиВыбора('меню-выбор-правил', function (значение) {
    подменаВВыборе = '';   // правила ничего за человека не меняют
    настройкиИгрыСБотами.переводной = (значение === 'переводной');
    запомнитьСтолСБотами();
    показатьВыборСтолаСБотами();
  });
  const пар = наКнопкиВыбора('меню-выбор-пар', function (значение) {
    выбратьПарыСБотами(значение === 'парами');
  });
  if (!мест || !правил || !пар) {
    /* Говорим ровно то, что будет: без кнопок стол не станет прежним сам собой —
       он возьмётся из памяти браузера, а там может лежать хоть шестеро.
       Поменять его будет нечем, поэтому и называем вслух, за какой стол сядем. */
    console.warn('Игра: не нашёл в меню выбор стола — поменять его будет нечем. ' +
                 'Стол возьмём из памяти браузера: ' + словаПроСтолСБотами() + ' ' +
                 'Скорее всего, браузер показывает старую страницу — обновите её (Ctrl+F5).');
  }
  показатьВыборСтолаСБотами();
}

/* ---------------------------------------------------------------------
   Звук. Файлов со звуками в проекте нет: короткие сигналы собираются
   прямо в браузере через Web Audio API.
   --------------------------------------------------------------------- */

const ГРОМКОСТЬ = 0.07;   // тихо: игра часто идёт в наушниках в транспорте
let звуковойДвижок = null;

/** Звуковой движок браузера. Создаём при первом звуке: до нажатия кнопки браузер его не даёт. */
function получитьЗвуковойДвижок() {
  if (звуковойДвижок) return звуковойДвижок;
  try {
    const Движок = window.AudioContext || window.webkitAudioContext;
    if (!Движок) return null;
    звуковойДвижок = new Движок();
  } catch (ошибка) {
    звуковойДвижок = null;
  }
  return звуковойДвижок;
}

/**
 * Один короткий сигнал: частота в герцах, длительность и задержка в секундах.
 * Нарастание и затухание нужны обязательно — без них слышен щелчок на краях.
 */
function сигнал(частота, длительность, задержка) {
  if (!звукВключён) return;
  const движок = получитьЗвуковойДвижок();
  if (!движок) return;
  try {
    if (движок.state === 'suspended') движок.resume();
    const начало = движок.currentTime + (задержка || 0);
    const генератор = движок.createOscillator();
    const громкость = движок.createGain();
    генератор.type = 'triangle';        // мягче синуса и без резкости квадрата
    генератор.frequency.setValueAtTime(частота, начало);
    громкость.gain.setValueAtTime(0.0001, начало);
    громкость.gain.exponentialRampToValueAtTime(ГРОМКОСТЬ, начало + 0.012);
    громкость.gain.exponentialRampToValueAtTime(0.0001, начало + длительность);
    генератор.connect(громкость);
    громкость.connect(движок.destination);
    генератор.start(начало);
    генератор.stop(начало + длительность + 0.02);
  } catch (ошибка) {
    /* звук — не то, ради чего стоит ронять игру */
  }
}

function звукКарты()     { сигнал(330, 0.07); }
/* Звук отказа нарочно ниже и короче звука хода: ход — 330 Гц, отказ — 150.
   Разница больше октавы, поэтому «получилось» и «нельзя» не спутать даже
   в шуме транспорта. Общей кнопки звука он слушается сам: проверку
   звукВключён делает сигнал(), а других путей к динамику в игре нет. */
function звукОтказа()    { сигнал(150, 0.05); }
function звукВзятия()    { сигнал(190, 0.14); }
function звукПобеды()    { сигнал(523, 0.12); сигнал(784, 0.20, 0.13); }
function звукПроигрыша() { сигнал(300, 0.16); сигнал(160, 0.30, 0.16); }

function переключитьЗвук() {
  звукВключён = !звукВключён;
  записатьНастройку(КЛЮЧ_ЗВУКА, звукВключён ? 'включен' : 'выключен');
  показатьСостояниеЗвука();
  if (звукВключён) звукКарты();   // сразу слышно, что включилось
}

function показатьСостояниеЗвука() {
  const кнопка = эл('кнопка-звук');
  if (!кнопка) return;
  кнопка.textContent = звукВключён ? 'Звук включён' : 'Звук выключен';
  кнопка.classList.toggle('кнопка--выключено', !звукВключён);
}

/* ---------------------------------------------------------------------
   Серия побед и таблица рекордов
   --------------------------------------------------------------------- */

function запомнитьСерию() {
  записатьНастройку(КЛЮЧ_СЕРИИ, String(серияПобед));
}

/** Есть ли рядом рабочий js/telegram.js с хранением рекордов. */
function хранилищеРаботает() {
  if (typeof loadScore !== 'function' || typeof saveScore !== 'function') return false;
  if (typeof isReady === 'function' && !isReady()) return false;
  return true;
}

/** Добавить в строку таблицы одну ячейку. */
function ячейка(строка, класс, текст) {
  const узел = document.createElement('span');
  узел.className = класс;
  узел.textContent = текст;
  строка.appendChild(узел);
  return узел;
}

/** Нарисовать таблицу рекордов по ответу хранилища. */
function нарисоватьРекорды(рекорды) {
  const таблица = эл('таблица-рекордов');
  const подпись = эл('лучший-рекорд');
  if (!таблица || !подпись) return;
  таблица.innerHTML = '';

  const записи = рекорды && Array.isArray(рекорды.таблица) ? рекорды.таблица : [];
  if (записи.length === 0) {
    подпись.textContent = 'Здесь пока пусто';
    const пусто = document.createElement('p');
    пусто.className = 'таблица__пусто';
    пусто.textContent = 'Выиграйте партию — сюда попадёт ваша серия побед подряд. ' +
                        'Проигрыш серию обнуляет, ничья её не трогает.';
    таблица.appendChild(пусто);
    return;
  }

  подпись.textContent = 'Лучшая серия: ' + рекорды.лучший + ' ' + словоПобед(рекорды.лучший);
  записи.forEach(function (запись, номер) {
    const строка = document.createElement('div');
    строка.className = 'таблица__строка';
    ячейка(строка, 'таблица__место', номер + 1 + '.');
    ячейка(строка, 'таблица__очки', запись.очки + ' ' + словоПобед(запись.очки) + ' подряд');
    ячейка(строка, 'таблица__дата', запись.дата || '');
    ячейка(строка, 'таблица__сложность', запись.сложность || '');
    таблица.appendChild(строка);
  });
}

function показатьРекорды() {
  показатьЭкран('экран-рекордов');
  const таблица = эл('таблица-рекордов');
  const подпись = эл('лучший-рекорд');
  if (!таблица || !подпись) return;

  if (!хранилищеРаботает()) {
    таблица.innerHTML = '';
    подпись.textContent = 'Рекорды сейчас сохранять некуда';
    const пояснение = document.createElement('p');
    пояснение.className = 'таблица__пусто';
    пояснение.textContent = 'Игра не смогла добраться до хранилища. ' +
                            'Играть можно, но результаты не запомнятся.';
    таблица.appendChild(пояснение);
    return;
  }

  подпись.textContent = 'Загружаем…';
  показатьОжиданиеРекордов(таблица);
  loadScore().then(нарисоватьРекорды);
}

/** Пока рекорды едут из облака, показываем, что игра не зависла. */
function показатьОжиданиеРекордов(таблица) {
  таблица.innerHTML = '';
  const ждём = document.createElement('p');
  ждём.className = 'таблица__пусто';
  ждём.textContent = 'Минутку…';
  таблица.appendChild(ждём);
}

/** Вернуться в меню с экрана рекордов. Партию не трогаем — её здесь нет. */
function вернутьсяВМеню() {
  показатьЭкран('экран-меню');
}

/**
 * Короткие правила. Открываются только из меню и только по своей кнопке:
 * никого читать не заставляем, а тому, кто в дурака не играл, без них
 * не с чего начать.
 */
function показатьПравила() {
  показатьЭкран('экран-правил');
}

/* За каким столом набрана серия — теми же словами, что и везде в игре.
   Двоих в списке нет нарочно: игра один на один так и остаётся подписанной
   одним уровнем, как была подписана всегда. */
const СТОЛ_В_РЕКОРДЕ = { 3: 'втроём', 4: 'вчетвером', 5: 'впятером', 6: 'вшестером' };

/**
 * Чем подписать строку рекорда.
 *
 * Раньше это был просто уровень соперника, и строка «4 победы подряд ·
 * 01.09.2026 · лёгкий» выглядела одинаково после победы один на один
 * и после победы за столом на шестерых. А выигрывать компанией заметно
 * легче: по замеру вшестером человек берёт 149 партий из 200, вдвоём — 67.
 * Поэтому к уровню добавляется стол: «лёгкий · вшестером», «лёгкий · парами».
 *
 * Уровень берём у самой партии, а не из меню: в меню его могли переключить
 * уже после её начала, и рекорд ушёл бы не с тем соперником. Стол — оттуда же
 * и по той же причине, и ещё потому, что правила могли поправить выбор
 * (парами бывают только вчетвером).
 *
 * НОВОГО ПОЛЯ В ХРАНИЛИЩЕ НЕ ЗАВЕЛОСЬ: стол дописывается в то же самое поле
 * «сложность». Договор с js/telegram.js от этого не сдвинулся — наружу
 * он по-прежнему отдаёт ровно три функции.
 *
 * НО ПОДПИСЬ ЭТУ ХРАНИЛИЩЕ РАЗБИРАЕТ, и об этом надо знать, прежде чем
 * менять здесь хоть знак. Оно берёт из подписи уровень, чтобы серию,
 * сыгранную на разных уровнях, подписать самым лёгким из них (иначе игроку
 * припишут заслугу, которой не было). Отсюда два жёстких условия:
 *
 *   1) УРОВЕНЬ СТОИТ ПЕРВЫМ, до разделителя. Поменяете порядок — хранилище
 *      перестанет узнавать уровень, и подписи серий начнут молча врать:
 *      три победы на лёгком плюс одна на сложном запишутся как «сложный»;
 *   2) РАЗДЕЛИТЕЛЬ — ровно ' · ' (пробел, точка посередине, пробел), и он
 *      ПРОДУБЛИРОВАН в js/telegram.js (там он зовётся РАЗДЕЛИТЕЛЬ_ПОДПИСИ).
 *      Это две копии одной мерки, и держатся они на дисциплине: менять их
 *      можно только вместе. Поменяли здесь — идите и меняйте там.
 *
 * Старые записи, где стола нет, читаются и показываются как есть. Дописывать
 * им стол задним числом нельзя: за каким столом они набраны, никто уже
 * не знает.
 *
 * ОДНА НЕТОЧНОСТЬ, И ОНА ЗДЕСЬ НАРОЧНО. Серию, набранную за разными столами
 * (выиграл вчетвером, потом вдвоём), запись пометит столом ПОСЛЕДНЕЙ партии —
 * так решено: обрывать серию из-за смены стола нечестно, человек воспримет
 * потерю пяти побед подряд как несправедливость. Уровень при этом остаётся
 * самым лёгким, как и был. Так что если увидите такую запись — это
 * не поломка, а принятое решение.
 */
function подписьРекорда() {
  const уровень = партия ? партия.сложность : сложность;
  if (!партия) return уровень;
  if (партия.парами) return уровень + ' · парами';
  const стол = СТОЛ_В_РЕКОРДЕ[партия.игроки.length];
  return стол ? уровень + ' · ' + стол : уровень;
}

/**
 * Подвести серию побед после партии и записать результат.
 * Победа растит серию, проигрыш обнуляет, ничья не меняет ничего.
 *
 * Довод — уже готовый исход одним словом ('победа', 'поражение', 'ничья'),
 * его считает «чемКончилосьДляМеня». Раньше сюда передавали имя дурака,
 * и разбирать его приходилось здесь — из-за этого за столом компанией
 * победа в серию не попадала вовсе.
 */
function подвестиСерию(чемКончилось) {
  if (чемКончилось === 'победа') {
    серияПобед++;
    запомнитьСерию();
    написатьВРамкуИтога('Побед подряд: ' + серияПобед + ' — записываем…');
    if (хранилищеРаботает()) {
      saveScore(серияПобед, подписьРекорда()).then(function (рекорды) {
        const лучший = рекорды && рекорды.лучший ? рекорды.лучший : серияПобед;
        написатьВРамкуИтога(серияПобед >= лучший
          ? 'Побед подряд: ' + серияПобед + '. Это ваш рекорд!'
          : 'Побед подряд: ' + серияПобед + '. Лучшая серия: ' + лучший);
      });
    } else {
      написатьВРамкуИтога('Побед подряд: ' + серияПобед + ' (сохранить не удалось)');
    }
    return;
  }

  if (чемКончилось === 'поражение') {   // остались с картами — серия обрывается
    const была = серияПобед;
    серияПобед = 0;
    запомнитьСерию();
    написатьВРамкуИтога(была > 0
      ? 'Серия прервана: было ' + была + ' ' + словоПобед(была) + ' подряд'
      : 'Побед подряд: 0');
    return;
  }

  // ничья серию не трогает
  написатьВРамкуИтога('Ничья серию не прерывает. Побед подряд: ' + серияПобед);
}

/**
 * Подключить нажатие к кнопке.
 * Раньше кнопки подключались подряд, и если одной не оказывалось в разметке
 * (например, браузер отдал старую страницу из кэша), настройка обрывалась
 * на полуслове: не подключался даже пересчёт размеров при повороте экрана.
 * Теперь пропавшая кнопка — это запись в консоли, а не сломанная игра.
 */
function наКнопку(id, действие) {
  const узел = эл(id);
  if (!узел) {
    console.warn('Игра: не нашёл кнопку «' + id + '», она работать не будет. ' +
                 'Скорее всего, браузер показывает старую страницу — обновите её (Ctrl+F5).');
    return false;
  }
  узел.addEventListener('click', действие);
  return true;
}

function запустить() {
  // Сначала то, что не зависит от разметки: размеры и реакция на поворот экрана.
  подобратьРазмерКарты();
  window.addEventListener('resize', function () {
    подобратьРазмерКарты();
    перерисовать();
  });

  наКнопку('кнопка-играть', начатьПартию);
  наКнопку('кнопка-ещё', нажатьЕщёПартию);
  наКнопку('кнопка-завершить', нажатьБито);
  наКнопку('кнопка-беру', нажатьБеру);
  кнопкаПеревода();   // её в разметке нет: создаём сами, вместе с нажатием
  наКнопку('колода', тапПоКолоде);   // не кнопка, но нажатие ловим так же
  наКнопку('рука-человека', тапМимоКарты);   // ответ на нажатие мимо карты
  наКнопку('метка-козыря', тапПоКозырю);   // лежит рядом с колодой, а не внутри
  наКнопку('кнопка-в-меню', спроситьПроВыход);
  наКнопку('кнопка-в-меню-итог', выйтиВМеню);   // партия уже кончилась, спрашивать не о чем
  наКнопку('кнопка-выход-да', выйтиВМеню);
  наКнопку('кнопка-выход-нет', остатьсяВПартии);
  наКнопку('кнопка-рекорды', показатьРекорды);
  наКнопку('кнопка-рекорды-назад', вернутьсяВМеню);
  наКнопку('кнопка-как-играть', показатьПравила);
  наКнопку('кнопка-правила-назад', вернутьсяВМеню);
  наКнопку('кнопка-звук', переключитьЗвук);
  подключитьВыборСложности();
  показатьВыбраннуюСложность();
  подключитьВыборСтолаСБотами();   // сам же и покажет выбранный стол
  показатьСостояниеЗвука();
}

/* =====================================================================
   ЧАСТЬ 4. ИГРА ВДВОЁМ: МОСТ К СЕРВЕРУ

   Здесь нет ни правил, ни сети. Правила в игре вдвоём считает сервер,
   с сервером разговаривает js/сеть.js, а этот кусок делает одно:
   превращает присланное сервером состояние в такой же объект партии,
   какой игра рисует всю дорогу. Поэтому стол, веер карт, подсветка
   «можно/нельзя» и два ряда при большой руке работают в сетевой игре
   сами собой — ни одна строка отрисовки под сеть не переписана.

   Чего здесь нарочно нет: своей проверки ходов. Клиент может ошибиться
   или отстать от жизни, поэтому последнее слово всегда за сервером —
   он и присылает то состояние, которое мы показываем.
   ===================================================================== */

const РЕЖИМ_БОТ = 'бот';
const РЕЖИМ_СЕТЬ = 'сеть';

let режим = РЕЖИМ_БОТ;          // с кем идёт партия прямо сейчас
let ждёмОтветСервера = false;   // ход отправлен, ответа ещё нет
let номерПоказанногоСобытия = 0;
let сетьПредупредилаОРазладе = false;
let другУшёлИзПартии = false;   // за столом больше некого звать на реванш
let насВывелиИзПартии = false;  // сервер счёл нас пропавшими и закрыл партию без нас
/* Вторая фраза под заголовком итога в игре вдвоём: что произошло с другом
   и что делать дальше. Держим её отдельной строкой, потому что заголовок
   с объяснением пишутся в одном месте, а новости от сервера приходят в другом
   и позже — иногда уже после того, как плашка итога легла на экран. */
let подсказкаПослеПартии = '';

/** Идёт ли сейчас партия с живым другом. */
function этоСетеваяИгра() {
  return режим === РЕЖИМ_СЕТЬ;
}

/* Что отвечать на тапы, пока ход летит к серверу. На медленной связи ответа
   ждать до десяти секунд, и всё это время стол на экране устаревший:
   поднятая карта уже опущена, а очередь хода, возможно, давно наша.
   Разбирать такое состояние — значит врать человеку: он получал бы
   «сначала выберите карту» сразу после того, как выбрал её и сходил.
   Поэтому здесь один честный ответ, без разбора стола. */
const ТЕКСТ_ХОД_ЛЕТИТ = 'Ход отправлен, ждём ответ игры';

/** Ход уже улетел к серверу, а ответа ещё нет. */
function ждёмОтветаНаХод() {
  return этоСетеваяИгра() && ждёмОтветСервера;
}

/**
 * Есть ли смысл показывать кнопку «Ещё партию». Звать на реванш некого
 * в двух случаях: друг ушёл из-за стола или сервер вывел из партии нас самих
 * (пропал интернет). В обоих сервер отвечает на кнопку отказом, а отказ
 * попадает в строку подсказки, закрытую плашкой итога, — для человека это
 * выглядит сломанной кнопкой. Поэтому кнопку убираем совсем.
 * В одиночной игре кнопка «Играть ещё» видна всегда.
 */
function реваншВозможен() {
  return !этоСетеваяИгра() || (!другУшёлИзПартии && !насВывелиИзПартии);
}

/**
 * Подключён ли файл js/сеть.js. Игра работает и без него — просто
 * остаётся одиночной, а кнопка «Играть с другом» ничего не откроет.
 */
function естьСеть() {
  return typeof window !== 'undefined' && window.Сеть &&
         typeof window.Сеть.отправитьХод === 'function';
}

/** Сказать серверу, что мы уходим, и погасить опрос. Вне сетевой партии — пустое действие. */
function оставитьСетевуюПартию() {
  // Хвосты прошлой сетевой партии не должны достаться игре с ботом:
  // иначе там останется надпись «Отправляем ход…» или спрятанная кнопка.
  ждёмОтветСервера = false;
  другУшёлИзПартии = false;
  насВывелиИзПартии = false;
  подсказкаПослеПартии = '';
  показатьСвязь('');
  if (!этоСетеваяИгра() || !естьСеть()) return;
  if (typeof window.Сеть.покинутьПартию === 'function') window.Сеть.покинутьПартию();
}

/**
 * Отправить намерение на сервер. Своё состояние не меняем совсем:
 * пока сервер не ответил, на столе всё по-старому. Так две игры
 * не расходятся: у обоих игроков стол всегда такой, каким его видит сервер.
 */
function отправитьХодНаСервер(намерение) {
  if (!естьСеть()) {
    // Через тот же отказ, что и в игре с ботом: путь к динамику в игре один,
    // иначе половина отказов пикает, а половина молчит без всякой причины.
    отказатьСловами('Связи с игрой нет — ход не отправлен');
    return null;
  }
  выбраннаяКарта = null;
  if (ждёмОтветСервера) return null;   // второй тап, пока летит первый
  ждёмОтветСервера = true;
  // Пока ход летит, человек видит «Отправляем ход…»: на медленной связи
  // ответа ждать до десяти секунд, и молчащий экран выглядит зависшим.
  нарисоватьСтрокуСвязи();
  перерисовать();

  return window.Сеть.отправитьХод(намерение).then(function (ответ) {
    перестатьЖдатьОтвет();
    // Состояние из ответа применит сам js/сеть.js — дверь одна.
    if (!ответ || ответ.ошибкаСвязи) return null;   // про связь расскажет строка связи
    // Отказ сервера — такой же отказ, как свой: со звуком и по тем же правилам показа.
    if (!ответ.принято && ответ.причина) отказатьСловами(ответ.причина);
    if (партия) перерисовать();
    return ответ;
  }, function () {
    // Ответа не будет совсем. Ожидание всё равно надо снять, иначе игра
    // так и останется «отправляющей ход» и перестанет принимать нажатия.
    перестатьЖдатьОтвет();
    return null;
  });
}

/** Ответ пришёл (или уже не придёт): снимаем ожидание и возвращаем строку связи. */
function перестатьЖдатьОтвет() {
  ждёмОтветСервера = false;
  нарисоватьСтрокуСвязи();
}

/**
 * Кнопка на экране итога. В одиночной игре это новая партия с ботом,
 * в игре вдвоём — предложение сыграть ещё в той же комнате: код и место
 * за столом остаются прежними, карты раздаются заново.
 */
function нажатьЕщёПартию() {
  /* Окно глухоты заводим первой строкой, до всякой развилки. Кнопка «Ещё
     партию» лежит на плашке итога, а та прижата к низу так же, как плашка
     выхода: палец нажимает её ровно над будущей рукой. Дальше в сети сервер
     отвечает быстро, плашка исчезает, новая рука рисуется под тем же местом —
     и хвост того же касания попадает в карту. По правилам реванша первым
     ходит проигравший, так что каждый второй раз этот ход наш и карта уходит
     на стол сама. Отсчёт ведём от пальца, а не от ответа сервера: ответ может
     прийти и через секунду, и тогда защита опоздает. */
  рукаГлухаДо = Date.now() + ГЛУХОТА_ПОСЛЕ_КНОПКИ;
  if (этоСетеваяИгра()) {
    const ответСервера = отправитьХодНаСервер({ действие: 'ещё' });
    // Обещать реванш заранее нельзя: сервер может и отказать (друг уже вышел).
    // Пишем «ждём друга» только после того, как предложение принято.
    if (ответСервера) ответСервера.then(function (ответ) {
      if (ответ && ответ.принято) показатьКонцовку(мыПозвалиНаРеванш());
    });
    return;
  }
  начатьПартию();
}

/* ---------------------------------------------------------------------
   Превращение ответа сервера в привычный объект партии
   --------------------------------------------------------------------- */

/**
 * Карта-невидимка. Такими заполняются чужая рука и колода: игре для
 * отрисовки нужна только их длина, а настоящих карт соперника у нас нет
 * и быть не должно — сервер их не присылает.
 */
function картаНевидимка() {
  return { масть: '', имя: '', вес: 0 };
}

function рядНевидимок(сколько) {
  const ряд = [];
  for (let i = 0; i < сколько; i++) ряд.push(картаНевидимка());
  return ряд;
}

/** Сервер говорит про итог глазами игрока, а игра хранит, кто остался дураком. */
function результатИзИтога(итог) {
  if (итог === 'победа') return 'бот';        // дурак — соперник
  if (итог === 'поражение') return 'человек'; // дурак — я
  if (итог === 'ничья') return 'ничья';
  // Партия оборвалась не по картам: друг ушёл. Дурака в ней нет, и выдавать
  // это за ничью нельзя — карты на руках остались у обоих.
  if (итог === 'соперник-ушёл') return 'друг-ушёл';
  return null;
}

/**
 * Чем кончилась партия вдвоём. Обычные исходы разбирает результатИзИтога,
 * а здесь ловится случай, которого там нет: партия закрыта, а итога сервер
 * не прислал вовсе.
 *
 * Так бывает, когда пропавшим сервер считает нас самих: интернет отвалился
 * на несколько минут (метро, лифт), сервер вывел нас из партии, а когда мы
 * вернулись — партии уже нет. Победы, поражения и «друг ушёл» тут не было,
 * поэтому нужен свой отдельный итог. Без него игра показывала «Ничья.
 * Карты кончились у обоих», хотя карты оставались на руках у обоих.
 */
function результатСетевойПартии(вид) {
  const результат = результатИзИтога(вид.итог);
  if (результат) return результат;
  return вид.завершена ? 'связь-потеряна' : null;
}

/** Целое число из ответа сервера, без сюрпризов вроде null и «пять». */
function целоеИзОтвета(значение) {
  const число = Number(значение);
  return Number.isFinite(число) && число > 0 ? Math.floor(число) : 0;
}

/** Моя рука из ответа сервера. Настоящие карты в ответе только эти. */
function мояРукаИзВида(вид) {
  return Array.isArray(вид.мояРука) ? вид.мояРука.slice() : [];
}

/**
 * Как зовут место в правилах. Своё место всегда «человек»: на это имя
 * завязана вся отрисовка и все проверки, писанные ещё для игры с ботом.
 * Остальные места зовём по номеру — своих имён у мест в правилах нет,
 * а номер сервер присылает у каждого места.
 */
function ключМеста(место) {
  return место.этоЯ ? 'человек' : ('место-' + место.номер);
}

/**
 * Круг игроков для игры компанией: правилам нужны имена мест, руки и список
 * выбывших. Чужие карты — только количество: настоящих у нас нет и быть
 * не должно, поэтому руки соперников набиваем картами-невидимками.
 */
function кругИзВида(вид) {
  const круг = { игроки: [], руки: {}, выбывшие: [] };
  for (const место of вид.застолом) {
    const ключ = ключМеста(место);
    круг.игроки.push(ключ);
    круг.руки[ключ] = место.этоЯ
      ? мояРукаИзВида(вид)
      : рядНевидимок(целоеИзОтвета(место.карт));
    if (место.выбыл) круг.выбывшие.push(ключ);
  }
  // Своё место за столом должно быть всегда: без него рука осталась бы
  // без карт. Если сервер прислал стол без нас — рука всё равно наша.
  if (!круг.руки['человек']) круг.руки['человек'] = мояРукаИзВида(вид);
  return круг;
}

/** Круг игры вдвоём — тот же, что был всегда: мы и соперник напротив. */
function кругНаДвоих(вид) {
  return {
    игроки: ['человек', 'бот'],
    руки: {
      человек: мояРукаИзВида(вид),
      бот: рядНевидимок(целоеИзОтвета(вид.картУСоперника))
    },
    выбывшие: []
  };
}

/** Ключ места, помеченного признаком («ходит» или «отбивается»). */
function ключПоПризнаку(вид, признак) {
  for (const место of вид.застолом) {
    if (место[признак]) return ключМеста(место);
  }
  return null;
}

/** Сосед справа среди тех, кто ещё играет. */
function предыдущийВКруге(партияВида, ключ) {
  const круг = поКругуОт(партияВида, ключ);
  return круг.length > 1 ? круг[круг.length - 1] : ключ;
}

let ужеРугалисьПроАтакующего = false;

/**
 * Кто сейчас атакует. Прямо сервер этого не говорит — он присылает, кто
 * отбивается. Ищем обратным ходом: атакующий это тот, за кем по кругу
 * отбивался бы именно этот игрок. Спрашиваем те же самые правила, по
 * которым круг считали на сервере, поэтому ответ сходится.
 *
 * Зачем вообще нужен атакующий: от него правила считают, сколько карт
 * у отбивающегося, а по этому числу игра решает, можно ли подкинуть ещё.
 */
function ктоАтакуетПоВиду(партияВида, вид) {
  const защитник = ключПоПризнаку(вид, 'отбивается');
  // Партия доиграна: отбиваться некому, и атакующий уже ни на что не влияет.
  if (!защитник) return ключПоПризнаку(вид, 'ходит') || партияВида.игроки[0];
  if (вид.яАтакую) return 'человек';
  for (const ключ of партияВида.игроки) {
    if (ключ === 'человек') continue;          // сервер сказал: атакуем не мы
    if (!вИгре(партияВида, ключ)) continue;
    if (ктоОтбиваетсяЗа(партияВида, ключ) === защитник) return ключ;
  }
  if (!ужеРугалисьПроАтакующего) {
    ужеРугалисьПроАтакующего = true;
    console.warn('Игра компанией: не сошлось, кто атакует. Берём соседа справа ' +
                 'от отбивающегося — кто отбивается, на экране останется верным.');
  }
  return предыдущийВКруге(партияВида, защитник);
}

/** Кто остался дураком — местами круга, как их зовут правила. */
function дуракиИзВида(вид) {
  const дураки = [];
  for (const место of вид.застолом) {
    if (место.проиграл) дураки.push(ключМеста(место));
  }
  return дураки;
}

/**
 * Собрать объект партии из того, что прислал сервер. Форма — ровно та же,
 * что у обычной партии против бота, поэтому дальше игра ничего не замечает.
 *
 * За столом компанией круг собирается по списку мест, а за столом вдвоём —
 * прежний круг из двух имён: игра с одним соперником не должна измениться
 * от того, что рядом появилась игра на шестерых.
 */
function партияИзВида(вид) {
  const стол = Array.isArray(вид.стол) ? вид.стол.map(function (пара) {
    return { атака: пара.атака, защита: пара.защита || null };
  }) : [];

  const компания = Array.isArray(вид.застолом) && вид.застолом.length > 0;
  const круг = компания ? кругИзВида(вид) : кругНаДвоих(вид);

  const партияВида = {
    сложность: СЛОЖНОСТЬ_ПО_УМОЛЧАНИЮ,   // за столом живой человек, уровня у него нет
    // Поля те же, что у обычной партии, иначе правила (например,
    // «кто отбивается») не смогут её прочитать.
    игроки: круг.игроки,
    выбывшие: круг.выбывшие,
    пасы: [],
    парами: вид.парами === true,
    переводной: вид.переводной === true,
    размерКолоды: КОЛОДА_36,
    колода: рядНевидимок(целоеИзОтвета(вид.вКолоде)),
    козырь: вид.козырь || '',
    козырнаяКарта: вид.козырнаяКарта || null,
    руки: круг.руки,
    стол: стол,
    отбой: [],            // сколько карт в отбое, экран не показывает
    атакует: вид.яАтакую ? 'человек' : 'бот',
    берёт: Boolean(вид.берут),
    завершена: Boolean(вид.завершена),
    результат: результатСетевойПартии(вид),
    проигравшие: [],

    /* Дальше — то, что приходит только от стола компанией. Своего мнения
       об этом у браузера нет и быть не может: кто сейчас говорит, кому
       разрешено подкинуть и возможен ли перевод, знает один сервер —
       он же один знает, кто из круга уже сказал «пас». */
    застолом: компания ? вид.застолом : null,
    мойНомер: целоеИзОтвета(вид.мойНомер),
    яХожу: вид.яХожу === true,
    яОтбиваюсь: вид.яОтбиваюсь === true,
    могуПодкинуть: вид.могуПодкинуть === true,
    могуПеревести: вид.могуПеревести === true
  };

  if (компания) {
    партияВида.атакует = ктоАтакуетПоВиду(партияВида, вид);
    партияВида.проигравшие = дуракиИзВида(вид);
  }
  return партияВида;
}

/**
 * Сверка на всякий случай: игра считает очередь хода сама (по столу),
 * сервер присылает её отдельным полем. Если они разошлись — виновата
 * не отрисовка, а расхождение правил, и это надо увидеть сразу.
 * Ругаемся один раз за партию, чтобы не залить консоль.
 */
function сверитьОчередьХода(вид) {
  /* За столом компанией сверять нечем: слово переходит по кругу к тем, кто
     ещё не сказал «пас», а списка сказавших браузеру не присылают вовсе.
     Там очередь целиком на совести сервера — её и показываем. */
  if (этоКомпания()) return;
  const поНашему = ктоХодит(партия) === 'человек';
  if (Boolean(вид.яХожу) === поНашему || вид.завершена || сетьПредупредилаОРазладе) return;
  сетьПредупредилаОРазладе = true;
  console.warn('Игра вдвоём: сервер и игра по-разному считают, чей сейчас ход. ' +
               'Показываем то, что сказал сервер.');
}

/* ---------------------------------------------------------------------
   Показ сетевой партии
   --------------------------------------------------------------------- */

/* Строка связи над столом одна, а пишут в неё двое: js/сеть.js рассказывает
   про друга и про обрыв, игра — про свой отправленный ход. Причём js/сеть.js
   освежает её раз в секунду, поэтому просто написать туда «Отправляем ход…»
   нельзя: надпись сотрут через секунду. Вести от сети держим отдельно и,
   пока ход летит, показываем поверх них своё ожидание. */
let вестиОСвязи = { текст: '', вид: '' };

/** Строка связи над столом: «ждём друга», «связь потеряна» и прочее. */
function показатьСвязь(текст, вид) {
  вестиОСвязи = { текст: текст || '', вид: вид || '' };
  нарисоватьСтрокуСвязи();
}

/* Вести о связи бывают двух родов: про нас самих («Связь с игрой потеряна»,
   «Соединяемся с игрой…») и про того, кто напротив («Друг на связи»,
   «Друг думает…»). Второй род писался для игры вдвоём, где друг ровно один.
   За столом компанией он врёт: соперников там до пяти, а бывает, что и вовсе
   одни боты, — и внизу висит «Друг на связи» при живом игроке, у которого
   в полосе соперников уже написано «нет связи». Два противоречащих сообщения
   на одном экране хуже, чем одно.

   Поэтому в компании вести про одного соперника не показываем вовсе: кто
   на связи, кто пропал и кто ушёл, поимённо сказано в полосе соперников
   наверху, а лишняя строка на телефоне отнимает высоту, которой и так мало.
   Вести про свою связь остаются: их полоса соперников показать не может.

   Узнаём вести про соперника по первому слову — все они начинаются
   со слова «Друг». */
const ВЕСТЬ_ПРО_ДРУГА = /^Друг/;

/** Годится ли весть от сети для этого стола. */
function вестьГодитсяСтолу(текст) {
  if (!этоКомпания()) return true;
  return !ВЕСТЬ_ПРО_ДРУГА.test(текст || '');
}

/**
 * Кто за столом пропал со связи — их имена. Своё место и тех, кто ушёл
 * насовсем или уже выбыл из партии, не считаем: про них разговор другой.
 */
function ктоПропалСоСвязи() {
  const пропали = [];
  for (const место of местаКомпании() || []) {
    if (место.этоЯ || место.ушёл || место.выбыл) continue;
    if (место.наСвязи === false) пропали.push(место.имя);
  }
  return пропали;
}

/**
 * Что сказать про пропавших за столом компанией.
 *
 * Ради чего. У живого игрока за столом на четверых пропала связь: стол встал,
 * строка внизу продолжала уверять «Александра-Мария отбивается…», и только
 * мелкая пометка на плашке говорила «нет связи». Три минуты человек не знал,
 * чего ждёт и не сломалось ли всё. Вдвоём такие слова есть давно («Друг
 * пропал со связи — ждём, партия сохранена»), а компанией их не было вовсе:
 * вести про одного друга здесь нарочно не показываются (см. ВЕСТЬ_ПРО_ДРУГА),
 * и место, которое они освободили, до сих пор пустовало.
 *
 * Говорим три вещи разом: кто пропал, что игра ждёт и что будет дальше.
 * Про «дальше» — правда: сервер через несколько минут сажает на место бота,
 * и партия идёт своим ходом.
 */
function вестиПроПропавших() {
  const пропали = этоКомпания() ? ктоПропалСоСвязи() : [];
  if (пропали.length === 0) return { текст: '', вид: '' };
  /* Имя ставим первым и в исходном виде: имена приходят из Telegram какие
     угодно, и склонять их («нет связи с Аня») игра не умеет и не должна. */
  const полная = пропали.length === 1
    ? пропали[0] + ': нет связи. Ждём. Не вернётся — сядет бот'
    : 'Нет связи: ' + пропали.length + ' ' + словоИгроков(пропали.length) +
      '. Ждём. Не вернутся — сядут боты';
  const короткая = пропали.length === 1
    ? 'Нет связи с игроком. Ждём — потом сядет бот'
    : 'Нет связи с игроками. Ждём — потом сядут боты';
  return { текст: полная, запасной: короткая, вид: 'тревога' };
}

/** Собрать надпись: свой неотправленный ход важнее вестей о друге. */
function нарисоватьСтрокуСвязи() {
  const узел = эл('строка-связи');
  if (!узел) return;
  const пришло = вестьГодитсяСтолу(вестиОСвязи.текст) ? вестиОСвязи : { текст: '', вид: '' };
  /* Своя беда со связью важнее чужой: если пропали мы сами, об этом и пишем.
     Слова про пропавших занимают место, которое компанией всё равно пустует. */
  const вести = пришло.текст ? пришло : вестиПроПропавших();
  const текст = ждёмОтветСервера ? 'Отправляем ход…' : вести.текст;
  const вид = ждёмОтветСервера ? 'ожидание' : вести.вид;
  /* ПОРЯДОК ЗДЕСЬ НАРОЧНЫЙ: сперва пометки, потом текст и замер — та же
     причина, что и в строке подсказки. У спрятанной плашки («скрыт» — это
     display: none) высоты нет вовсе, и мерка ушла бы в запасной путь, в счёт
     знаков: а его порог подбирался для строки подсказки, которая и выше,
     и шире. Плашка связи мельче и режет раньше — на узком телефоне уже
     с семидесяти с небольшим знаков, то есть запас против того порога там
     отрицательный. Сегодня самая длинная надпись короче и не стреляет,
     но полагаться на это нельзя. */
  узел.classList.toggle('скрыт', !текст);
  узел.classList.toggle('связь--тревога', вид === 'тревога');
  узел.classList.toggle('связь--ожидание', вид === 'ожидание');

  /* Длинное имя из Telegram (до шестнадцати знаков) может не влезть: строка
     связи держит неподвижную высоту и режет лишнее так же, как подсказка.
     Спрашиваем ту же мерку — и, если не влезло, говорим то же самое короче,
     без имени: кто именно пропал, видно на плашке в полосе соперников. */
  узел.textContent = текст;
  if (текст && вести.запасной && !влезлоВСтроку(текст, узел)) {
    узел.textContent = вести.запасной;
  }
}

/** Переключить игру в сетевой режим и очистить всё, что осталось от прошлой партии. */
function начатьСетевуюПартию() {
  if (таймер !== null) {
    clearTimeout(таймер);
    таймер = null;
  }
  отменитьПоказИтога();
  убратьСобытие();
  выбраннаяКарта = null;
  итогЗасчитан = false;
  ждёмОтветПроВыход = false;
  ждёмОтветСервера = false;
  /* Отказы прошлой партии к новой отношения не имеют. Иначе первый же отказ
     у друга совпал бы словами с последним отказом в игре с ботом, игра сочла
     бы его повтором и вместо причины объяснила бы подсветку. */
  прошлыеСловаОтказа = '';
  событиеЭтоОтказ = false;
  забытьПропущенныеПодходы();
  /* Раньше здесь окно глухоты обнулялось — единственное место в файле,
     где защита снималась, ничего не давая взамен. Теперь заводим его,
     как и в начале одиночной партии: эту функцию зовут и по нажатию
     («Играть с другом», вход в комнату), и опросом сервера, а разницы
     для игрока нет — первые доли секунды новой партии рука всё равно
     не нужна, зато самопроизвольный первый ход отменить нельзя. */
  рукаГлухаДо = Date.now() + ГЛУХОТА_ПОСЛЕ_КНОПКИ;
  номерПоказанногоСобытия = 0;
  сетьПредупредилаОРазладе = false;
  другУшёлИзПартии = false;
  насВывелиИзПартии = false;
  подсказкаПослеПартии = '';
  // Прошлая партия (хоть с ботом, хоть сетевая) забывается целиком:
  // иначе игра примет первое состояние от сервера за продолжение старой
  // и не покажет, кто ходит первым.
  партия = null;
  режим = РЕЖИМ_СЕТЬ;
  показатьЭкран('экран-игры');
  подобратьРазмерКарты();
}

/* Виды событий, под которые звучит охапка карт: кто-то забирает стол себе.
   Слова берём те же, какими событие называет сервер (поле «видСобытия»):
   «беру» — сказал «Беру», «забрал» — карты и вправду уехали в руку.
   Всё остальное за столом — одна карта, и звук у неё другой. */
const СОБЫТИЯ_ВЗЯТИЯ = ['беру', 'забрал'];

/* События, при которых картами никто не двигал: кто-то ушёл, позвал на
   реванш, поменял правила, посадил бота. Их игра не озвучивает вовсе.

   Почему молчим, а не даём им свой звук. Звук в этой игре значит ровно
   одно: «за столом двинулись карты» — одна карта по столу или охапка
   в руку. Услышав его, человек смотрит на стол и ищет перемену; если
   перемены нет, звук отправил его искать несуществующее. Третий сигнал
   эту беду не лечит: такие события случаются раз в несколько партий,
   редкий звук не запоминается, и человек всё равно пойдёт искать глазами —
   только звуков в игре стало бы на один больше.

   Незамеченным при этом ничего не остаётся: уход друга заканчивает партию
   и приводит плашку итога, а строка события висит до следующего хода
   и не гаснет сама. */
const СОБЫТИЯ_БЕЗ_КАРТ = ['зовёт', 'вошёл', 'вернулся', 'ушёл', 'ушёл-бот',
                          'ушёл-из-комнаты', 'посадили-бота', 'убрали-бота',
                          'пересобрали', 'настройки'];

/**
 * Звук под чужой ход: охапка карт в руке шуршит иначе, чем одна карта по столу.
 *
 * Раньше вид события угадывался по руке: стало карт больше — значит, забрал.
 * Угадывание врало, и врало в худшем месте. Рука растёт не только от забранного
 * стола, но и от добора из колоды: скажешь «Бито», доберёшь две карты — и
 * слышишь звук взятия, хотя ничего не забирал. Звук человек слышит раньше,
 * чем успевает прочитать сообщение, так что первым делом игра сообщала неправду.
 *
 * Теперь берём вид события у сервера — он знает точно, что случилось.
 *
 * Запасной путь оставлен нарочно и убирать его нельзя. Поле «видСобытия»
 * новое, а страница и сервер обновляются порознь: Telegram может держать
 * в памяти старую страницу при новом сервере, а бывает и наоборот — сервер
 * подняли до этой правки и не перезапускали. Не пришло поле — озвучиваем
 * по-старому, по приросту руки: прежнее угадывание всё же лучше тишины.
 */
function озвучитьСетевоеСобытие(былоВРуке, вид) {
  const какоеСобытие = вид ? вид.видСобытия : null;
  if (typeof какоеСобытие === 'string' && какоеСобытие) {
    // Картами не двигали — молчим: см. СОБЫТИЯ_БЕЗ_КАРТ.
    if (СОБЫТИЯ_БЕЗ_КАРТ.indexOf(какоеСобытие) !== -1) return;
    if (СОБЫТИЯ_ВЗЯТИЯ.indexOf(какоеСобытие) !== -1) звукВзятия();
    else звукКарты();
    return;
  }
  if (партия.руки.человек.length > былоВРуке) звукВзятия();
  else звукКарты();
}

/** Новая раздача в той же комнате (реванш): стираем следы прошлой партии. */
function принятьНовуюРаздачу() {
  итогЗасчитан = false;
  ждёмОтветПроВыход = false;
  выбраннаяКарта = null;
  отменитьПоказИтога();       // итог прошлой партии поверх новой раздачи не нужен
  /* И сообщение прошлой партии тоже. Сейчас его всё равно перекрывает
     событие от сервера, но опираться на это нельзя: придёт раздача без
     текста — и над свежими картами повиснет «Вы забрали 6♠, 7♦» из партии,
     которая уже кончилась. Сообщения теперь не гаснут сами, стереть некому. */
  убратьСобытие();
  /* И отказы прошлой раздачи тоже: иначе первый же тычок в новой совпадёт
     словами с последним в прошлой, игра сочтёт его повтором и объяснит
     подсветку вместо причины. Тот же сброс стоит в начале обычной и сетевой
     партии — реванш был единственным краем, где его не было. */
  прошлыеСловаОтказа = '';
  забытьПропущенныеПодходы();   // новая раздача — счёт пропущенных подходов с нуля
  другУшёлИзПартии = false;   // раз играем дальше, друг за столом
  насВывелиИзПартии = false;  // и нас самих сервер снова считает за столом
  подсказкаПослеПартии = '';  // объяснение прошлой концовки к новой раздаче не относится
  показатьЭкран('экран-игры');
  написатьВРамкуИтога('');
}

/**
 * Кто ходит первым — самое первое сообщение партии. За столом компанией
 * «друг» не годится: друзей там до пяти, и надо назвать того самого.
 */
function текстПервогоХода() {
  if (сейчасМойХод()) return 'Вы ходите первым';
  if (этоКомпания()) {
    const кто = имяТого('ходит');
    return кто ? 'Первым ходит ' + кто : 'Первым ходит соперник';
  }
  return 'Первым ходит друг';
}

/**
 * Главная дверь: сюда js/сеть.js отдаёт каждое новое состояние от сервера.
 * Всё, что игра показывает в сетевой партии, проходит через эту функцию.
 */
function показатьСетевоеСостояние(вид) {
  if (!вид) return;
  if (!этоСетеваяИгра()) начатьСетевуюПартию();

  const былоВРуке = партия ? партия.руки.человек.length : 0;
  const былаЗавершена = партия ? партия.завершена : false;
  const первыйПоказ = !партия;

  партия = партияИзВида(вид);
  сверитьОчередьХода(вид);

  /* Карт в руке стало другое число — значит, рука пересобралась, и поднятая
     карта уже не та, что была: игра держит её номером в веере, а сервер
     после подхода раскладывает руку заново. Опускаем карту, чтобы «Перевести»
     и удар по столу не ушли не той картой. */
  if (!первыйПоказ && партия.руки.человек.length !== былоВРуке) выбраннаяКарта = null;

  // Партия была доиграна, а теперь идёт снова — значит, состоялся реванш.
  if (былаЗавершена && !партия.завершена) принятьНовуюРаздачу();

  const номер = целоеИзОтвета(вид.номерСобытия);
  if (первыйПоказ) {
    номерПоказанногоСобытия = номер;
    показатьСобытие(текстПервогоХода(), ПОКАЗ_НАЧАЛА);
  } else if (номер !== номерПоказанногоСобытия) {
    номерПоказанногоСобытия = номер;
    if (вид.событие) показатьСобытие(вид.событие);
    озвучитьСетевоеСобытие(былоВРуке, вид);
  }

  перерисовать();
  /* И строку связи заодно: про пропавших мы узнаём как раз из этого ответа
     (поле «наСвязи» у мест). Часовой связи в js/сеть.js освежает строку сам,
     но раз в несколько секунд, — а новость про пропавшего должна появиться
     сразу, вместе со столом, на котором он замер. */
  нарисоватьСтрокуСвязи();

  if (партия.завершена) подвестиСетевойИтог(вид);
}

/**
 * Итог сетевой партии. В таблицу рекордов он не идёт: там серия побед
 * над ботом определённого уровня, и мешать с ней победы над живым другом
 * нельзя — рекорды перестанут что-либо значить.
 */
function подвестиСетевойИтог(вид) {
  /* Друг мог уйти двумя способами: бросить партию посреди игры или отказаться
     от реванша после честного конца. В обоих случаях звать больше некого,
     поэтому кнопку прячем сразу — плашка итога могла появиться и раньше. */
  другУшёлИзПартии = Boolean(вид.соперникУшёл) || партия.результат === 'друг-ушёл';
  /* А здесь обратный случай: из партии вывели нас самих. Реванш в такой
     комнате сервер уже не даст, поэтому кнопку тоже прячем. */
  насВывелиИзПартии = партия.результат === 'связь-потеряна';
  показатьЭлемент('кнопка-ещё', реваншВозможен());

  if (!итогЗасчитан) {
    итогЗасчитан = true;
    if (партия.результат === 'бот') звукПобеды();
    else if (партия.результат === 'человек') звукПроигрыша();
    // Плашку показываем с задержкой: сначала пусть игрок увидит последний ход.
    отменитьПоказИтога();
    таймерИтога = setTimeout(показатьРезультат, 1200);
  }
  показатьКонцовку(разобратьКонцовку(вид));
}

/**
 * Что показать после партии вдвоём — двумя частями, потому что на экране
 * итога два разных места для текста.
 *
 * «рамка» — та самая рамка под заголовком, где в игре с ботом стоит
 * «Побед подряд: 3». Она крупная и жирная и рассчитана на короткий статус
 * в пару слов, поэтому длинным объяснениям там не место.
 *
 * «подсказка» — вторая фраза обычной подписью под заголовком: там спокойно
 * помещается объяснение, что случилось и что делать дальше.
 */
function разобратьКонцовку(вид) {
  // Нас вывели из партии — звать на реванш нечем и незачем, даже если друг
  // успел позвать нас первым: сервер этой комнаты нас уже не пустит.
  // Что делать дальше, сказано прямо в подписи итога, второй раз не повторяем.
  if (партия && партия.результат === 'связь-потеряна') {
    return { рамка: '', подсказка: '' };
  }
  if (вид.соперникУшёл) {
    // Партия оборвалась на середине: про уход крупно написано в заголовке,
    // поэтому здесь только про то, что делать дальше.
    if (партия && партия.результат === 'друг-ушёл') {
      return {
        рамка: '',
        подсказка: 'Позвать на реванш уже некого — вернитесь в меню и начните новую игру.'
      };
    }
    // А здесь партия доиграна честно, в заголовке стоит «Вы выиграли!»
    // или «Вы проиграли», и про ушедших соперников человек ещё не знает.
    // Сервер поднимает этот признак, только когда из-за стола вышли все,
    // — так и говорим, чтобы за столом на шестерых не звучало «друг».
    return {
      рамка: '',
      подсказка: этоКомпания()
        ? 'Из-за стола все вышли, реванша не будет — вернитесь в меню и начните новую.'
        : 'Друг уже вышел из игры, реванша не будет — вернитесь в меню и начните новую.'
    };
  }
  if (вид.яХочуЕщё) return мыПозвалиНаРеванш();
  if (вид.соперникХочетЕщё) {
    // Признак приходит от сервера, когда играть дальше согласны все, кто
    // остался за столом, — значит в компании зовёт не «друг», а остальные.
    return {
      рамка: этоКомпания()
        ? 'Остальные зовут сыграть ещё — жмите «Ещё партию»'
        : 'Друг зовёт сыграть ещё — жмите «Ещё партию»',
      подсказка: ''
    };
  }
  return {
    рамка: этоКомпания()
      ? 'В таблицу рекордов партии за общим столом не идут'
      : 'В таблицу рекордов партии с другом не идут',
    подсказка: ''
  };
}

/**
 * Мы позвали за столом сыграть ещё и ждём ответа. В рамке — короткое
 * ожидание, само предложение уходит в подпись: вместе они не влезали
 * в рамку и растягивали её на две строки.
 */
function мыПозвалиНаРеванш() {
  return {
    рамка: этоКомпания() ? 'Ждём остальных…' : 'Ждём друга…',
    подсказка: 'Вы предложили сыграть ещё.'
  };
}

/** Разложить концовку по местам: короткое — в рамку, объяснение — в подпись. */
function показатьКонцовку(концовка) {
  подсказкаПослеПартии = концовка.подсказка || '';
  написатьВРамкуИтога(концовка.рамка || '');
  обновитьТекстыИтога();
}

/* Наружу отдаём ровно то, что нужно файлу js/сеть.js, — и ничего больше.
   В Node (сервер и автотесты) окна нет, поэтому мост там не создаётся. */
if (typeof window !== 'undefined') {
  window.ИграПоСети = {
    начать: начатьСетевуюПартию,
    показатьВид: показатьСетевоеСостояние,
    показатьСвязь: показатьСвязь,
    экран: показатьЭкран,
    вМеню: выйтиВМеню,
    идёт: этоСетеваяИгра
  };
}

// В браузере запускаемся сразу, в Node (автотест правил) экрана нет.
if (typeof document !== 'undefined') {
  запустить();
}

// Экспорт для автотеста правил и для сервера игры вдвоём: правила должны
// жить в одном месте, иначе браузер и сервер однажды разойдутся в решениях.
// В браузере переменной module не существует.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    МАСТИ: МАСТИ,
    ДОСТОИНСТВА: ДОСТОИНСТВА,
    ВСЕ_ДОСТОИНСТВА: ВСЕ_ДОСТОИНСТВА,
    СЛОЖНОСТИ: СЛОЖНОСТИ,
    КАРТ_В_РУКЕ: КАРТ_В_РУКЕ,
    МАКС_КАРТ_В_ПОДХОДЕ: МАКС_КАРТ_В_ПОДХОДЕ,
    МИН_ИГРОКОВ: МИН_ИГРОКОВ,
    МАКС_ИГРОКОВ: МАКС_ИГРОКОВ,
    КОЛОДА_36: КОЛОДА_36,
    КОЛОДА_52: КОЛОДА_52,
    собратьКолоду: собратьКолоду,
    создатьПартию: создатьПартию,
    упорядочитьРуку: упорядочитьРуку,
    фаза: фаза,
    ктоХодит: ктоХодит,
    защищается: защищается,
    вИгре: вИгре,
    оставшиеся: оставшиеся,
    партнёр: партнёр,
    следующийВКруге: следующийВКруге,
    подкидывающие: подкидывающие,
    можетПодкидывать: можетПодкидывать,
    /* Нужен серверу: «можетПодкидывать» отвечает и тому, кто уже спасовал, —
       ему слово возвращают, чтобы он закрыл подход. А вот класть карту он
       больше не вправе, и игроку об этом надо сказать честно. */
    ужеСпасовал: ужеСпасовал,
    порядокДобора: порядокДобора,
    бьёт: бьёт,
    неотбитых: неотбитых,
    достоинстваНаСтоле: достоинстваНаСтоле,
    можноПоложить: можноПоложить,
    положитьВАтаку: положитьВАтаку,
    отбить: отбить,
    можноПеревести: можноПеревести,
    перевести: перевести,
    объявитьБеру: объявитьБеру,
    пас: пас,
    завершитьПодход: завершитьПодход,
    ходБота: ходБота,
    /* Не правило, а счёт: чем партия кончилась для человека — победой,
       поражением или ничьёй. Отдаётся наружу нарочно, чтобы проверки
       спрашивали об этом саму игру, а не повторяли её развилку у себя:
       именно на такой второй копии счёт побед компанией и разъехался
       с тем, что человек видел на экране. */
    чемКончилосьДляМеня: чемКончилосьДляМеня,
    /* Тоже не правило, а слова экрана: уместна ли надпись «отбивается ваш
       напарник». Отдаётся наружу по той же причине, что и «чемКончилось»:
       проверке нужно спрашивать игру, а не держать у себя пересказ условия.
       Довод «былЯвПодходе» проверка ведёт сама — он про прошлое, а прошлого
       в самой партии не записано. */
    надписьПроНапарникаУместна: надписьПроНапарникаУместна,
    /* И правило подсчёта заодно: без него проверке пришлось бы пересказывать
       своими словами, что считать подходом и что считать участием, — то есть
       вторая мерка вернулась бы через заднюю дверь. */
    пересчитатьПропущенныеПодходы: пересчитатьПропущенныеПодходы,
    пустойСчётПодходов: пустойСчётПодходов
  };
}
